-- Generated by backend/scripts/generate_scoped_product_tax_migration.py
SET LOCAL ROLE erp_migration_owner;

-- Tenant/product source snapshots retain imported treatment without replacing
-- shared statutory releases. Source facts remain the immutable evidence owner.
ALTER TABLE core.reference_data_releases
  ADD COLUMN org_id uuid REFERENCES core.organizations(id),
  ADD COLUMN source_dataset_id varchar(128);
ALTER TABLE core.reference_data_releases DROP CONSTRAINT reference_data_releases_status_ck;
ALTER TABLE core.reference_data_releases ADD CONSTRAINT reference_data_releases_status_ck
  CHECK (status IN ('staged','active','superseded','source_snapshot'));
ALTER TABLE core.reference_data_releases ADD CONSTRAINT reference_data_releases_source_scope_ck
  CHECK ((org_id IS NULL AND source_dataset_id IS NULL AND status<>'source_snapshot')
    OR (org_id IS NOT NULL AND source_dataset_id IS NOT NULL
      AND dataset_kind='hsn_sac_tax' AND source_authority='legacy_erp_migration'
      AND status IN ('staged','source_snapshot') AND supersedes_release_id IS NULL));
CREATE UNIQUE INDEX reference_data_releases_source_dataset_uq
  ON core.reference_data_releases(org_id,source_dataset_id) WHERE org_id IS NOT NULL;

ALTER TABLE tax.tax_code_versions ADD COLUMN org_id uuid,
  ADD COLUMN product_id uuid, ADD COLUMN source_fact_id uuid;
ALTER TABLE tax.tax_code_versions DROP CONSTRAINT tax_code_versions_code_version_uq;
CREATE UNIQUE INDEX tax_code_versions_code_version_uq ON tax.tax_code_versions(code,version_number)
  WHERE org_id IS NULL;
ALTER TABLE tax.tax_code_versions ADD CONSTRAINT tax_code_versions_source_product_fk
  FOREIGN KEY(org_id,product_id) REFERENCES catalog.products(org_id,id);
ALTER TABLE tax.tax_code_versions ADD CONSTRAINT tax_code_versions_source_fact_fk
  FOREIGN KEY(org_id,source_fact_id) REFERENCES automation.historical_migration_facts(org_id,id);
ALTER TABLE tax.tax_code_versions DROP CONSTRAINT tax_code_versions_status_ck;
ALTER TABLE tax.tax_code_versions ADD CONSTRAINT tax_code_versions_status_ck
  CHECK (status IN ('active','retired','source_snapshot'));
ALTER TABLE tax.tax_code_versions ADD CONSTRAINT tax_code_versions_source_scope_ck
  CHECK ((org_id IS NULL AND product_id IS NULL AND source_fact_id IS NULL AND status<>'source_snapshot')
    OR (org_id IS NOT NULL AND product_id IS NOT NULL AND source_fact_id IS NOT NULL
      AND status='source_snapshot' AND code_kind='hsn' AND default_supply_type='goods'));
CREATE UNIQUE INDEX tax_code_versions_source_product_uq
  ON tax.tax_code_versions(org_id,product_id) WHERE org_id IS NOT NULL;
CREATE UNIQUE INDEX tax_code_versions_source_fact_uq
  ON tax.tax_code_versions(org_id,source_fact_id) WHERE org_id IS NOT NULL;

ALTER POLICY erp_select ON core.reference_data_releases USING
  (org_id IS NULL OR (org_id=erp_security.current_org_id() AND erp_security.current_actor_is_active()));
ALTER POLICY erp_select ON tax.tax_code_versions USING
  (org_id IS NULL OR (org_id=erp_security.current_org_id() AND erp_security.current_actor_is_active()));
ALTER TABLE core.reference_data_releases FORCE ROW LEVEL SECURITY;
ALTER TABLE tax.tax_code_versions FORCE ROW LEVEL SECURITY;
CREATE POLICY source_release_owner ON core.reference_data_releases FOR ALL TO erp_migration_owner
  USING (org_id IS NULL OR (org_id=erp_security.current_org_id() AND erp_security.current_actor_is_active()))
  WITH CHECK (org_id IS NULL OR (org_id=erp_security.current_org_id() AND erp_security.current_actor_is_active()));
CREATE POLICY source_tax_owner ON tax.tax_code_versions FOR ALL TO erp_migration_owner
  USING (org_id IS NULL OR (org_id=erp_security.current_org_id() AND erp_security.current_actor_is_active()))
  WITH CHECK (org_id IS NULL OR (org_id=erp_security.current_org_id() AND erp_security.current_actor_is_active()));


CREATE FUNCTION erp_automation_commands.guard_source_product_tax()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $function$
DECLARE fact automation.historical_migration_facts%ROWTYPE;
  release core.reference_data_releases%ROWTYPE;
BEGIN
  IF TG_OP<>'INSERT' THEN
    IF OLD.org_id IS NOT NULL OR (TG_OP='UPDATE' AND NEW.org_id IS DISTINCT FROM OLD.org_id) THEN
      RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='source product tax snapshots are immutable';
    END IF;
    RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
  END IF;
  IF NEW.org_id IS NULL THEN RETURN NEW; END IF;
  IF NOT erp_regulatory_commands.scope_active('source_product_tax',NEW.product_id) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='source product tax requires reviewed command provenance';
  END IF;
  SELECT * INTO STRICT fact FROM automation.historical_migration_facts
    WHERE org_id=NEW.org_id AND id=NEW.source_fact_id AND source_kind='product' AND selection_state='reviewed';
  SELECT * INTO STRICT release FROM core.reference_data_releases
    WHERE id=NEW.release_id AND org_id=NEW.org_id AND source_dataset_id=fact.dataset_id
      AND source_authority='legacy_erp_migration' AND status='source_snapshot';
  IF NEW.code IS DISTINCT FROM fact.payload->>'hsn_code'
    OR NEW.igst_rate IS DISTINCT FROM (fact.payload->>'gst_rate')::numeric
    OR NEW.effective_from IS DISTINCT FROM fact.event_date OR NEW.effective_to IS NOT NULL
    OR NEW.cgst_rate<>NEW.igst_rate/2 OR NEW.sgst_rate<>NEW.igst_rate/2 OR NEW.cess_rate<>0
    OR NEW.ruleset_version IS DISTINCT FROM release.ruleset_version
    OR NEW.taxability IS DISTINCT FROM (CASE WHEN NEW.igst_rate=0 THEN 'nil_rated' ELSE 'taxable' END)
    OR NOT EXISTS (SELECT 1 FROM catalog.products WHERE org_id=NEW.org_id AND id=NEW.product_id) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='source product tax differs from reviewed evidence';
  END IF;
  RETURN NEW;
END
$function$;
CREATE TRIGGER source_product_tax_guard BEFORE INSERT OR UPDATE OR DELETE ON tax.tax_code_versions
  FOR EACH ROW EXECUTE FUNCTION erp_automation_commands.guard_source_product_tax();

CREATE FUNCTION erp_automation_commands.install_source_product_tax(
  organization_id uuid, reviewed_dataset_id varchar, source_fact_identifier uuid, product_identifier uuid
) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $function$
#variable_conflict use_variable
DECLARE fact automation.historical_migration_facts%ROWTYPE; release_id uuid;
  actor uuid; reviewer uuid; source_hash bytea; snapshot_ruleset text;
  source_count integer; effective_date date; result uuid; rate numeric; code text;
BEGIN
  actor:=erp_core_commands.assert_context(organization_id,'core.organization.manage',NULL::uuid);
  SELECT user_id INTO STRICT reviewer FROM core.memberships WHERE org_id=organization_id AND id=actor;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('source-tax:'||organization_id||':'||reviewed_dataset_id,0));
  SELECT * INTO STRICT fact FROM automation.historical_migration_facts
    WHERE org_id=organization_id AND id=source_fact_identifier AND dataset_id=reviewed_dataset_id
      AND source_kind='product' AND selection_state='reviewed';
  code:=fact.payload->>'hsn_code'; rate:=(fact.payload->>'gst_rate')::numeric;
  IF code !~ '^[0-9]{4,8}$' OR code IS NULL OR rate IS NULL OR rate NOT BETWEEN 0 AND 100
    OR rate<>round(rate,6) OR rate/2<>round(rate/2,6)
    OR fact.event_date IS NULL OR COALESCE((fact.payload->>'hsn_gst_candidate_unique')::boolean,false) IS NOT TRUE THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='source product tax evidence is incomplete';
  END IF;
  SELECT id INTO result FROM tax.tax_code_versions
    WHERE org_id=organization_id AND product_id=product_identifier AND source_fact_id=source_fact_identifier;
  IF result IS NOT NULL THEN RETURN result; END IF;
  SELECT extensions.digest(pg_catalog.convert_to(pg_catalog.string_agg(id::text||':'||encode(row_sha256,'hex'),',' ORDER BY id),'UTF8'),'sha256'),
         count(*),min(event_date)
    INTO source_hash,source_count,effective_date FROM automation.historical_migration_facts
    WHERE org_id=organization_id AND dataset_id=reviewed_dataset_id AND source_kind='product' AND selection_state='reviewed';
  snapshot_ruleset:=pg_catalog.encode(source_hash,'hex');
  SELECT id INTO release_id FROM core.reference_data_releases
    WHERE org_id=organization_id AND source_dataset_id=reviewed_dataset_id AND status='source_snapshot';
  IF release_id IS NULL THEN
    release_id:=pg_catalog.gen_random_uuid();
    INSERT INTO erp_regulatory_commands.command_scopes VALUES
      (pg_catalog.pg_backend_pid(),pg_catalog.txid_current(),'reference_import',release_id);
    INSERT INTO core.reference_data_releases(id,dataset_kind,ruleset_version,source_authority,source_uri,
      source_storage_bucket,source_storage_object_path,source_media_type,source_document_sha256,
      dataset_storage_bucket,dataset_storage_object_path,dataset_sha256,record_count,
      publication_date,effective_from,reviewed_by_user_id,reviewed_at,status,org_id,source_dataset_id)
    VALUES(release_id,'hsn_sac_tax',snapshot_ruleset,'legacy_erp_migration',
      'urn:aasopharma:source-product-tax:'||organization_id||':'||reviewed_dataset_id,
      'database-bound-review','historical/'||organization_id||'/'||reviewed_dataset_id||'/source-facts',
      'application/json',source_hash,'database-bound-review',
      'historical/'||organization_id||'/'||reviewed_dataset_id||'/source-facts',source_hash,source_count,
      effective_date,effective_date,reviewer,transaction_timestamp(),'staged',organization_id,reviewed_dataset_id);
    UPDATE core.reference_data_releases SET status='source_snapshot' WHERE id=release_id;
    DELETE FROM erp_regulatory_commands.command_scopes WHERE backend_pid=pg_backend_pid()
      AND transaction_id=txid_current() AND scope='reference_import' AND target_id=release_id;
  ELSIF NOT EXISTS (SELECT 1 FROM core.reference_data_releases WHERE id=release_id AND dataset_sha256=source_hash) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='reviewed source product set changed after tax assignment';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('tax-code-version:'||code,0));
  result:=pg_catalog.gen_random_uuid();
  INSERT INTO erp_regulatory_commands.command_scopes VALUES
    (pg_backend_pid(),txid_current(),'source_product_tax',product_identifier);
  INSERT INTO tax.tax_code_versions(id,release_id,code,code_kind,version_number,description,effective_from,
    taxability,default_supply_type,cgst_rate,sgst_rate,igst_rate,cess_rate,ruleset_version,status,org_id,product_id,source_fact_id)
  SELECT result,release_id,code,'hsn',1,'Reviewed source product treatment',fact.event_date,
    CASE WHEN rate=0 THEN 'nil_rated' ELSE 'taxable' END,'goods',rate/2,rate/2,rate,0,
    snapshot_ruleset,'source_snapshot',organization_id,product_identifier,source_fact_identifier;
  DELETE FROM erp_regulatory_commands.command_scopes WHERE backend_pid=pg_backend_pid()
    AND transaction_id=txid_current() AND scope='source_product_tax' AND target_id=product_identifier;
  RETURN result;
END
$function$;

CREATE FUNCTION erp_automation_reads.resolve_product_tax(
  organization_id uuid, product_identifier uuid, document_date date
) RETURNS SETOF tax.tax_code_versions LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $function$
#variable_conflict use_variable
DECLARE product catalog.products%ROWTYPE; version tax.tax_code_versions%ROWTYPE; matches integer;
BEGIN
  IF organization_id IS NULL OR organization_id IS DISTINCT FROM erp_security.current_org_id()
     OR NOT erp_security.current_actor_is_active() THEN
    RAISE EXCEPTION 'product tax read requires active organization context' USING ERRCODE='42501';
  END IF;
  IF document_date IS NULL THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='product tax requires document date'; END IF;
  SELECT * INTO product FROM catalog.products WHERE org_id=organization_id AND id=product_identifier;
  IF NOT FOUND OR product.hsn_code IS NULL OR product.hsn_code='0000' OR product.status='draft' THEN RETURN; END IF;
  matches:=0;
  FOR version IN SELECT v.* FROM tax.tax_code_versions v
    JOIN core.reference_data_releases r ON r.id=v.release_id
    JOIN automation.historical_product_bindings b ON b.org_id=v.org_id AND b.product_id=v.product_id AND b.source_fact_id=v.source_fact_id
    WHERE product.setup_review_required AND v.org_id=organization_id AND v.product_id=product_identifier AND v.code=product.hsn_code
      AND v.status='source_snapshot' AND r.status='source_snapshot' AND r.org_id=organization_id
      AND r.source_dataset_id=b.dataset_id AND b.gst_rate=v.igst_rate AND b.hsn_code=v.code
      AND document_date BETWEEN v.effective_from AND COALESCE(v.effective_to,'infinity'::date)
      AND document_date BETWEEN r.effective_from AND COALESCE(r.effective_to,'infinity'::date)
  LOOP
    matches:=matches+1;
    IF matches>1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='source product tax is ambiguous'; END IF;
    RETURN NEXT version;
  END LOOP;
  IF matches=1 THEN RETURN; END IF;
  -- A source assignment must not silently fall back to a different global rate.
  IF product.setup_review_required AND EXISTS(SELECT 1 FROM tax.tax_code_versions WHERE org_id=organization_id AND product_id=product_identifier) THEN RETURN; END IF;
  FOR version IN SELECT v.* FROM tax.tax_code_versions v JOIN core.reference_data_releases r ON r.id=v.release_id
    WHERE v.org_id IS NULL AND v.code=product.hsn_code AND v.code_kind='hsn' AND v.status='active'
      AND r.org_id IS NULL AND r.dataset_kind='hsn_sac_tax' AND r.status='active'
      AND document_date BETWEEN v.effective_from AND COALESCE(v.effective_to,'infinity'::date)
      AND document_date BETWEEN r.effective_from AND COALESCE(r.effective_to,'infinity'::date)
  LOOP
    matches:=matches+1;
    IF matches>1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='product tax is ambiguous'; END IF;
    RETURN NEXT version;
  END LOOP;
END
$function$;

CREATE FUNCTION erp_automation_reads.tax_ruleset_fingerprint(lines jsonb)
RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $function$
DECLARE total integer; matched integer; scoped boolean; rules integer; single_rule text; material text;
BEGIN
  IF jsonb_typeof(lines)<>'array' OR jsonb_array_length(lines)=0 THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='tax fingerprint requires resolved lines'; END IF;
  SELECT count(*) INTO total FROM jsonb_array_elements(lines);
  SELECT count(*),bool_or(v.org_id IS NOT NULL),count(DISTINCT v.ruleset_version),min(v.ruleset_version),
    string_agg(DISTINCT v.id::text||':'||v.ruleset_version,',' ORDER BY v.id::text||':'||v.ruleset_version)
    INTO matched,scoped,rules,single_rule,material
    FROM jsonb_array_elements(lines) l JOIN tax.tax_code_versions v
      ON v.id=(l->>'tax_code_version_id')::uuid AND v.ruleset_version=l->>'ruleset_version'
    WHERE v.org_id IS NULL OR (v.org_id=erp_security.current_org_id() AND erp_security.current_actor_is_active());
  IF matched<>total THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='tax fingerprint references unreviewed or foreign versions'; END IF;
  IF NOT scoped AND rules=1 THEN RETURN single_rule; END IF;
  RETURN encode(extensions.digest(convert_to('aasopharma-tax-set-v1:'||material,'UTF8'),'sha256'),'hex');
END
$function$;

ALTER FUNCTION erp_automation_commands.guard_source_product_tax() OWNER TO erp_migration_owner;
ALTER FUNCTION erp_automation_commands.install_source_product_tax(uuid,varchar,uuid,uuid) OWNER TO erp_migration_owner;
ALTER FUNCTION erp_automation_reads.resolve_product_tax(uuid,uuid,date) OWNER TO erp_migration_owner;
ALTER FUNCTION erp_automation_reads.tax_ruleset_fingerprint(jsonb) OWNER TO erp_migration_owner;
REVOKE ALL ON FUNCTION erp_automation_commands.guard_source_product_tax() FROM PUBLIC,erp_app,erp_runtime;
REVOKE ALL ON FUNCTION erp_automation_commands.install_source_product_tax(uuid,varchar,uuid,uuid) FROM PUBLIC,erp_app,erp_runtime;
REVOKE ALL ON FUNCTION erp_automation_reads.resolve_product_tax(uuid,uuid,date) FROM PUBLIC;
REVOKE ALL ON FUNCTION erp_automation_reads.tax_ruleset_fingerprint(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION erp_automation_reads.resolve_product_tax(uuid,uuid,date),
  erp_automation_reads.tax_ruleset_fingerprint(jsonb) TO erp_app,erp_runtime;

CREATE OR REPLACE FUNCTION erp_automation_commands.promote_historical_product_inventory_batch(
  organization_id uuid,
  reviewed_dataset_id varchar,
  opening_location_id uuid,
  batch_size integer DEFAULT 100
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=''
AS $function$
#variable_conflict use_variable
DECLARE actor_id uuid; product_fact automation.historical_migration_facts%ROWTYPE;
  batch_fact automation.historical_migration_facts%ROWTYPE;
  product_identifier uuid; manufacturer_identifier uuid; tax_release_identifier uuid; tax_version_identifier uuid;
  identity_conversion_id uuid; batch_identifier uuid; line_identifier uuid;
  document_identifier uuid; journal_identifier uuid; event_identifier uuid;
  branch_identifier uuid; inventory_account_id uuid; equity_account_id uuid;
  raw_quantity numeric(20,6); derived_quantity numeric(20,6);
  raw_value numeric(20,2); derived_value numeric(20,2);
  batch_quantity numeric(20,6); batch_value numeric(20,2);
  batch_count integer; line_number integer; matching_count integer;
  matching_product_count integer;
  source_code text; manufacturer_label text; base_uom text; source_hsn text;
  source_gst numeric(9,6); opening_date date; fiscal_year integer;
  product_created integer:=0; zero_clamped integer:=0; openings_posted integer:=0;
  batches_bound integer:=0; products_remaining integer; replayed integer:=0;
  command_time timestamptz:=pg_catalog.transaction_timestamp();
  created_product record; created_manufacturer record;
BEGIN
  actor_id:=erp_core_commands.assert_context(
    organization_id,'core.organization.manage',NULL::uuid
  );
  SET CONSTRAINTS ALL DEFERRED;
  IF NULLIF(pg_catalog.btrim(reviewed_dataset_id),'') IS NULL
     OR batch_size NOT BETWEEN 1 AND 100 THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='historical product cutover request is invalid';
  END IF;
  SELECT location.branch_id INTO STRICT branch_identifier
    FROM inventory.locations location
   WHERE location.org_id=organization_id AND location.id=opening_location_id
     AND location.status='active' AND location.allows_sale
     AND NOT location.allows_negative_stock FOR SHARE;
  IF NOT erp_security.can_access_branch(branch_identifier) THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='opening inventory location is outside branch scope';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    organization_id::text||':historical-product-inventory:'||reviewed_dataset_id,730073
  ));
  inventory_account_id:=erp_commercial_commands.resolve_role_account(
    organization_id,branch_identifier,'inventory_asset','asset','INR',false
  );
  SELECT account.id INTO equity_account_id
    FROM core.settings setting JOIN finance.accounts account
      ON account.org_id=setting.org_id AND account.id=setting.value_text::uuid
   WHERE setting.org_id=organization_id AND setting.namespace='finance.account_roles'
     AND setting.key='opening_balance_equity' AND setting.status='active'
     AND setting.branch_id IS NULL AND account.status='active' AND account.account_type='equity';
  IF equity_account_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='opening balance equity account role is unavailable';
  END IF;

  FOR product_fact IN
    SELECT fact.* FROM automation.historical_migration_facts fact
    LEFT JOIN automation.historical_product_bindings binding
      ON binding.org_id=fact.org_id AND binding.source_fact_id=fact.id
   WHERE fact.org_id=organization_id AND fact.dataset_id=reviewed_dataset_id
     AND fact.source_kind='product' AND fact.selection_state='reviewed'
     AND binding.source_fact_id IS NULL
   ORDER BY fact.id LIMIT batch_size
  LOOP
    source_code:=COALESCE(NULLIF(pg_catalog.btrim(product_fact.product_code),''),
      NULLIF(pg_catalog.btrim(product_fact.payload->>'source_product_code'),''));
    manufacturer_label:=NULLIF(pg_catalog.btrim(product_fact.payload->>'source_company'),'');
    base_uom:=NULLIF(pg_catalog.btrim(product_fact.payload->>'base_uom_code'),'');
    source_hsn:=NULLIF(pg_catalog.btrim(product_fact.payload->>'hsn_code'),'');
    source_gst:=NULLIF(product_fact.payload->>'gst_rate','')::numeric;
    raw_quantity:=COALESCE(product_fact.quantity,0);
    raw_value:=COALESCE(product_fact.inventory_value,0);
    derived_quantity:=greatest(raw_quantity,0);
    derived_value:=CASE WHEN raw_quantity>0 THEN greatest(raw_value,0) ELSE 0 END;
    opening_date:=product_fact.event_date;
    IF source_code IS NULL OR NULLIF(pg_catalog.btrim(product_fact.product_name),'') IS NULL
       OR manufacturer_label IS NULL OR base_uom IS NULL OR source_hsn IS NULL
       OR source_hsn !~ '^[0-9]{4,8}$' OR source_gst IS NULL OR source_gst<0
       OR opening_date IS NULL
       OR COALESCE(product_fact.payload->>'product_kind','medicine')<>'medicine'
       OR COALESCE((product_fact.payload->>'hsn_gst_candidate_unique')::boolean,false) IS DISTINCT FROM true
       OR (raw_quantity>0 AND COALESCE(product_fact.payload->>'batch_reconciliation_status','')<>'exact') THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='reviewed historical product fact is incomplete or ambiguous';
    END IF;
    PERFORM 1 FROM catalog.units_of_measure unit
     WHERE unit.code=base_uom AND unit.status='active' FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE='P0002', MESSAGE='historical product base UOM is unavailable';
    END IF;
    SELECT count(*),(min(party.id::text))::uuid
      INTO matching_count,manufacturer_identifier
      FROM catalog.manufacturers manufacturer JOIN parties.parties party
        ON party.org_id=manufacturer.org_id AND party.id=manufacturer.party_id
     WHERE manufacturer.org_id=organization_id AND manufacturer.status='active'
       AND party.status='active'
       AND pg_catalog.lower(pg_catalog.btrim(party.legal_name))=
           pg_catalog.lower(manufacturer_label);
    IF matching_count>1 THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='historical manufacturer label is ambiguous';
    ELSIF matching_count=0 THEN
      SELECT * INTO STRICT created_manufacturer
        FROM erp_master_commands.create_product_manufacturer(
          organization_id,manufacturer_label,
          extensions.digest(pg_catalog.convert_to(
            reviewed_dataset_id||':manufacturer:'||pg_catalog.lower(manufacturer_label),'UTF8'
          ),'sha256'),command_time+interval '1 hour'
        );
      manufacturer_identifier:=created_manufacturer.manufacturer_party_id;
    END IF;
    IF product_fact.product_id IS NOT NULL THEN
      SELECT product.id INTO product_identifier
        FROM catalog.products product
       WHERE product.org_id=organization_id
         AND product.id=product_fact.product_id
         AND product.status='draft'
         AND pg_catalog.lower(pg_catalog.btrim(product.name))=
             pg_catalog.lower(pg_catalog.btrim(product_fact.product_name))
       FOR UPDATE;
      IF product_identifier IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='23514',
          MESSAGE='reviewed historical product does not identify its existing draft';
      END IF;
    ELSE
      SELECT count(*),(min(product.id::text))::uuid
        INTO matching_product_count,product_identifier
        FROM catalog.products product
       WHERE product.org_id=organization_id AND product.status='draft'
         AND pg_catalog.lower(pg_catalog.btrim(product.name))=
             pg_catalog.lower(pg_catalog.btrim(product_fact.product_name));
      IF matching_product_count>1 THEN
        RAISE EXCEPTION USING ERRCODE='23514',
          MESSAGE='reviewed historical product name matches multiple drafts';
      ELSIF matching_product_count=0 THEN
        SELECT * INTO STRICT created_product
          FROM erp_master_commands.create_product_draft(
            organization_id,product_fact.product_name,NULL,'medicine',
            extensions.digest(pg_catalog.convert_to(
              reviewed_dataset_id||':product:'||source_code,'UTF8'
            ),'sha256'),command_time+interval '1 hour'
          );
        product_identifier:=created_product.product_id;
      END IF;
    END IF;
    IF EXISTS (
      SELECT 1 FROM automation.historical_product_bindings binding
       WHERE binding.org_id=organization_id AND binding.product_id=product_identifier
    ) THEN
      RAISE EXCEPTION USING ERRCODE='23505',
        MESSAGE='historical product draft is already bound to another source fact';
    END IF;
    tax_version_identifier:=erp_automation_commands.install_source_product_tax(
      organization_id,reviewed_dataset_id,product_fact.id,product_identifier);
    SELECT release_id INTO STRICT tax_release_identifier FROM tax.tax_code_versions
      WHERE id=tax_version_identifier;
    identity_conversion_id:=pg_catalog.gen_random_uuid();
    INSERT INTO catalog.uom_conversions(
      org_id,id,product_id,from_uom_code,to_uom_code,multiplier,valid_from,status,
      created_by_membership_id
    ) VALUES (
      organization_id,identity_conversion_id,product_identifier,base_uom,base_uom,1,
      opening_date,'active',actor_id
    );
    INSERT INTO erp_regulatory_commands.command_scopes VALUES (
      pg_catalog.pg_backend_pid(),pg_catalog.txid_current(),'product_activation',
      product_identifier
    );
    UPDATE catalog.products product SET
      manufacturer_party_id=manufacturer_identifier,base_uom_code=base_uom,
      hsn_code=source_hsn,hsn_release_id=tax_release_identifier,
      setup_review_required=true,status='active',updated_at=command_time,
      updated_by_membership_id=actor_id,row_version=row_version+1
     WHERE product.org_id=organization_id AND product.id=product_identifier
       AND product.status='draft';
    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='historical product draft changed before binding';
    END IF;
    INSERT INTO automation.historical_product_bindings(
      org_id,dataset_id,source_product_code,source_fact_id,product_id,
      manufacturer_label,hsn_code,gst_rate,raw_quantity,derived_quantity,
      raw_inventory_value,derived_inventory_value,setup_review_required,
      created_by_membership_id
    ) VALUES (
      organization_id,reviewed_dataset_id,source_code,product_fact.id,product_identifier,
      manufacturer_label,source_hsn,source_gst,raw_quantity,derived_quantity,
      raw_value,derived_value,true,actor_id
    );
    IF NOT EXISTS (
      SELECT 1 FROM automation.historical_product_bindings binding
       WHERE binding.org_id=organization_id AND binding.product_id=product_identifier
         AND binding.source_fact_id=product_fact.id
    ) THEN
      RAISE EXCEPTION USING ERRCODE='23514',
        MESSAGE='historical product activation lacks immutable source binding';
    END IF;
    DELETE FROM erp_regulatory_commands.command_scopes scope
     WHERE scope.backend_pid=pg_catalog.pg_backend_pid()
       AND scope.transaction_id=pg_catalog.txid_current()
       AND scope.scope='product_activation' AND scope.target_id=product_identifier;
    product_created:=product_created+1;
    IF derived_quantity=0 THEN
      IF EXISTS (
        SELECT 1 FROM automation.historical_migration_facts fact
         WHERE fact.org_id=organization_id AND fact.dataset_id=reviewed_dataset_id
           AND fact.source_kind='batch' AND fact.product_code=source_code
           AND fact.selection_state='reviewed' AND COALESCE(fact.quantity,0)>0
      ) THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='zero opening product owns reviewed positive batches'; END IF;
      IF raw_quantity<0 THEN zero_clamped:=zero_clamped+1; END IF;
      CONTINUE;
    END IF;
    IF derived_value<=0 THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='positive historical stock requires positive exact value';
    END IF;
    SELECT count(*),COALESCE(sum(fact.quantity),0),COALESCE(sum(fact.inventory_value),0)
      INTO batch_count,batch_quantity,batch_value
      FROM automation.historical_migration_facts fact
     WHERE fact.org_id=organization_id AND fact.dataset_id=reviewed_dataset_id
       AND fact.source_kind='batch' AND fact.product_code=source_code
       AND fact.selection_state='reviewed';
    IF batch_count=0 OR batch_quantity IS DISTINCT FROM derived_quantity
       OR batch_value IS DISTINCT FROM derived_value THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='historical batch quantity or value does not reconcile exact product opening';
    END IF;
    IF EXISTS (
      SELECT 1 FROM automation.historical_migration_facts fact
       WHERE fact.org_id=organization_id AND fact.dataset_id=reviewed_dataset_id
         AND fact.source_kind='batch' AND fact.product_code=source_code
         AND fact.selection_state='reviewed'
         AND (COALESCE(fact.quantity,0)<=0 OR COALESCE(fact.inventory_value,0)<=0
           OR fact.event_date IS NULL OR fact.event_date<=opening_date
           OR NULLIF(pg_catalog.btrim(fact.batch_number),'') IS NULL
           OR NULLIF(fact.payload->>'mrp','')::numeric<=0
           OR NULLIF(fact.payload->>'unit_cost','')::numeric<0
           OR fact.payload->>'base_uom_code' IS DISTINCT FROM base_uom
           OR fact.payload->>'mrp_uom_code' IS DISTINCT FROM base_uom
           OR NULLIF(fact.payload->>'mrp_uom_multiplier','')::numeric IS DISTINCT FROM 1
           OR pg_catalog.round(fact.quantity*NULLIF(fact.payload->>'unit_cost','')::numeric,2)
                IS DISTINCT FROM fact.inventory_value)
    ) OR EXISTS (
      SELECT 1 FROM automation.historical_migration_facts fact
       WHERE fact.org_id=organization_id AND fact.dataset_id=reviewed_dataset_id
         AND fact.source_kind='batch' AND fact.product_code=source_code
         AND fact.selection_state='reviewed'
       GROUP BY pg_catalog.lower(pg_catalog.btrim(fact.batch_number))
      HAVING count(DISTINCT ROW(fact.event_date,fact.payload->>'mrp',
        fact.payload->>'base_uom_code',fact.payload->>'mrp_uom_code',
        fact.payload->>'mrp_uom_multiplier'))<>1
    ) THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='historical batch is expired, incomplete, negative, or conflicting';
    END IF;
    document_identifier:=pg_catalog.gen_random_uuid();
    journal_identifier:=pg_catalog.gen_random_uuid();
    event_identifier:=pg_catalog.gen_random_uuid();
    fiscal_year:=CASE WHEN pg_catalog.date_part('month',opening_date)>=4
      THEN pg_catalog.date_part('year',opening_date)::integer
      ELSE pg_catalog.date_part('year',opening_date)::integer-1 END;
    INSERT INTO inventory.inventory_documents(
      org_id,id,branch_id,physical_movement_required,document_type,document_number,
      fiscal_year,document_date,status,reason_code,currency_code,costing_method_snapshot,
      total_abs_base_quantity,total_value,approved_at,approved_by_membership_id,
      created_by_membership_id,updated_by_membership_id
    ) VALUES (
      organization_id,document_identifier,branch_identifier,false,'opening_receipt',
      pg_catalog.left('MIG-OPEN-'||pg_catalog.replace(product_fact.id::text,'-',''),64),
      fiscal_year,opening_date,'approved','historical_marg_opening','INR',
      'moving_weighted_average',derived_quantity,derived_value,command_time,actor_id,
      actor_id,actor_id
    );
    line_number:=0;
    FOR batch_fact IN
      SELECT fact.* FROM automation.historical_migration_facts fact
       WHERE fact.org_id=organization_id AND fact.dataset_id=reviewed_dataset_id
         AND fact.source_kind='batch' AND fact.product_code=source_code
         AND fact.selection_state='reviewed'
       ORDER BY pg_catalog.lower(pg_catalog.btrim(fact.batch_number)),fact.id
    LOOP
      SELECT binding.batch_id INTO batch_identifier
        FROM automation.historical_batch_bindings binding
        JOIN automation.historical_migration_facts prior
          ON prior.org_id=binding.org_id AND prior.id=binding.source_batch_fact_id
       WHERE binding.org_id=organization_id AND binding.dataset_id=reviewed_dataset_id
         AND binding.source_product_code=source_code
         AND pg_catalog.lower(pg_catalog.btrim(prior.batch_number))=
             pg_catalog.lower(pg_catalog.btrim(batch_fact.batch_number))
       LIMIT 1;
      IF batch_identifier IS NULL THEN
        batch_identifier:=pg_catalog.gen_random_uuid();
        INSERT INTO inventory.batches(
          org_id,id,product_id,batch_number,lot_kind,manufactured_on,expires_on,mrp,
          mrp_uom_conversion_id,status,released_at,released_by_membership_id,
          created_by_membership_id,updated_by_membership_id
        ) VALUES (
          organization_id,batch_identifier,product_identifier,
          pg_catalog.btrim(batch_fact.batch_number),'manufacturer_batch',
          NULLIF(batch_fact.payload->>'manufactured_on','')::date,batch_fact.event_date,
          (batch_fact.payload->>'mrp')::numeric,identity_conversion_id,'quarantined',NULL,
          NULL,actor_id,actor_id
        );
      END IF;
      line_number:=line_number+1;
      line_identifier:=pg_catalog.gen_random_uuid();
      INSERT INTO inventory.inventory_document_lines(
        org_id,id,inventory_document_id,line_number,movement_kind,product_id,batch_id,
        uom_code,entered_quantity,base_quantity,to_location_id,unit_cost,extended_cost,
        created_by_membership_id
      ) VALUES (
        organization_id,line_identifier,document_identifier,line_number,'receipt',
        product_identifier,batch_identifier,base_uom,batch_fact.quantity,batch_fact.quantity,
        opening_location_id,(batch_fact.payload->>'unit_cost')::numeric,
        batch_fact.inventory_value,actor_id
      );
      INSERT INTO automation.historical_batch_bindings(
        org_id,dataset_id,source_batch_fact_id,source_product_code,batch_id,
        inventory_document_line_id,created_by_membership_id
      ) VALUES (
        organization_id,reviewed_dataset_id,batch_fact.id,source_code,batch_identifier,
        line_identifier,actor_id
      );
      batches_bound:=batches_bound+1;
    END LOOP;
    PERFORM erp_trade_commands.post_locked_document(
      organization_id,document_identifier,actor_id
    );
    SET CONSTRAINTS ALL IMMEDIATE;
    SET CONSTRAINTS ALL DEFERRED;
    INSERT INTO erp_trade_commands.command_scopes(
      backend_pid,transaction_id,scope,org_id,entity_id
    ) SELECT pg_catalog.pg_backend_pid(),pg_catalog.txid_current(),
      'goods_receipt_batch_release',binding.org_id,binding.batch_id
      FROM automation.historical_batch_bindings binding
     WHERE binding.org_id=organization_id AND binding.dataset_id=reviewed_dataset_id
       AND binding.source_product_code=source_code
    ON CONFLICT DO NOTHING;
    UPDATE inventory.batches batch SET
      status='released',released_at=command_time,released_by_membership_id=actor_id,
      updated_at=command_time,updated_by_membership_id=actor_id,
      row_version=batch.row_version+1
      FROM erp_trade_commands.command_scopes scope
     WHERE scope.backend_pid=pg_catalog.pg_backend_pid()
       AND scope.transaction_id=pg_catalog.txid_current()
       AND scope.scope='goods_receipt_batch_release'
       AND scope.org_id=organization_id
       AND batch.org_id=scope.org_id AND batch.id=scope.entity_id
       AND batch.status='quarantined';
    SET CONSTRAINTS ALL IMMEDIATE;
    SET CONSTRAINTS ALL DEFERRED;
    DELETE FROM erp_trade_commands.command_scopes scope
     WHERE scope.backend_pid=pg_catalog.pg_backend_pid()
       AND scope.transaction_id=pg_catalog.txid_current()
       AND scope.scope='goods_receipt_batch_release'
       AND scope.org_id=organization_id;
    INSERT INTO finance.journal_entries(
      org_id,id,journal_number,posting_date,description,transaction_currency,
      functional_currency,fx_rate,transaction_debit_total,transaction_credit_total,
      functional_debit_total,functional_credit_total,status,
      created_by_membership_id,updated_by_membership_id
    ) VALUES (
      organization_id,journal_identifier,
      pg_catalog.left('MIG-INV-'||pg_catalog.replace(product_fact.id::text,'-',''),64),
      opening_date,'Historical MARG opening inventory '||source_code,'INR','INR',1,
      derived_value,derived_value,derived_value,derived_value,'draft',actor_id,actor_id
    );
    INSERT INTO finance.journal_lines(
      org_id,id,journal_entry_id,line_number,account_id,branch_id,description,
      transaction_debit,transaction_credit,functional_debit,functional_credit,
      created_by_membership_id
    ) VALUES
    (organization_id,pg_catalog.gen_random_uuid(),journal_identifier,1,inventory_account_id,
      branch_identifier,'Historical opening inventory '||source_code,
      derived_value,0,derived_value,0,actor_id),
    (organization_id,pg_catalog.gen_random_uuid(),journal_identifier,2,equity_account_id,
      branch_identifier,'Historical opening inventory offset '||source_code,
      0,derived_value,0,derived_value,actor_id);
    SET CONSTRAINTS ALL IMMEDIATE;
    SET CONSTRAINTS ALL DEFERRED;
    UPDATE finance.journal_entries SET status='posted',posted_at=command_time,
      posted_by_membership_id=actor_id,updated_at=command_time,
      updated_by_membership_id=actor_id,row_version=row_version+1
     WHERE org_id=organization_id AND id=journal_identifier AND status='draft';
    INSERT INTO finance.accounting_events(
      org_id,id,event_type,inventory_document_id,journal_entry_id,occurred_at,
      source_posted_at,created_by_membership_id
    ) SELECT organization_id,event_identifier,'inventory_valuation',document_identifier,
      journal_identifier,command_time,document.posted_at,actor_id
      FROM inventory.inventory_documents document
     WHERE document.org_id=organization_id AND document.id=document_identifier
       AND document.status='posted';
    INSERT INTO automation.historical_inventory_openings(
      org_id,dataset_id,source_product_fact_id,product_id,branch_id,location_id,
      inventory_document_id,journal_entry_id,accounting_event_id,quantity,
      inventory_value,created_by_membership_id
    ) VALUES (
      organization_id,reviewed_dataset_id,product_fact.id,product_identifier,
      branch_identifier,opening_location_id,document_identifier,journal_identifier,
      event_identifier,derived_quantity,derived_value,actor_id
    );
    openings_posted:=openings_posted+1;
  END LOOP;
  SELECT count(*) INTO products_remaining
    FROM automation.historical_migration_facts fact
    LEFT JOIN automation.historical_product_bindings binding
      ON binding.org_id=fact.org_id AND binding.source_fact_id=fact.id
   WHERE fact.org_id=organization_id AND fact.dataset_id=reviewed_dataset_id
     AND fact.source_kind='product' AND fact.selection_state='reviewed'
     AND binding.source_fact_id IS NULL;
  SET CONSTRAINTS ALL IMMEDIATE;
  RETURN pg_catalog.jsonb_build_object(
    'products_created',product_created,'products_replayed',replayed,
    'products_remaining',products_remaining,'negative_products_clamped',zero_clamped,
    'batches_bound',batches_bound,'openings_posted',openings_posted,
    'complete',products_remaining=0
  );
END
$function$;

CREATE OR REPLACE FUNCTION "erp_regulatory_commands"."product_ready"(organization_id uuid, product_id uuid, effective_on date)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
DECLARE product catalog.products%ROWTYPE; treatment tax.tax_code_versions%ROWTYPE;
BEGIN
    SELECT * INTO product FROM catalog.products p
      WHERE p.org_id=organization_id AND p.id=product_id AND p.status='active';
    IF NOT FOUND THEN RETURN false; END IF;
    SELECT * INTO treatment FROM erp_automation_reads.resolve_product_tax(organization_id,product_id,effective_on);
    IF NOT FOUND OR treatment.default_supply_type<>'goods' THEN RETURN false; END IF;
    -- The resolver permits a source snapshot only for the immutable-bound,
    -- explicitly review-required migration state. It is not ingredient authority.
    IF treatment.status='source_snapshot' OR product.product_kind<>'medicine' THEN RETURN true; END IF;
    PERFORM erp_regulatory_commands.assert_reference_readiness(effective_on);
    RETURN EXISTS (SELECT 1 FROM core.reference_data_releases AS release
       WHERE release.dataset_kind='ingredient_classification' AND release.status='active'
         AND release.ruleset_version=product.regulatory_ruleset_version
         AND effective_on BETWEEN release.effective_from AND COALESCE(release.effective_to,'infinity'::date));
END
$function$;

CREATE OR REPLACE FUNCTION "erp_regulatory_commands"."guard_release"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
BEGIN
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='reviewed reference releases are retained';
  END IF;
  IF TG_OP='INSERT' THEN
    IF NEW.status<>'staged' OR NOT erp_regulatory_commands.scope_active('reference_import',NEW.id) THEN
      RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='reference release requires verified import provenance';
    END IF;
    RETURN NEW;
  END IF;
  IF (to_jsonb(NEW)-'status') IS DISTINCT FROM (to_jsonb(OLD)-'status')
    OR NOT erp_regulatory_commands.scope_active('reference_import',OLD.id)
    OR NOT (((to_jsonb(OLD)->>'org_id') IS NULL AND ((OLD.status='staged' AND NEW.status='active')
                  OR (OLD.status='active' AND NEW.status='superseded')))
         OR ((to_jsonb(OLD)->>'org_id') IS NOT NULL AND OLD.status='staged' AND NEW.status='source_snapshot')) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='invalid or unproven reference release transition';
  END IF;
  RETURN NEW;
END
$function$;

CREATE OR REPLACE FUNCTION "erp_regulatory_commands"."guard_tax_code_version"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
BEGIN
  IF TG_OP='INSERT' THEN
    IF NOT (((to_jsonb(NEW)->>'org_id') IS NULL AND NEW.status='active'
          AND erp_regulatory_commands.scope_active('reference_import',NEW.release_id))
        OR ((to_jsonb(NEW)->>'org_id') IS NOT NULL AND NEW.status='source_snapshot'
          AND erp_regulatory_commands.scope_active('source_product_tax',(to_jsonb(NEW)->>'product_id')::uuid))) THEN
      RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='tax code version requires reviewed import provenance';
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP='DELETE' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='deployed tax code versions are retained'; END IF;
  IF (to_jsonb(OLD)->>'org_id') IS NOT NULL OR (to_jsonb(NEW)-'status') IS DISTINCT FROM (to_jsonb(OLD)-'status')
    OR OLD.status<>'active' OR NEW.status<>'retired'
    OR NOT erp_regulatory_commands.scope_active('reference_import',OLD.release_id) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='tax code identity, treatment and provenance are immutable';
  END IF;
  RETURN NEW;
END
$function$;

CREATE OR REPLACE FUNCTION "erp_regulatory_commands"."guard_product_use"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
BEGIN
    IF NEW.product_id IS NULL THEN RETURN NEW; END IF;
    IF NOT erp_regulatory_commands.product_ready(NEW.org_id,NEW.product_id,
          erp_core_commands.current_organization_business_date()) THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='sale or receipt requires an active product with current reviewed treatment';
    END IF;
    RETURN NEW;
END
$function$;

CREATE OR REPLACE FUNCTION "erp_automation_commands"."resolve_sales_order_prepare"(organization_id uuid, membership_id uuid, auth_user_id uuid, application_user_id uuid, grant_id uuid, caller_client_id varchar, request_document jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
DECLARE
    branch_id uuid := NULLIF(request_document->>'branch_id','')::uuid;
    customer_account_id uuid := NULLIF(request_document->>'customer_account_id','')::uuid;
    delivery_address_id uuid := NULLIF(request_document->>'delivery_address_id','')::uuid;
    delivery_address_row_version bigint := NULLIF(request_document->>'delivery_address_row_version','')::bigint;
    customer_party_id uuid;
    order_date date := NULLIF(request_document->>'order_date','')::date;
    requested_delivery_date date := NULLIF(request_document->>'requested_delivery_date','')::date;
    zero_rated_payment_mode text := request_document->>'zero_rated_payment_mode';
    supply_type text;
    customer_account parties.customer_accounts%ROWTYPE;
    customer_registration parties.tax_registrations%ROWTYPE;
    billing_address parties.addresses%ROWTYPE;
    shipping_address parties.addresses%ROWTYPE;
    branch core.branches%ROWTYPE;
    line_count integer;
    resolved_count integer;
    ruleset_count integer;
    address_count integer;
    registration_count integer;
    resolved_lines jsonb;
BEGIN
    IF SESSION_USER<>'erp_calculator' OR organization_id IS NULL OR membership_id IS NULL
       OR auth_user_id IS NULL OR application_user_id IS NULL OR grant_id IS NULL
       OR branch_id IS NULL OR customer_account_id IS NULL OR order_date IS NULL
       OR requested_delivery_date IS NULL
       OR delivery_address_id IS NULL OR delivery_address_row_version IS NULL
       OR delivery_address_row_version<1 OR request_document?'place_of_supply_state_code'
       OR request_document?'shipping_address_id'
       OR zero_rated_payment_mode NOT IN ('not_applicable','without_payment','with_igst')
       OR pg_catalog.jsonb_typeof(request_document)<>'object'
       OR pg_catalog.jsonb_typeof(request_document->'lines')<>'array'
       OR pg_catalog.jsonb_array_length(request_document->'lines') NOT BETWEEN 1 AND 500 THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='sales-order resolve input is incomplete';
    END IF;
    IF requested_delivery_date<order_date THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='sales-order requested delivery date precedes order date';
    END IF;
    PERFORM 1
      FROM core.memberships AS membership
      JOIN core.users AS user_row ON user_row.id=membership.user_id
      JOIN core.organizations AS organization ON organization.id=membership.org_id
      JOIN automation.agent_grants AS grant_row
        ON grant_row.org_id=membership.org_id
       AND grant_row.subject_membership_id=membership.id
      JOIN automation.agent_grant_capabilities AS capability
        ON capability.org_id=grant_row.org_id AND capability.agent_grant_id=grant_row.id
     WHERE membership.org_id=organization_id AND membership.id=membership_id
       AND membership.user_id=application_user_id AND membership.status='active'
       AND user_row.auth_user_id=auth_user_id AND user_row.status='active'
       AND organization.status='active' AND grant_row.id=grant_id
       AND grant_row.client_id=caller_client_id AND grant_row.status='active'
       AND grant_row.expires_at>pg_catalog.transaction_timestamp()
       AND (grant_row.branch_id IS NULL OR grant_row.branch_id=branch_id)
       AND capability.capability_code='sales.order.prepare'
       AND capability.operation_mode='write' AND capability.status='active';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='sales-order delegated authority is inactive';
    END IF;
    PERFORM erp_security.activate_context(auth_user_id,organization_id);
    IF erp_security.current_membership_id() IS DISTINCT FROM membership_id THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='sales-order verified auth context resolved a different membership';
    END IF;
    IF order_date>"erp_core_commands"."current_organization_business_date"() THEN
        RAISE EXCEPTION USING ERRCODE='22007', MESSAGE='sales order date cannot be in the future';
    END IF;
    IF erp_security.can_access_branch(branch_id) IS DISTINCT FROM true
       OR erp_security.has_permission('sales.order.create',branch_id) IS DISTINCT FROM true
       OR erp_security.has_permission('automation.command.execute',branch_id) IS DISTINCT FROM true THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='sales-order branch permission is inactive';
    END IF;
    SELECT * INTO STRICT branch FROM core.branches
     WHERE org_id=organization_id AND id=branch_id AND status='active' FOR SHARE;
    SELECT * INTO STRICT customer_account FROM parties.customer_accounts
     WHERE org_id=organization_id AND id=customer_account_id AND status='active' FOR SHARE;
    customer_party_id:=customer_account.party_id;
    SELECT count(*) INTO address_count FROM parties.addresses
     WHERE org_id=organization_id AND party_id=customer_party_id
       AND address_kind='billing' AND is_primary AND status='active'
       AND valid_from<=order_date AND (valid_until IS NULL OR valid_until>=order_date);
    IF address_count>1 THEN
        RAISE EXCEPTION USING ERRCODE='21000', MESSAGE='customer has ambiguous effective primary billing addresses';
    ELSIF address_count=1 THEN
        SELECT * INTO STRICT billing_address FROM parties.addresses
         WHERE org_id=organization_id AND party_id=customer_party_id
           AND address_kind='billing' AND is_primary AND status='active'
           AND valid_from<=order_date AND (valid_until IS NULL OR valid_until>=order_date) FOR SHARE;
    ELSE
        SELECT * INTO STRICT billing_address FROM parties.addresses
         WHERE org_id=organization_id AND party_id=customer_party_id
           AND address_kind='registered' AND is_primary AND status='active'
           AND valid_from<=order_date AND (valid_until IS NULL OR valid_until>=order_date) FOR SHARE;
    END IF;
    SELECT * INTO STRICT shipping_address FROM parties.addresses
     WHERE org_id=organization_id AND id=delivery_address_id
       AND party_id=customer_party_id
       AND address_kind IN ('registered','billing','shipping') AND status='active'
       AND row_version=delivery_address_row_version
       AND valid_from<=order_date AND (valid_until IS NULL OR valid_until>=order_date)
     FOR SHARE;
    IF shipping_address.country_code<>'IN' OR shipping_address.state_code!~'^[0-9]{2}$'
       OR shipping_address.postal_code!~'^[0-9]{6}$' THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='selected delivery address lacks exact supported India address facts';
    END IF;

    SELECT count(*) INTO registration_count FROM parties.tax_registrations
     WHERE org_id=organization_id AND party_id=customer_party_id
       AND registration_type='GSTIN' AND status='active'
       AND (valid_from IS NULL OR valid_from<=order_date)
       AND (valid_until IS NULL OR valid_until>=order_date);
    IF registration_count>1 THEN
        RAISE EXCEPTION USING ERRCODE='21000', MESSAGE='customer has ambiguous effective active GST registrations';
    ELSIF registration_count=1 THEN
        SELECT * INTO STRICT customer_registration FROM parties.tax_registrations
         WHERE org_id=organization_id AND party_id=customer_party_id
           AND registration_type='GSTIN' AND status='active'
           AND (valid_from IS NULL OR valid_from<=order_date)
           AND (valid_until IS NULL OR valid_until>=order_date) FOR SHARE;
    END IF;
    supply_type:=CASE
      WHEN registration_count=1 AND customer_registration.taxpayer_type IN ('sez_unit','sez_developer') THEN 'sez'
      WHEN branch.state_code=shipping_address.state_code THEN 'intra_state'
      ELSE 'inter_state'
    END;
    IF (supply_type='sez' AND zero_rated_payment_mode NOT IN ('without_payment','with_igst'))
       OR (supply_type<>'sez' AND zero_rated_payment_mode<>'not_applicable') THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='zero-rated payment mode does not match exact customer GST status';
    END IF;

    line_count:=pg_catalog.jsonb_array_length(request_document->'lines')
      +pg_catalog.jsonb_array_length(COALESCE(request_document->'charge_lines','[]'::jsonb));
    WITH requested_products AS (
        SELECT item.value AS line, item.ordinality::integer AS line_number
          FROM pg_catalog.jsonb_array_elements(request_document->'lines') WITH ORDINALITY AS item(value,ordinality)
    ), resolved_products AS (
        SELECT requested.line_number,tax_version.ruleset_version,
               pg_catalog.jsonb_build_object(
                 'line_number',requested.line_number,'line_kind','product',
                 'line_id',NULLIF(requested.line->>'line_id','')::uuid,
                 'product_id',product.id,'product_row_version',product.row_version,
                 'hsn_code',product.hsn_code,'uom_conversion_id',conversion.id,
                 'uom_code',conversion.from_uom_code,'to_uom_code',conversion.to_uom_code,
                 'multiplier',conversion.multiplier::text,
                 'uom_valid_from',conversion.valid_from,'uom_valid_until',conversion.valid_until,
                 'tax_code_version_id',tax_version.id,'tax_version_number',tax_version.version_number,
                 'tax_effective_from',tax_version.effective_from,'tax_effective_to',tax_version.effective_to,
                 'tax_release_id',tax_release.id,'tax_release_ruleset_version',tax_release.ruleset_version,
                 'taxability',CASE WHEN supply_type='sez' THEN 'zero_rated' ELSE tax_version.taxability END,
                 'gst_rate',CASE
                   WHEN supply_type='sez' AND zero_rated_payment_mode='without_payment' THEN '0'
                   WHEN supply_type='sez' THEN tax_version.igst_rate::text
                   WHEN tax_version.taxability='taxable' THEN tax_version.igst_rate::text ELSE '0' END,
                 'cess_rate',CASE WHEN supply_type<>'sez' AND tax_version.taxability='taxable'
                                  THEN tax_version.cess_rate::text ELSE '0' END,
                 'ruleset_version',tax_version.ruleset_version,'input',requested.line
               ) AS resolved_line
          FROM requested_products AS requested
          JOIN catalog.products AS product
            ON product.org_id=organization_id
           AND product.id=NULLIF(requested.line->>'product_id','')::uuid
           AND product.status='active'
          JOIN catalog.uom_conversions AS conversion
            ON conversion.org_id=product.org_id
           AND conversion.id=NULLIF(requested.line->>'uom_conversion_id','')::uuid
           AND conversion.product_id=product.id AND conversion.status='active'
           AND conversion.to_uom_code=product.base_uom_code
           AND conversion.valid_from<=order_date
           AND (conversion.valid_until IS NULL OR conversion.valid_until>=order_date)
          JOIN LATERAL erp_automation_reads.resolve_product_tax(organization_id,product.id,order_date) AS tax_version ON true
          JOIN core.reference_data_releases AS tax_release
            ON tax_release.id=tax_version.release_id AND tax_release.dataset_kind='hsn_sac_tax'
           AND tax_release.status IN ('active','source_snapshot') AND tax_release.effective_from<=order_date
           AND (tax_release.effective_to IS NULL OR tax_release.effective_to>=order_date)
         FOR SHARE OF product,conversion,tax_release
    ), requested_charges AS (
        SELECT item.value AS line,
               pg_catalog.jsonb_array_length(request_document->'lines')+item.ordinality::integer AS line_number
          FROM pg_catalog.jsonb_array_elements(
                 COALESCE(request_document->'charge_lines','[]'::jsonb)
               ) WITH ORDINALITY AS item(value,ordinality)
    ), resolved_charges AS (
        SELECT requested.line_number,tax_version.ruleset_version,
               pg_catalog.jsonb_build_object(
                 'line_number',requested.line_number,'line_kind','charge',
                 'line_id',NULLIF(requested.line->>'line_id','')::uuid,
                 'charge_code',profile.charge_code,
                 'charge_tax_profile_id',profile.id,'charge_tax_profile_row_version',profile.row_version,
                 'charge_tax_profile_effective_from',profile.effective_from,
                 'charge_tax_profile_effective_to',profile.effective_to,
                 'sac_code',tax_version.code,'tax_code_version_id',tax_version.id,
                 'tax_version_number',tax_version.version_number,
                 'tax_effective_from',tax_version.effective_from,'tax_effective_to',tax_version.effective_to,
                 'tax_release_id',tax_release.id,'tax_release_ruleset_version',tax_release.ruleset_version,
                 'taxability',CASE WHEN supply_type='sez' THEN 'zero_rated' ELSE tax_version.taxability END,
                 'gst_rate',CASE
                   WHEN supply_type='sez' AND zero_rated_payment_mode='without_payment' THEN '0'
                   WHEN supply_type='sez' THEN tax_version.igst_rate::text
                   WHEN tax_version.taxability='taxable' THEN tax_version.igst_rate::text ELSE '0' END,
                 'cess_rate',CASE WHEN supply_type<>'sez' AND tax_version.taxability='taxable'
                                  THEN tax_version.cess_rate::text ELSE '0' END,
                 'ruleset_version',tax_version.ruleset_version,'input',requested.line
               ) AS resolved_line
          FROM requested_charges AS requested
          JOIN catalog.commercial_charge_tax_profiles AS profile
            ON profile.org_id=organization_id AND profile.direction='sales'
           AND profile.charge_code=requested.line->>'charge_code' AND profile.status='active'
           AND profile.effective_from<=order_date
           AND (profile.effective_to IS NULL OR profile.effective_to>=order_date)
          JOIN tax.tax_code_versions AS tax_version
            ON tax_version.id=profile.tax_code_version_id AND tax_version.code_kind='sac'
           AND tax_version.status='active' AND tax_version.effective_from<=order_date
           AND (tax_version.effective_to IS NULL OR tax_version.effective_to>=order_date)
          JOIN core.reference_data_releases AS tax_release
            ON tax_release.id=tax_version.release_id AND tax_release.dataset_kind='hsn_sac_tax'
           AND tax_release.status='active' AND tax_release.effective_from<=order_date
           AND (tax_release.effective_to IS NULL OR tax_release.effective_to>=order_date)
         FOR SHARE OF profile,tax_version,tax_release
    ), resolved AS (
        SELECT * FROM resolved_products UNION ALL SELECT * FROM resolved_charges
    )
    SELECT count(*),count(DISTINCT ruleset_version),
           pg_catalog.jsonb_agg(resolved_line ORDER BY line_number)
      INTO resolved_count,ruleset_count,resolved_lines FROM resolved;
    IF resolved_count<>line_count THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='sales-order product, charge, UOM, or effective tax resolution is not exact';
    END IF;
    RETURN pg_catalog.jsonb_build_object(
        'branch_id',branch.id,'branch_row_version',branch.row_version,
        'branch_state_code',branch.state_code,
        'supply_type',supply_type,'zero_rated_payment_mode',zero_rated_payment_mode,
        'customer_party_id',customer_party_id,'customer_account_id',customer_account.id,
        'customer_account_row_version',customer_account.row_version,
        'customer_tax_registration_id',CASE WHEN registration_count=1 THEN customer_registration.id ELSE NULL END,
        'customer_tax_registration_row_version',CASE WHEN registration_count=1 THEN customer_registration.row_version ELSE NULL END,
        'customer_taxpayer_type',CASE WHEN registration_count=1 THEN customer_registration.taxpayer_type ELSE NULL END,
        'billing_address_id',billing_address.id,'billing_address_row_version',billing_address.row_version,
        'shipping_address_id',shipping_address.id,'shipping_address_row_version',shipping_address.row_version,
        'shipping_state_code',shipping_address.state_code,
        'order_date',order_date,'requested_delivery_date',requested_delivery_date,
        'lines',resolved_lines,
        'ruleset_version',erp_automation_reads.tax_ruleset_fingerprint(resolved_lines)
    );
END
$function$;

CREATE OR REPLACE FUNCTION "erp_automation_commands"."resolve_purchase_order_prepare"(organization_id uuid, membership_id uuid, auth_user_id uuid, application_user_id uuid, grant_id uuid, caller_client_id varchar, purchase_order_id uuid, request_document jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
DECLARE branch_id uuid:=NULLIF(request_document->>'branch_id','')::uuid;
        supplier_account_id uuid:=NULLIF(request_document->>'supplier_account_id','')::uuid;
        order_date date:=NULLIF(request_document->>'order_date','')::date;
        expected_on date:=NULLIF(request_document->>'expected_on','')::date;
        organization core.organizations%ROWTYPE; branch core.branches%ROWTYPE;
        buyer_registration tax.registrations%ROWTYPE;
        buyer_registration_branch tax.registration_branches%ROWTYPE;
        supplier parties.supplier_accounts%ROWTYPE; supplier_party parties.parties%ROWTYPE;
        supplier_address parties.addresses%ROWTYPE;
        supplier_registration parties.tax_registrations%ROWTYPE;
        product catalog.products%ROWTYPE; conversion catalog.uom_conversions%ROWTYPE;
        tax_version tax.tax_code_versions%ROWTYPE; tax_release core.reference_data_releases%ROWTYPE;
        profile catalog.commercial_charge_tax_profiles%ROWTYPE;
        requested_line jsonb; resolved_lines jsonb:='[]'::jsonb;
        source_versions jsonb:='[]'::jsonb; ruleset_version text; supply_type text;
        registration_count integer; address_count integer;
BEGIN
    IF organization_id IS NULL OR membership_id IS NULL OR auth_user_id IS NULL
       OR application_user_id IS NULL OR grant_id IS NULL OR purchase_order_id IS NULL
       OR branch_id IS NULL OR supplier_account_id IS NULL OR order_date IS NULL
       OR expected_on IS NULL OR expected_on<order_date
       OR request_document->>'tax_charge_mechanism'<>'normal'
       OR request_document->>'zero_rated_payment_mode'<>'not_applicable'
       OR pg_catalog.jsonb_typeof(request_document)<>'object'
       OR pg_catalog.jsonb_typeof(request_document->'lines')<>'array'
       OR pg_catalog.jsonb_array_length(request_document->'lines') NOT BETWEEN 1 AND 500
       OR pg_catalog.jsonb_typeof(COALESCE(request_document->'expense_charge_lines','[]'::jsonb))<>'array' THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='purchase-order input is incomplete or outside the domestic normal-charge pilot'; END IF;
    PERFORM 1 FROM core.memberships membership
      JOIN core.users user_row ON user_row.id=membership.user_id
      JOIN core.organizations organization_row ON organization_row.id=membership.org_id
      JOIN automation.agent_grants grant_row ON grant_row.org_id=membership.org_id
       AND grant_row.subject_membership_id=membership.id
      JOIN automation.agent_grant_capabilities capability ON capability.org_id=grant_row.org_id
       AND capability.agent_grant_id=grant_row.id
     WHERE membership.org_id=organization_id AND membership.id=membership_id
       AND membership.user_id=application_user_id AND membership.status='active'
       AND user_row.auth_user_id=auth_user_id AND user_row.status='active'
       AND organization_row.status='active' AND grant_row.id=grant_id
       AND grant_row.client_id=caller_client_id AND grant_row.status='active'
       AND grant_row.expires_at>pg_catalog.transaction_timestamp()
       AND (grant_row.branch_id IS NULL OR grant_row.branch_id=branch_id)
       AND capability.capability_code='procurement.purchase_order.prepare'
       AND capability.operation_mode='write' AND capability.status='active';
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='purchase-order delegated authority is inactive'; END IF;
    PERFORM erp_security.activate_context(auth_user_id,organization_id);
    IF erp_security.current_membership_id() IS DISTINCT FROM membership_id THEN
      RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='purchase-order verified auth context resolved a different membership'; END IF;
    IF order_date>"erp_core_commands"."current_organization_business_date"() THEN
      RAISE EXCEPTION USING ERRCODE='22007', MESSAGE='purchase order date cannot be in the future'; END IF;
    IF erp_security.can_access_branch(branch_id) IS DISTINCT FROM true
       OR erp_security.has_permission('procurement.order.manage',branch_id) IS DISTINCT FROM true
       OR erp_security.has_permission('automation.command.execute',branch_id) IS DISTINCT FROM true THEN
      RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='purchase-order branch permission is inactive'; END IF;
    SELECT * INTO STRICT organization FROM core.organizations
     WHERE id=organization_id AND status='active' FOR SHARE;
    IF organization.country_code<>'IN' OR organization.base_currency<>'INR' THEN
      RAISE EXCEPTION USING ERRCODE='0A000', MESSAGE='purchase-order pilot supports only Indian INR organizations'; END IF;
    SELECT * INTO STRICT branch FROM core.branches
     WHERE org_id=organization_id AND id=branch_id AND status='active' FOR SHARE;
    SELECT count(*) INTO registration_count FROM tax.registration_branches association
      JOIN tax.registrations registration ON registration.org_id=association.org_id
       AND registration.id=association.registration_id
     WHERE association.org_id=organization_id AND association.branch_id=branch.id
       AND association.status='active' AND association.effective_from<=order_date
       AND (association.effective_to IS NULL OR association.effective_to>=order_date)
       AND registration.state_code=branch.state_code AND registration.status='active'
       AND registration.effective_from<=order_date
       AND (registration.effective_to IS NULL OR registration.effective_to>=order_date);
    IF registration_count<>1 THEN RAISE EXCEPTION USING ERRCODE='21000', MESSAGE='buyer has no exact effective branch-state GST registration'; END IF;
    SELECT registration.* INTO STRICT buyer_registration FROM tax.registration_branches association
      JOIN tax.registrations registration ON registration.org_id=association.org_id
       AND registration.id=association.registration_id
     WHERE association.org_id=organization_id AND association.branch_id=branch.id
       AND association.status='active' AND association.effective_from<=order_date
       AND (association.effective_to IS NULL OR association.effective_to>=order_date)
       AND registration.state_code=branch.state_code AND registration.status='active'
       AND registration.effective_from<=order_date
       AND (registration.effective_to IS NULL OR registration.effective_to>=order_date)
     FOR SHARE OF association,registration;
    IF buyer_registration.registration_type<>'regular' THEN
      RAISE EXCEPTION USING ERRCODE='0A000', MESSAGE='purchase-order pilot requires a regular buyer GST registration'; END IF;
    SELECT * INTO STRICT buyer_registration_branch FROM tax.registration_branches association
     WHERE association.org_id=organization_id AND association.registration_id=buyer_registration.id
       AND association.branch_id=branch.id AND association.status='active'
       AND association.effective_from<=order_date
       AND (association.effective_to IS NULL OR association.effective_to>=order_date) FOR SHARE;
    SELECT * INTO STRICT supplier FROM parties.supplier_accounts
     WHERE org_id=organization_id AND id=supplier_account_id AND status='active' FOR SHARE;
    SELECT * INTO STRICT supplier_party FROM parties.parties
     WHERE org_id=organization_id AND id=supplier.party_id AND status='active' FOR SHARE;
    SELECT count(*) INTO address_count FROM parties.addresses
     WHERE org_id=organization_id AND party_id=supplier.party_id AND address_kind='registered'
       AND is_primary AND status='active' AND valid_from<=order_date
       AND (valid_until IS NULL OR valid_until>=order_date);
    IF address_count<>1 THEN RAISE EXCEPTION USING ERRCODE='21000', MESSAGE='supplier requires one effective primary registered address'; END IF;
    SELECT * INTO STRICT supplier_address FROM parties.addresses
     WHERE org_id=organization_id AND party_id=supplier.party_id AND address_kind='registered'
       AND is_primary AND status='active' AND valid_from<=order_date
       AND (valid_until IS NULL OR valid_until>=order_date) FOR SHARE;
    IF supplier_address.country_code<>'IN' THEN
      RAISE EXCEPTION USING ERRCODE='0A000', MESSAGE='import purchase orders remain fail-closed in the pilot'; END IF;
    SELECT count(*) INTO registration_count FROM parties.tax_registrations
     WHERE org_id=organization_id AND party_id=supplier.party_id AND registration_type='GSTIN'
       AND state_code=supplier_address.state_code AND status='active'
       AND (valid_from IS NULL OR valid_from<=order_date)
       AND (valid_until IS NULL OR valid_until>=order_date);
    IF registration_count<>1 THEN RAISE EXCEPTION USING ERRCODE='21000', MESSAGE='supplier requires one effective address-state GSTIN'; END IF;
    SELECT * INTO STRICT supplier_registration FROM parties.tax_registrations
     WHERE org_id=organization_id AND party_id=supplier.party_id AND registration_type='GSTIN'
       AND state_code=supplier_address.state_code AND status='active'
       AND (valid_from IS NULL OR valid_from<=order_date)
       AND (valid_until IS NULL OR valid_until>=order_date) FOR SHARE;
    IF supplier_registration.taxpayer_type NOT IN ('regular','casual') THEN
      RAISE EXCEPTION USING ERRCODE='0A000', MESSAGE='SEZ, composition, non-resident, and unregistered supplier purchases remain fail-closed'; END IF;
    supply_type:=CASE WHEN buyer_registration.state_code=supplier_registration.state_code
      THEN 'intra_state' ELSE 'inter_state' END;
    source_versions:=pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('resource_type','organization','id',organization.id,'row_version',organization.row_version),
      pg_catalog.jsonb_build_object('resource_type','branch','id',branch.id,'row_version',branch.row_version),
      pg_catalog.jsonb_build_object('resource_type','buyer_tax_registration','id',buyer_registration.id,'row_version',buyer_registration.row_version,'effective_from',buyer_registration.effective_from,'effective_to',buyer_registration.effective_to),
      pg_catalog.jsonb_build_object('resource_type','buyer_registration_branch','registration_id',buyer_registration_branch.registration_id,'branch_id',buyer_registration_branch.branch_id,'status',buyer_registration_branch.status,'effective_from',buyer_registration_branch.effective_from,'effective_to',buyer_registration_branch.effective_to),
      pg_catalog.jsonb_build_object('resource_type','supplier_account','id',supplier.id,'row_version',supplier.row_version),
      pg_catalog.jsonb_build_object('resource_type','supplier_party','id',supplier_party.id,'row_version',supplier_party.row_version),
      pg_catalog.jsonb_build_object('resource_type','supplier_registered_address','id',supplier_address.id,'row_version',supplier_address.row_version,'valid_from',supplier_address.valid_from,'valid_until',supplier_address.valid_until),
      pg_catalog.jsonb_build_object('resource_type','supplier_tax_registration','id',supplier_registration.id,'row_version',supplier_registration.row_version,'taxpayer_type',supplier_registration.taxpayer_type,'valid_from',supplier_registration.valid_from,'valid_until',supplier_registration.valid_until));
    FOR requested_line IN SELECT value FROM pg_catalog.jsonb_array_elements(request_document->'lines') LOOP
      IF NULLIF(requested_line->>'line_id','')::uuid IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='purchase-order product line identity is missing'; END IF;
      SELECT * INTO STRICT product FROM catalog.products WHERE org_id=organization_id
       AND id=NULLIF(requested_line->>'product_id','')::uuid AND status='active' FOR SHARE;
      SELECT * INTO STRICT conversion FROM catalog.uom_conversions WHERE org_id=organization_id
       AND id=NULLIF(requested_line->>'uom_conversion_id','')::uuid AND product_id=product.id
       AND status='active' AND to_uom_code=product.base_uom_code AND valid_from<=order_date
       AND (valid_until IS NULL OR valid_until>=order_date) FOR SHARE;
      SELECT * INTO STRICT tax_version FROM erp_automation_reads.resolve_product_tax(organization_id,product.id,order_date);
      SELECT * INTO STRICT tax_release FROM core.reference_data_releases WHERE id=tax_version.release_id
       AND dataset_kind='hsn_sac_tax' AND status IN ('active','source_snapshot') AND effective_from<=order_date
       AND (effective_to IS NULL OR effective_to>=order_date) FOR SHARE;
      resolved_lines:=resolved_lines||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'line_number',pg_catalog.jsonb_array_length(resolved_lines)+1,'line_kind','product','line_id',requested_line->>'line_id',
        'product_id',product.id,'product_row_version',product.row_version,'hsn_code',product.hsn_code,
        'uom_conversion_id',conversion.id,'uom_code',conversion.from_uom_code,'to_uom_code',conversion.to_uom_code,
        'multiplier',conversion.multiplier::text,'uom_valid_from',conversion.valid_from,'uom_valid_until',conversion.valid_until,
        'tax_code_version_id',tax_version.id,'tax_version_number',tax_version.version_number,
        'tax_effective_from',tax_version.effective_from,'tax_effective_to',tax_version.effective_to,
        'tax_release_id',tax_release.id,'tax_release_ruleset_version',tax_release.ruleset_version,
        'taxability',tax_version.taxability,'gst_rate',CASE WHEN tax_version.taxability='taxable' THEN tax_version.igst_rate::text ELSE '0' END,
        'cess_rate',CASE WHEN tax_version.taxability='taxable' THEN tax_version.cess_rate::text ELSE '0' END,
        'ruleset_version',tax_version.ruleset_version,'input',requested_line));
      source_versions:=source_versions||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'resource_type','product','id',product.id,'row_version',product.row_version,
        'uom_conversion_id',conversion.id,'uom_valid_from',conversion.valid_from,'uom_valid_until',conversion.valid_until,
        'tax_code_version_id',tax_version.id,'tax_version_number',tax_version.version_number,
        'tax_effective_from',tax_version.effective_from,'tax_effective_to',tax_version.effective_to,
        'tax_release_id',tax_release.id,'tax_release_ruleset_version',tax_release.ruleset_version));
    END LOOP;
    FOR requested_line IN SELECT value FROM pg_catalog.jsonb_array_elements(COALESCE(request_document->'charge_lines','[]'::jsonb)) LOOP
      IF NULLIF(requested_line->>'line_id','')::uuid IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='purchase-order charge line identity is missing'; END IF;
      SELECT * INTO STRICT profile FROM catalog.commercial_charge_tax_profiles WHERE org_id=organization_id
       AND direction='procurement' AND charge_code=requested_line->>'charge_code' AND status='active'
       AND effective_from<=order_date AND (effective_to IS NULL OR effective_to>=order_date) FOR SHARE;
      SELECT * INTO STRICT tax_version FROM tax.tax_code_versions WHERE id=profile.tax_code_version_id
       AND code_kind='sac' AND status='active' AND effective_from<=order_date
       AND (effective_to IS NULL OR effective_to>=order_date) FOR SHARE;
      SELECT * INTO STRICT tax_release FROM core.reference_data_releases WHERE id=tax_version.release_id
       AND dataset_kind='hsn_sac_tax' AND status='active' AND effective_from<=order_date
       AND (effective_to IS NULL OR effective_to>=order_date) FOR SHARE;
      resolved_lines:=resolved_lines||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'line_number',pg_catalog.jsonb_array_length(resolved_lines)+1,'line_kind','charge','line_id',requested_line->>'line_id',
        'charge_code',profile.charge_code,'charge_tax_profile_id',profile.id,'charge_tax_profile_row_version',profile.row_version,
        'charge_tax_profile_effective_from',profile.effective_from,'charge_tax_profile_effective_to',profile.effective_to,
        'sac_code',tax_version.code,'tax_code_version_id',tax_version.id,'tax_version_number',tax_version.version_number,
        'tax_effective_from',tax_version.effective_from,'tax_effective_to',tax_version.effective_to,
        'tax_release_id',tax_release.id,'tax_release_ruleset_version',tax_release.ruleset_version,
        'taxability',tax_version.taxability,'gst_rate',CASE WHEN tax_version.taxability='taxable' THEN tax_version.igst_rate::text ELSE '0' END,
        'cess_rate',CASE WHEN tax_version.taxability='taxable' THEN tax_version.cess_rate::text ELSE '0' END,
        'ruleset_version',tax_version.ruleset_version,'input',requested_line));
      source_versions:=source_versions||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'resource_type','commercial_charge_tax_profile','id',profile.id,'row_version',profile.row_version,
        'charge_code',profile.charge_code,'effective_from',profile.effective_from,'effective_to',profile.effective_to,
        'tax_code_version_id',tax_version.id,'tax_version_number',tax_version.version_number,
        'tax_effective_from',tax_version.effective_from,'tax_effective_to',tax_version.effective_to,
        'tax_release_id',tax_release.id,'tax_release_ruleset_version',tax_release.ruleset_version));
    END LOOP;
    ruleset_version:=erp_automation_reads.tax_ruleset_fingerprint(resolved_lines);
    RETURN pg_catalog.jsonb_build_object(
      'branch_id',branch.id,'branch_row_version',branch.row_version,'order_date',order_date,'expected_on',expected_on,
      'supply_type',supply_type,'zero_rated_payment_mode','not_applicable','tax_charge_mechanism','normal',
      'supplier_account_id',supplier.id,'supplier_account_row_version',supplier.row_version,
      'supplier_party_id',supplier_party.id,'supplier_party_row_version',supplier_party.row_version,
      'supplier_address_id',supplier_address.id,'supplier_address_row_version',supplier_address.row_version,
      'supplier_tax_registration_id',supplier_registration.id,'supplier_tax_registration_row_version',supplier_registration.row_version,
      'supplier_taxpayer_type',supplier_registration.taxpayer_type,'buyer_tax_registration_id',buyer_registration.id,
      'ruleset_version',ruleset_version,'lines',resolved_lines,
      'legal_scope',pg_catalog.jsonb_build_object('country','IN','currency','INR','normal_charge',true,
        'import_supported',false,'sez_supported',false,'reverse_charge_supported',false,
        'supplier_gstin_evidence_id',supplier_registration.id,'buyer_gstin_evidence_id',buyer_registration.id),
      'source_versions',source_versions);
END
$function$;

CREATE OR REPLACE FUNCTION "erp_automation_commands"."resolve_supplier_invoice_prepare"(organization_id uuid, membership_id uuid, auth_user_id uuid, application_user_id uuid, grant_id uuid, caller_client_id varchar, supplier_invoice_id uuid, request_document jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
DECLARE requested_branch_id uuid:=NULLIF(request_document->>'branch_id','')::uuid;
        requested_supplier_id uuid:=NULLIF(request_document->>'supplier_account_id','')::uuid;
        requested_registration_id uuid:=NULLIF(request_document->>'supplier_tax_registration_id','')::uuid;
        requested_portal_line_id uuid:=NULLIF(request_document->>'portal_document_line_id','')::uuid;
        invoice_date date:=NULLIF(request_document->>'invoice_date','')::date;
        received_date date:=NULLIF(request_document->>'received_date','')::date;
        organization core.organizations%ROWTYPE; branch core.branches%ROWTYPE;
        buyer_registration tax.registrations%ROWTYPE; buyer_scope tax.registration_branches%ROWTYPE;
        supplier parties.supplier_accounts%ROWTYPE; supplier_party parties.parties%ROWTYPE;
        supplier_registration parties.tax_registrations%ROWTYPE; supplier_address parties.addresses%ROWTYPE;
        portal_line tax.portal_document_lines%ROWTYPE; portal_document tax.portal_documents%ROWTYPE;
        portal_period tax.return_periods%ROWTYPE; inventory_account finance.accounts%ROWTYPE;
        payable_account finance.accounts%ROWTYPE; input_cgst_account finance.accounts%ROWTYPE;
        input_sgst_account finance.accounts%ROWTYPE; input_igst_account finance.accounts%ROWTYPE;
        input_cess_account finance.accounts%ROWTYPE; rounding_gain_account finance.accounts%ROWTYPE;
        rounding_loss_account finance.accounts%ROWTYPE; variance_account finance.accounts%ROWTYPE;
        receipt_line procurement.goods_receipt_lines%ROWTYPE; receipt procurement.goods_receipts%ROWTYPE;
        order_line procurement.purchase_order_lines%ROWTYPE; purchase_order procurement.purchase_orders%ROWTYPE;
        product catalog.products%ROWTYPE;
        tax_version tax.tax_code_versions%ROWTYPE; tax_release core.reference_data_releases%ROWTYPE;
        profile catalog.commercial_charge_tax_profiles%ROWTYPE; expense_account finance.accounts%ROWTYPE;
        requested_line jsonb; requested_allocation jsonb; resolved_allocations jsonb;
        landed_cost_lineage jsonb; landed_cost_target jsonb;
        resolved_lines jsonb:='[]'::jsonb; source_versions jsonb:='[]'::jsonb;
        resolved_receipt_ids jsonb:='[]'::jsonb; source_purchase_order_id uuid;
        base_billed numeric(20,6); base_free numeric(20,6); prior_billed numeric(20,6); prior_free numeric(20,6);
        receipt_cost numeric(20,2); line_product_id uuid; line_purchase_order_line_id uuid;
        line_uom text; line_factor numeric(20,6); receipt_business_date date;
        ruleset_version text; supply_type text; candidate_count integer; address_count integer;
        allocation_count integer; distinct_allocation_count integer;
BEGIN
    IF organization_id IS NULL OR membership_id IS NULL OR auth_user_id IS NULL OR application_user_id IS NULL
       OR grant_id IS NULL OR supplier_invoice_id IS NULL OR requested_branch_id IS NULL
       OR requested_supplier_id IS NULL OR requested_registration_id IS NULL OR requested_portal_line_id IS NULL
       OR invoice_date IS NULL OR received_date<invoice_date OR pg_catalog.btrim(COALESCE(request_document->>'supplier_invoice_number',''))=''
       OR request_document->>'tax_charge_mechanism'<>'normal'
       OR request_document->>'zero_rated_payment_mode'<>'not_applicable'
       OR pg_catalog.jsonb_typeof(request_document->'lines')<>'array'
       OR pg_catalog.jsonb_array_length(request_document->'lines') NOT BETWEEN 1 AND 500
       OR pg_catalog.jsonb_typeof(request_document->'goods_receipt_ids')<>'array'
       OR pg_catalog.jsonb_array_length(request_document->'goods_receipt_ids')<1
       OR pg_catalog.jsonb_typeof(COALESCE(request_document->'expense_charge_lines','[]'::jsonb))<>'array' THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='supplier-invoice input is incomplete or outside the domestic normal-charge pilot'; END IF;
    SELECT count(*),count(DISTINCT line.value->>'goods_receipt_line_id')
      INTO allocation_count,distinct_allocation_count
      FROM pg_catalog.jsonb_array_elements(request_document->'lines') line(value);
    IF allocation_count<>distinct_allocation_count OR allocation_count=0
       OR (SELECT count(*) FROM pg_catalog.jsonb_array_elements_text(request_document->'goods_receipt_ids'))
          <>(SELECT count(DISTINCT value) FROM pg_catalog.jsonb_array_elements_text(request_document->'goods_receipt_ids')) THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='supplier invoice requires unique receipt lines and a unique exact GRN set'; END IF;
    IF EXISTS (SELECT 1 FROM pg_catalog.jsonb_array_elements(request_document->'lines') line(value)
      WHERE line.value->>'product_inventory_cost_treatment'<>'capitalize'
         OR line.value->>'landed_cost_allocation_method' NOT IN ('direct','quantity_weighted','value_weighted')
         OR line.value->>'itc_eligibility'<>'eligible'
         OR line.value->>'itc_eligibility_basis'<>'taxable_resale_not_blocked_under_section_17')
       OR EXISTS (SELECT 1 FROM pg_catalog.jsonb_array_elements(COALESCE(request_document->'expense_charge_lines','[]'::jsonb)) line(value)
      WHERE line.value->>'charge_inventory_cost_treatment' NOT IN ('expense','capitalize')
         OR (line.value->>'charge_inventory_cost_treatment'='capitalize'
             AND line.value->>'landed_cost_allocation_method' NOT IN ('direct','quantity_weighted','value_weighted'))
         OR (line.value->>'charge_inventory_cost_treatment'='expense'
             AND line.value ? 'landed_cost_allocation_method')
         OR line.value->>'itc_eligibility'<>'eligible'
         OR line.value->>'itc_eligibility_basis'<>'taxable_resale_not_blocked_under_section_17'
         OR line.value->>'expense_charge_code' NOT IN ('freight','packing','insurance','handling')) THEN
      RAISE EXCEPTION USING ERRCODE='0A000', MESSAGE='supplier-invoice requires reviewed ITC and explicit product or charge landed-cost treatment'; END IF;
    PERFORM 1 FROM core.memberships membership JOIN core.users user_row ON user_row.id=membership.user_id
      JOIN core.organizations organization_row ON organization_row.id=membership.org_id
      JOIN automation.agent_grants grant_row ON grant_row.org_id=membership.org_id AND grant_row.subject_membership_id=membership.id
      JOIN automation.agent_grant_capabilities capability ON capability.org_id=grant_row.org_id AND capability.agent_grant_id=grant_row.id
     WHERE membership.org_id=organization_id AND membership.id=membership_id AND membership.user_id=application_user_id
       AND membership.status='active' AND user_row.auth_user_id=auth_user_id AND user_row.status='active'
       AND organization_row.status='active' AND grant_row.id=grant_id AND grant_row.client_id=caller_client_id
       AND grant_row.status='active' AND grant_row.expires_at>pg_catalog.transaction_timestamp()
       AND (grant_row.branch_id IS NULL OR grant_row.branch_id=requested_branch_id)
       AND capability.capability_code='procurement.supplier_invoice.prepare'
       AND capability.operation_mode='write' AND capability.status='active';
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='supplier-invoice delegated authority is inactive'; END IF;
    PERFORM erp_security.activate_context(auth_user_id,organization_id);
    IF erp_security.current_membership_id() IS DISTINCT FROM membership_id THEN
      RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='supplier-invoice verified auth context resolved a different membership'; END IF;
    IF erp_security.can_access_branch(requested_branch_id) IS DISTINCT FROM true
       OR erp_security.has_permission('procurement.supplier_invoice.create',requested_branch_id) IS DISTINCT FROM true
       OR erp_security.has_permission('procurement.invoice.post',requested_branch_id) IS DISTINCT FROM true
       OR erp_security.has_permission('finance.journal.post',NULL::uuid) IS DISTINCT FROM true
       OR erp_security.has_permission('automation.command.execute',requested_branch_id) IS DISTINCT FROM true THEN
      RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='supplier-invoice cross-domain permission is inactive'; END IF;
    SELECT * INTO STRICT organization FROM core.organizations WHERE id=organization_id AND status='active' FOR SHARE;
    SELECT * INTO STRICT branch FROM core.branches WHERE org_id=organization_id AND id=requested_branch_id AND status='active' FOR SHARE;
    IF invoice_date>"erp_core_commands"."current_organization_business_date"()
       OR received_date>"erp_core_commands"."current_organization_business_date"() THEN
      RAISE EXCEPTION USING ERRCODE='22007', MESSAGE='supplier invoice or received date cannot be in the future'; END IF;
    IF organization.country_code<>'IN' OR organization.base_currency<>'INR' THEN
      RAISE EXCEPTION USING ERRCODE='0A000', MESSAGE='supplier-invoice pilot supports only Indian INR organizations'; END IF;
    SELECT count(*) INTO candidate_count FROM tax.registration_branches association JOIN tax.registrations registration
      ON registration.org_id=association.org_id AND registration.id=association.registration_id
     WHERE association.org_id=organization_id AND association.branch_id=branch.id AND association.status='active'
       AND association.effective_from<=invoice_date AND (association.effective_to IS NULL OR association.effective_to>=invoice_date)
       AND registration.state_code=branch.state_code AND registration.registration_type='regular' AND registration.status='active'
       AND registration.effective_from<=invoice_date AND (registration.effective_to IS NULL OR registration.effective_to>=invoice_date);
    IF candidate_count<>1 THEN RAISE EXCEPTION USING ERRCODE='21000', MESSAGE='buyer requires one exact effective regular branch GST registration'; END IF;
    SELECT registration.* INTO STRICT buyer_registration FROM tax.registration_branches association JOIN tax.registrations registration
      ON registration.org_id=association.org_id AND registration.id=association.registration_id
     WHERE association.org_id=organization_id AND association.branch_id=branch.id AND association.status='active'
       AND association.effective_from<=invoice_date AND (association.effective_to IS NULL OR association.effective_to>=invoice_date)
       AND registration.state_code=branch.state_code AND registration.registration_type='regular' AND registration.status='active'
       AND registration.effective_from<=invoice_date AND (registration.effective_to IS NULL OR registration.effective_to>=invoice_date)
     FOR SHARE OF association,registration;
    SELECT * INTO STRICT buyer_scope FROM tax.registration_branches association
     WHERE association.org_id=organization_id AND association.registration_id=buyer_registration.id
       AND association.branch_id=branch.id AND association.status='active'
       AND association.effective_from<=invoice_date AND (association.effective_to IS NULL OR association.effective_to>=invoice_date) FOR SHARE;
    SELECT * INTO STRICT supplier FROM parties.supplier_accounts
     WHERE org_id=organization_id AND id=requested_supplier_id AND status='active' FOR SHARE;
    SELECT * INTO STRICT supplier_party FROM parties.parties
     WHERE org_id=organization_id AND id=supplier.party_id AND status='active' FOR SHARE;
    SELECT * INTO STRICT supplier_registration FROM parties.tax_registrations
     WHERE org_id=organization_id AND id=requested_registration_id AND party_id=supplier.party_id
       AND registration_type='GSTIN' AND status='active' AND verified_at IS NOT NULL
       AND taxpayer_type IN ('regular','casual') AND (valid_from IS NULL OR valid_from<=invoice_date)
       AND (valid_until IS NULL OR valid_until>=invoice_date) FOR SHARE;
    SELECT count(*) INTO address_count FROM parties.addresses WHERE org_id=organization_id AND party_id=supplier.party_id
       AND address_kind='registered' AND is_primary AND status='active' AND state_code=supplier_registration.state_code
       AND valid_from<=invoice_date AND (valid_until IS NULL OR valid_until>=invoice_date);
    IF address_count<>1 THEN RAISE EXCEPTION USING ERRCODE='21000', MESSAGE='supplier GSTIN requires one exact effective registered address'; END IF;
    SELECT * INTO STRICT supplier_address FROM parties.addresses WHERE org_id=organization_id AND party_id=supplier.party_id
       AND address_kind='registered' AND is_primary AND status='active' AND state_code=supplier_registration.state_code
       AND valid_from<=invoice_date AND (valid_until IS NULL OR valid_until>=invoice_date) FOR SHARE;
    IF supplier_address.country_code<>'IN' THEN RAISE EXCEPTION USING ERRCODE='0A000', MESSAGE='import supplier invoices remain fail-closed'; END IF;
    supply_type:=CASE WHEN buyer_registration.state_code=supplier_registration.state_code THEN 'intra_state' ELSE 'inter_state' END;
    SELECT * INTO STRICT portal_line FROM tax.portal_document_lines
     WHERE org_id=organization_id AND id=requested_portal_line_id AND document_type='invoice'
       AND supplier_gstin=supplier_registration.registration_number
       AND invoice_number=request_document->>'supplier_invoice_number' AND invoice_date=invoice_date
       AND place_of_supply_state_code=buyer_registration.state_code FOR SHARE;
    SELECT * INTO STRICT portal_document FROM tax.portal_documents
     WHERE org_id=organization_id AND id=portal_line.portal_document_id AND registration_id=buyer_registration.id
       AND portal_document_type='gstr2b' AND status='parsed' AND parsed_at IS NOT NULL FOR SHARE;
    SELECT * INTO STRICT portal_period FROM tax.return_periods
     WHERE org_id=organization_id AND id=portal_document.return_period_id AND registration_id=buyer_registration.id
       AND period_start<=invoice_date AND period_end>=invoice_date FOR SHARE;
    SELECT count(*) INTO candidate_count FROM tax.portal_document_lines line JOIN tax.portal_documents document
      ON document.org_id=line.org_id AND document.id=line.portal_document_id
     WHERE line.org_id=organization_id AND line.supplier_gstin=supplier_registration.registration_number
       AND line.invoice_number=request_document->>'supplier_invoice_number' AND line.invoice_date=invoice_date
       AND line.document_type='invoice' AND document.registration_id=buyer_registration.id
       AND document.portal_document_type='gstr2b' AND document.status='parsed';
    IF candidate_count<>1 THEN RAISE EXCEPTION USING ERRCODE='21000', MESSAGE='supplier invoice requires one unique parsed GSTR-2B row'; END IF;
    SELECT * INTO STRICT inventory_account FROM finance.accounts WHERE org_id=organization_id
       AND id=erp_commercial_commands.resolve_role_account(organization_id,branch.id,'inventory_asset','asset','INR',false) FOR SHARE;
    SELECT * INTO STRICT payable_account FROM finance.accounts WHERE org_id=organization_id
       AND id=erp_commercial_commands.resolve_role_account(organization_id,branch.id,'accounts_payable','liability','INR',true) FOR SHARE;
    IF supplier.default_payable_account_id IS DISTINCT FROM payable_account.id THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='supplier default payable account differs from the reviewed branch account role'; END IF;
    SELECT * INTO STRICT input_cgst_account FROM finance.accounts WHERE org_id=organization_id
       AND id=erp_commercial_commands.resolve_role_account(organization_id,branch.id,'input_cgst','asset','INR',false) FOR SHARE;
    SELECT * INTO STRICT input_sgst_account FROM finance.accounts WHERE org_id=organization_id
       AND id=erp_commercial_commands.resolve_role_account(organization_id,branch.id,'input_sgst','asset','INR',false) FOR SHARE;
    SELECT * INTO STRICT input_igst_account FROM finance.accounts WHERE org_id=organization_id
       AND id=erp_commercial_commands.resolve_role_account(organization_id,branch.id,'input_igst','asset','INR',false) FOR SHARE;
    SELECT * INTO STRICT input_cess_account FROM finance.accounts WHERE org_id=organization_id
       AND id=erp_commercial_commands.resolve_role_account(organization_id,branch.id,'input_cess','asset','INR',false) FOR SHARE;
    SELECT * INTO STRICT rounding_gain_account FROM finance.accounts WHERE org_id=organization_id
       AND id=erp_commercial_commands.resolve_role_account(organization_id,branch.id,'rounding_gain','income','INR',false) FOR SHARE;
    SELECT * INTO STRICT rounding_loss_account FROM finance.accounts WHERE org_id=organization_id
       AND id=erp_commercial_commands.resolve_role_account(organization_id,branch.id,'rounding_loss','expense','INR',false) FOR SHARE;
    SELECT * INTO STRICT variance_account FROM finance.accounts WHERE org_id=organization_id
       AND id=erp_commercial_commands.resolve_role_account(organization_id,branch.id,'purchase_price_variance','expense','INR',false) FOR SHARE;
    source_versions:=pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('resource_type','organization','id',organization.id,'row_version',organization.row_version),
      pg_catalog.jsonb_build_object('resource_type','branch','id',branch.id,'row_version',branch.row_version),
      pg_catalog.jsonb_build_object('resource_type','buyer_tax_registration','id',buyer_registration.id,'row_version',buyer_registration.row_version),
      pg_catalog.jsonb_build_object('resource_type','buyer_registration_branch','registration_id',buyer_scope.registration_id,'branch_id',buyer_scope.branch_id,'effective_from',buyer_scope.effective_from,'effective_to',buyer_scope.effective_to),
      pg_catalog.jsonb_build_object('resource_type','supplier_account','id',supplier.id,'row_version',supplier.row_version,'payment_days',supplier.payment_days),
      pg_catalog.jsonb_build_object('resource_type','supplier_party','id',supplier_party.id,'row_version',supplier_party.row_version),
      pg_catalog.jsonb_build_object('resource_type','supplier_tax_registration','id',supplier_registration.id,'row_version',supplier_registration.row_version,'registration_number',supplier_registration.registration_number,'taxpayer_type',supplier_registration.taxpayer_type,'verified_at',supplier_registration.verified_at),
      pg_catalog.jsonb_build_object('resource_type','supplier_registered_address','id',supplier_address.id,'row_version',supplier_address.row_version),
      pg_catalog.jsonb_build_object('resource_type','gstr2b_portal_document','id',portal_document.id,'status',portal_document.status,'parsed_at',portal_document.parsed_at,'source_sha256',pg_catalog.encode(portal_document.source_sha256,'hex')),
      pg_catalog.jsonb_build_object('resource_type','gstr2b_portal_line','id',portal_line.id,'source_row_hash',pg_catalog.encode(portal_line.source_row_hash,'hex')),
      pg_catalog.jsonb_build_object('resource_type','finance_account','role','inventory_asset','id',inventory_account.id,'row_version',inventory_account.row_version),
      pg_catalog.jsonb_build_object('resource_type','finance_account','role','accounts_payable','id',payable_account.id,'row_version',payable_account.row_version),
      pg_catalog.jsonb_build_object('resource_type','finance_account','role','input_cgst','id',input_cgst_account.id,'row_version',input_cgst_account.row_version),
      pg_catalog.jsonb_build_object('resource_type','finance_account','role','input_sgst','id',input_sgst_account.id,'row_version',input_sgst_account.row_version),
      pg_catalog.jsonb_build_object('resource_type','finance_account','role','input_igst','id',input_igst_account.id,'row_version',input_igst_account.row_version),
      pg_catalog.jsonb_build_object('resource_type','finance_account','role','input_cess','id',input_cess_account.id,'row_version',input_cess_account.row_version),
      pg_catalog.jsonb_build_object('resource_type','finance_account','role','rounding_gain','id',rounding_gain_account.id,'row_version',rounding_gain_account.row_version),
      pg_catalog.jsonb_build_object('resource_type','finance_account','role','rounding_loss','id',rounding_loss_account.id,'row_version',rounding_loss_account.row_version),
      pg_catalog.jsonb_build_object('resource_type','finance_account','role','purchase_price_variance','id',variance_account.id,'row_version',variance_account.row_version));
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        organization_id::text||':supplier-receipt:'||locked.goods_receipt_line_id,630195401))
      FROM (
        SELECT DISTINCT line.value->>'goods_receipt_line_id' AS goods_receipt_line_id
          FROM pg_catalog.jsonb_array_elements(request_document->'lines') line(value)
         ORDER BY goods_receipt_line_id
      ) locked;
    FOR requested_line IN SELECT value FROM pg_catalog.jsonb_array_elements(request_document->'lines') LOOP
      IF NULLIF(requested_line->>'line_id','')::uuid IS NULL OR NULLIF(requested_line->>'allocation_id','')::uuid IS NULL
         OR NULLIF(requested_line->>'goods_receipt_line_id','')::uuid IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='supplier product line requires identity and one explicit receipt line'; END IF;
      base_billed:=0; base_free:=0; receipt_cost:=0; line_product_id:=NULL; line_purchase_order_line_id:=NULL;
      line_uom:=NULL; line_factor:=NULL; resolved_allocations:='[]'::jsonb;
      FOR requested_allocation IN SELECT pg_catalog.jsonb_build_object(
        'allocation_id',requested_line->>'allocation_id',
        'goods_receipt_line_id',requested_line->>'goods_receipt_line_id',
        'allocated_base_billed_quantity',requested_line->>'allocated_base_billed_quantity',
        'allocated_base_free_quantity',requested_line->>'allocated_base_free_quantity') LOOP
        PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(organization_id::text||':supplier-receipt:'||(requested_allocation->>'goods_receipt_line_id'),630195401));
        SELECT line.* INTO STRICT receipt_line FROM procurement.goods_receipt_lines line JOIN procurement.goods_receipts header
          ON header.org_id=line.org_id AND header.id=line.goods_receipt_id
         WHERE line.org_id=organization_id AND line.id=NULLIF(requested_allocation->>'goods_receipt_line_id','')::uuid
           AND header.status='posted' AND header.branch_id=branch.id AND header.supplier_account_id=supplier.id
           AND line.purchase_order_line_id IS NOT NULL FOR SHARE OF line,header;
        SELECT * INTO STRICT receipt FROM procurement.goods_receipts
         WHERE org_id=organization_id AND id=receipt_line.goods_receipt_id AND status='posted' FOR SHARE;
        receipt_business_date:=(receipt.received_at AT TIME ZONE organization.timezone)::date;
        IF received_date<receipt_business_date THEN
          RAISE EXCEPTION USING ERRCODE='22007', MESSAGE='supplier invoice received date cannot precede the organization-local goods receipt date'; END IF;
        SELECT * INTO STRICT order_line FROM procurement.purchase_order_lines
         WHERE org_id=organization_id AND id=receipt_line.purchase_order_line_id AND line_kind='product' FOR SHARE;
        SELECT * INTO STRICT purchase_order FROM procurement.purchase_orders
         WHERE org_id=organization_id AND id=order_line.purchase_order_id
           AND branch_id=branch.id AND supplier_account_id=supplier.id
           AND status IN ('partially_received','received') FOR SHARE;
        IF source_purchase_order_id IS NULL THEN source_purchase_order_id:=purchase_order.id;
        ELSIF source_purchase_order_id IS DISTINCT FROM purchase_order.id THEN
          RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='supplier invoice receipt allocations must belong to one purchase order'; END IF;
        IF receipt_line.uom_code IS DISTINCT FROM order_line.uom_code THEN
          RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='posted receipt UOM differs from its locked purchase-order line'; END IF;
        SELECT * INTO STRICT product FROM catalog.products
         WHERE org_id=organization_id AND id=receipt_line.product_id AND id=order_line.product_id
           AND product_kind IN ('medicine','medical_device','consumable') AND status='active' FOR SHARE;
        IF line_product_id IS NULL THEN line_product_id:=product.id; line_purchase_order_line_id:=order_line.id;
          line_uom:=receipt_line.uom_code; line_factor:=order_line.uom_conversion_factor;
        ELSIF ROW(line_product_id,line_purchase_order_line_id,line_uom,line_factor)
          IS DISTINCT FROM ROW(product.id,order_line.id,receipt_line.uom_code,order_line.uom_conversion_factor) THEN
          RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='one supplier invoice line cannot mix PO line, product, or UOM receipt facts'; END IF;
        PERFORM allocation.id
          FROM procurement.supplier_invoice_receipt_allocations allocation
          JOIN procurement.supplier_invoice_lines invoice_line
            ON invoice_line.org_id=allocation.org_id AND invoice_line.id=allocation.supplier_invoice_line_id
         WHERE allocation.org_id=organization_id AND allocation.goods_receipt_line_id=receipt_line.id
           AND invoice_line.supplier_invoice_id<>supplier_invoice_id
         ORDER BY allocation.id FOR SHARE OF allocation,invoice_line;
        prior_billed:=COALESCE((SELECT sum(allocation.allocated_base_billed_quantity)
          FROM procurement.supplier_invoice_receipt_allocations allocation JOIN procurement.supplier_invoice_lines invoice_line
            ON invoice_line.org_id=allocation.org_id AND invoice_line.id=allocation.supplier_invoice_line_id
         WHERE allocation.org_id=organization_id AND allocation.goods_receipt_line_id=receipt_line.id
           AND invoice_line.supplier_invoice_id<>supplier_invoice_id),0);
        prior_free:=COALESCE((SELECT sum(allocation.allocated_base_free_quantity)
          FROM procurement.supplier_invoice_receipt_allocations allocation JOIN procurement.supplier_invoice_lines invoice_line
            ON invoice_line.org_id=allocation.org_id AND invoice_line.id=allocation.supplier_invoice_line_id
         WHERE allocation.org_id=organization_id AND allocation.goods_receipt_line_id=receipt_line.id
           AND invoice_line.supplier_invoice_id<>supplier_invoice_id),0);
        IF (requested_allocation->>'allocated_base_billed_quantity')::numeric<0
           OR (requested_allocation->>'allocated_base_free_quantity')::numeric<0
           OR (requested_allocation->>'allocated_base_billed_quantity')::numeric+(requested_allocation->>'allocated_base_free_quantity')::numeric<=0
           OR prior_billed+(requested_allocation->>'allocated_base_billed_quantity')::numeric>receipt_line.base_accepted_quantity
           OR prior_free+(requested_allocation->>'allocated_base_free_quantity')::numeric>receipt_line.base_free_quantity THEN
          RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='supplier invoice exceeds separate posted receipt billed or free ceiling'; END IF;
        landed_cost_lineage:=erp_trade_commands_v2.landed_cost_receipt_lineage_state(
          organization_id,receipt_line.id,
          (requested_allocation->>'allocated_base_billed_quantity')::numeric,
          (requested_allocation->>'allocated_base_free_quantity')::numeric);
        IF landed_cost_lineage->>'contract_version'<>'supplier_invoice_landed_cost_lineage_v1'
           OR (landed_cost_lineage->>'source_identity_count')::integer<>1
           OR pg_catalog.jsonb_typeof(landed_cost_lineage->'targets')<>'array' THEN
          RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='supplier invoice landed-cost lineage contract is invalid'; END IF;
        base_billed:=base_billed+(requested_allocation->>'allocated_base_billed_quantity')::numeric;
        base_free:=base_free+(requested_allocation->>'allocated_base_free_quantity')::numeric;
        receipt_cost:=receipt_cost+pg_catalog.round(((requested_allocation->>'allocated_base_billed_quantity')::numeric+
          (requested_allocation->>'allocated_base_free_quantity')::numeric)*receipt_line.unit_cost,2);
        resolved_allocations:=resolved_allocations||pg_catalog.jsonb_build_array(requested_allocation||pg_catalog.jsonb_build_object(
          'goods_receipt_id',receipt.id,'goods_receipt_row_version',receipt.row_version,'goods_receipt_line_row_id',receipt_line.id,
          'goods_receipt_received_at',receipt.received_at,'goods_receipt_business_date',receipt_business_date,
          'product_id',product.id,'receipt_unit_cost',receipt_line.unit_cost::text,'receipt_base_accepted_quantity',receipt_line.base_accepted_quantity::text,
          'receipt_base_free_quantity',receipt_line.base_free_quantity::text,'prior_allocated_base_billed_quantity',prior_billed::text,
          'prior_allocated_base_free_quantity',prior_free::text,'location_id',receipt_line.location_id,'batch_id',receipt_line.batch_id,
          'landed_cost_lineage',landed_cost_lineage));
        resolved_receipt_ids:=resolved_receipt_ids||pg_catalog.jsonb_build_array(receipt.id::text);
        source_versions:=source_versions||pg_catalog.jsonb_build_array(
          pg_catalog.jsonb_build_object('resource_type','purchase_order','id',purchase_order.id,'row_version',purchase_order.row_version,
            'status',purchase_order.status,'order_date',purchase_order.order_date),
          pg_catalog.jsonb_build_object('resource_type','purchase_order_line','id',order_line.id,'purchase_order_id',purchase_order.id),
          pg_catalog.jsonb_build_object('resource_type','goods_receipt','id',receipt.id,'row_version',receipt.row_version,
            'status',receipt.status,'received_at',receipt.received_at,'business_date',receipt_business_date),
          pg_catalog.jsonb_build_object('resource_type','goods_receipt_line','id',receipt_line.id,'goods_receipt_line_id',receipt_line.id,'base_accepted_quantity',receipt_line.base_accepted_quantity::text,'base_free_quantity',receipt_line.base_free_quantity::text,'unit_cost',receipt_line.unit_cost::text),
          pg_catalog.jsonb_build_object('resource_type','receipt_invoice_ceiling','goods_receipt_line_id',receipt_line.id,'allocated_base_billed_quantity',prior_billed::text,'allocated_base_free_quantity',prior_free::text));
        FOR landed_cost_target IN SELECT value FROM pg_catalog.jsonb_array_elements(landed_cost_lineage->'targets') LOOP
          source_versions:=source_versions||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
            'resource_type','landed_cost_stock_target','goods_receipt_line_id',receipt_line.id,
            'location_id',landed_cost_target->>'location_id','branch_id',landed_cost_target->>'branch_id',
            'product_id',landed_cost_target->>'product_id','batch_id',landed_cost_target->>'batch_id',
            'row_version',(landed_cost_target->>'stock_row_version')::bigint,
            'last_ledger_entry_id',landed_cost_target->>'last_ledger_entry_id',
            'on_hand_quantity',landed_cost_target->>'on_hand_quantity',
            'inventory_value',landed_cost_target->>'inventory_value'));
        END LOOP;
      END LOOP;
      IF base_billed IS DISTINCT FROM pg_catalog.round((requested_line->>'billed_quantity')::numeric*line_factor,6)
         OR base_free IS DISTINCT FROM pg_catalog.round((requested_line->>'free_quantity')::numeric*line_factor,6) THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='supplier invoice billed and free quantities do not reconcile exact receipt base allocations'; END IF;
      SELECT * INTO STRICT tax_version FROM erp_automation_reads.resolve_product_tax(organization_id,product.id,invoice_date)
       WHERE taxability='taxable';
      SELECT * INTO STRICT tax_release FROM core.reference_data_releases WHERE id=tax_version.release_id
       AND dataset_kind='hsn_sac_tax' AND status IN ('active','source_snapshot') AND effective_from<=invoice_date
       AND (effective_to IS NULL OR effective_to>=invoice_date) FOR SHARE;
      resolved_lines:=resolved_lines||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'line_number',pg_catalog.jsonb_array_length(resolved_lines)+1,'line_kind','product','line_id',requested_line->>'line_id',
        'purchase_order_line_id',line_purchase_order_line_id,'product_id',product.id,'hsn_code',product.hsn_code,'uom_code',line_uom,'multiplier',line_factor::text,
        'tax_code_version_id',tax_version.id,'taxability','taxable','gst_rate',tax_version.igst_rate::text,'cess_rate',tax_version.cess_rate::text,
        'ruleset_version',tax_version.ruleset_version,'net_value_account_id',inventory_account.id,'inventory_cost_treatment','capitalize',
        'landed_cost_allocation_method',requested_line->>'landed_cost_allocation_method',
        'itc_eligibility','eligible','receipt_cost',receipt_cost::text,'receipt_allocations',resolved_allocations,'input',requested_line));
      source_versions:=source_versions||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'resource_type','supplier_invoice_product_tax','product_id',product.id,'product_row_version',product.row_version,
        'tax_code_version_id',tax_version.id,'tax_version_number',tax_version.version_number,'tax_release_id',tax_release.id,
        'tax_release_ruleset_version',tax_release.ruleset_version));
    END LOOP;
    FOR requested_line IN SELECT value FROM pg_catalog.jsonb_array_elements(COALESCE(request_document->'expense_charge_lines','[]'::jsonb)) LOOP
      SELECT * INTO STRICT profile FROM catalog.commercial_charge_tax_profiles WHERE org_id=organization_id
       AND direction='procurement' AND charge_code=requested_line->>'expense_charge_code' AND status='active'
       AND effective_from<=invoice_date AND (effective_to IS NULL OR effective_to>=invoice_date) FOR SHARE;
      SELECT * INTO STRICT tax_version FROM tax.tax_code_versions WHERE id=profile.tax_code_version_id AND code_kind='sac'
       AND status='active' AND taxability='taxable' AND effective_from<=invoice_date
       AND (effective_to IS NULL OR effective_to>=invoice_date) FOR SHARE;
      SELECT * INTO STRICT tax_release FROM core.reference_data_releases WHERE id=tax_version.release_id
       AND dataset_kind='hsn_sac_tax' AND status='active' AND effective_from<=invoice_date
       AND (effective_to IS NULL OR effective_to>=invoice_date) FOR SHARE;
      IF requested_line->>'charge_inventory_cost_treatment'='capitalize' THEN
        IF NULLIF(requested_line->>'net_value_account_id','')::uuid IS DISTINCT FROM inventory_account.id THEN
          RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='capitalized supplier charge account differs from the canonical inventory role'; END IF;
        expense_account:=inventory_account;
      ELSE
        SELECT * INTO STRICT expense_account FROM finance.accounts WHERE org_id=organization_id
         AND id=NULLIF(requested_line->>'net_value_account_id','')::uuid AND account_type='expense'
         AND currency_code='INR' AND status='active' AND NOT allows_party_posting FOR SHARE;
      END IF;
      resolved_lines:=resolved_lines||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'line_number',pg_catalog.jsonb_array_length(resolved_lines)+1,'line_kind','charge','line_id',requested_line->>'line_id',
        'charge_code',profile.charge_code,'sac_code',tax_version.code,'tax_code_version_id',tax_version.id,
        'taxability','taxable','gst_rate',tax_version.igst_rate::text,'cess_rate',tax_version.cess_rate::text,
        'ruleset_version',tax_version.ruleset_version,'net_value_account_id',expense_account.id,
        'inventory_cost_treatment',requested_line->>'charge_inventory_cost_treatment',
        'landed_cost_allocation_method',requested_line->>'landed_cost_allocation_method',
        'itc_eligibility','eligible','input',requested_line||pg_catalog.jsonb_build_object(
          'charge_code',profile.charge_code,'price_basis',requested_line->>'expense_price_basis',
          'document_discount_eligible',requested_line->'expense_document_discount_eligible')));
      source_versions:=source_versions||pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object('resource_type','commercial_charge_tax_profile','id',profile.id,'row_version',profile.row_version,'charge_code',profile.charge_code),
        pg_catalog.jsonb_build_object('resource_type','supplier_invoice_charge_tax','charge_code',profile.charge_code,
          'tax_code_version_id',tax_version.id,'tax_version_number',tax_version.version_number,
          'tax_release_id',tax_release.id,'tax_release_ruleset_version',tax_release.ruleset_version),
        pg_catalog.jsonb_build_object('resource_type','finance_account','id',expense_account.id,'row_version',expense_account.row_version,'account_type',expense_account.account_type));
    END LOOP;
    IF EXISTS (
      (SELECT value FROM pg_catalog.jsonb_array_elements_text(request_document->'goods_receipt_ids') requested(value)
       EXCEPT SELECT value FROM pg_catalog.jsonb_array_elements_text(resolved_receipt_ids) resolved(value))
      UNION ALL
      (SELECT value FROM pg_catalog.jsonb_array_elements_text(resolved_receipt_ids) resolved(value)
       EXCEPT SELECT value FROM pg_catalog.jsonb_array_elements_text(request_document->'goods_receipt_ids') requested(value))
    ) THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='requested GRN header set differs from the exact receipt allocation lineage'; END IF;
    RETURN pg_catalog.jsonb_build_object('branch_id',branch.id,'supplier_account_id',supplier.id,
      'purchase_order_id',source_purchase_order_id,'goods_receipt_ids',request_document->'goods_receipt_ids',
      'supplier_party_id',supplier_party.id,'supplier_tax_registration_id',supplier_registration.id,
      'supplier_gstin',supplier_registration.registration_number,'supplier_legal_name',supplier_registration.registered_legal_name,
      'supplier_address',pg_catalog.concat_ws(', ',supplier_address.line1,supplier_address.line2,supplier_address.city,supplier_address.state_code,supplier_address.postal_code),
      'buyer_tax_registration_id',buyer_registration.id,'buyer_gstin',buyer_registration.gstin,
      'buyer_legal_name',organization.legal_name,'buyer_address',pg_catalog.concat_ws(', ',branch.address_line1,branch.address_line2,branch.city,branch.state_code,branch.postal_code),
      'invoice_date',invoice_date,'received_date',received_date,'due_date',invoice_date+supplier.payment_days,
      'supply_type',supply_type,'zero_rated_payment_mode','not_applicable','tax_charge_mechanism','normal',
      'place_of_supply_state_code',buyer_registration.state_code,'portal_document_line_id',portal_line.id,
      'portal_taxable_amount',portal_line.taxable_amount::text,'portal_cgst_amount',portal_line.cgst_amount::text,
      'portal_sgst_amount',portal_line.sgst_amount::text,'portal_igst_amount',portal_line.igst_amount::text,
      'portal_cess_amount',portal_line.cess_amount::text,'ruleset_version',erp_automation_reads.tax_ruleset_fingerprint(resolved_lines),'lines',resolved_lines,
      'legal_scope',pg_catalog.jsonb_build_object('country','IN','currency','INR','normal_charge',true,
        'posted_grn_match_required',true,'gstr2b_required',true,'itc_business_use_attestation_required',true,
        'landed_cost_supported',true,'landed_cost_methods',pg_catalog.jsonb_build_array('direct','quantity_weighted','value_weighted'),
        'consumed_variance_role','purchase_price_variance','import_supported',false,'sez_supported',false,'reverse_charge_supported',false),
      'source_versions',source_versions);
END
$function$;

CREATE OR REPLACE FUNCTION "erp_automation_commands"."resolve_sales_invoice_prepare"(organization_id uuid, membership_id uuid, auth_user_id uuid, application_user_id uuid, grant_id uuid, caller_client_id varchar, invoice_id uuid, request_document jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
DECLARE
    branch_id uuid:=NULLIF(request_document->>'branch_id','')::uuid;
    customer_account_id uuid:=NULLIF(request_document->>'customer_account_id','')::uuid;
    delivery_address_id uuid:=NULLIF(request_document->>'delivery_address_id','')::uuid;
    delivery_address_row_version bigint:=NULLIF(request_document->>'delivery_address_row_version','')::bigint;
    from_location_id uuid:=NULLIF(request_document->>'from_location_id','')::uuid;
    invoice_date date:=NULLIF(request_document->>'invoice_date','')::date;
    place_of_supply text;
    zero_mode text:=request_document->>'zero_rated_payment_mode';
    logistics jsonb:=request_document->'logistics';
    transport_mode text:=logistics->>'transport_mode';
    transporter_party_id uuid:=NULLIF(logistics->>'transporter_party_id','')::uuid;
    has_direct boolean;
    has_allocated boolean;
    supply_type text;
    branch core.branches%ROWTYPE;
    organization core.organizations%ROWTYPE;
    customer parties.customer_accounts%ROWTYPE;
    customer_party parties.parties%ROWTYPE;
    customer_registration parties.tax_registrations%ROWTYPE;
    seller_registration tax.registrations%ROWTYPE;
    seller_registration_branch tax.registration_branches%ROWTYPE;
    billing parties.addresses%ROWTYPE;
    shipping parties.addresses%ROWTYPE;
    location inventory.locations%ROWTYPE;
    transporter parties.parties%ROWTYPE;
    transporter_registration parties.tax_registrations%ROWTYPE;
    revenue_account finance.accounts%ROWTYPE;
    product catalog.products%ROWTYPE;
    conversion catalog.uom_conversions%ROWTYPE;
    tax_version tax.tax_code_versions%ROWTYPE;
    tax_release core.reference_data_releases%ROWTYPE;
    profile catalog.commercial_charge_tax_profiles%ROWTYPE;
    batch inventory.batches%ROWTYPE;
    balance inventory.stock_balances%ROWTYPE;
    dispatch_line sales.dispatch_lines%ROWTYPE;
    dispatch_header sales.dispatches%ROWTYPE;
    order_line sales.order_lines%ROWTYPE;
    eligible record;
    requested_line jsonb;
    requested_allocation jsonb;
    resolved_line jsonb;
    resolved_lines jsonb:='[]'::jsonb;
    resolved_allocations jsonb;
    source_versions jsonb:='[]'::jsonb;
    allocation_tracker jsonb:='{}'::jsonb;
    dispatch_tracker jsonb:='{}'::jsonb;
    auto_allocations jsonb;
    allocation_mode text;
    billed numeric(20,6);
    free numeric(20,6);
    base_billed numeric(20,6);
    base_free numeric(20,6);
    allocated_billed numeric(20,6);
    allocated_free numeric(20,6);
    allocation_billed numeric(20,6);
    allocation_free numeric(20,6);
    prior_base numeric(20,6);
    prior_value numeric(20,2);
    current_quantity numeric(20,6);
    current_value numeric(20,2);
    current_unit_cost numeric(20,4);
    extended_cost numeric(20,2);
    existing_billed numeric(20,6);
    existing_free numeric(20,6);
    remaining_billed numeric(20,6);
    remaining_free numeric(20,6);
    candidate_billed numeric(20,6);
    candidate_free numeric(20,6);
    available_entered numeric(20,6);
    total_base numeric(20,6):=0;
    total_value numeric(20,2):=0;
    line_number integer:=0;
    registration_count integer;
    address_count integer;
    bad_count integer;
    ruleset_version text;
BEGIN
    IF organization_id IS NULL OR membership_id IS NULL OR auth_user_id IS NULL
       OR application_user_id IS NULL OR grant_id IS NULL OR invoice_id IS NULL
       OR branch_id IS NULL OR customer_account_id IS NULL OR invoice_date IS NULL
       OR delivery_address_id IS NULL OR delivery_address_row_version IS NULL
       OR delivery_address_row_version<1 OR request_document?'place_of_supply_state_code'
       OR request_document?'shipping_address_id'
       OR request_document->>'tax_charge_mechanism'<>'normal'
       OR zero_mode NOT IN ('not_applicable','with_igst')
       OR pg_catalog.jsonb_typeof(request_document)<>'object'
       OR pg_catalog.jsonb_typeof(request_document->'lines')<>'array'
       OR pg_catalog.jsonb_array_length(request_document->'lines') NOT BETWEEN 1 AND 500
       OR pg_catalog.jsonb_typeof(COALESCE(request_document->'charge_lines','[]'::jsonb))<>'array' THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='sales-invoice resolve input is incomplete or outside the pilot legal scope';
    END IF;
    has_direct:=EXISTS(
      SELECT 1 FROM pg_catalog.jsonb_array_elements(request_document->'lines') line(value)
       WHERE line.value->>'fulfillment_source'='direct_issue');
    has_allocated:=EXISTS(
      SELECT 1 FROM pg_catalog.jsonb_array_elements(request_document->'lines') line(value)
       WHERE line.value->>'fulfillment_source'='dispatch_allocated');
    IF EXISTS(
      SELECT 1 FROM pg_catalog.jsonb_array_elements(request_document->'lines') line(value)
       WHERE line.value->>'fulfillment_source' NOT IN ('direct_issue','dispatch_allocated'))
       OR (has_direct AND (from_location_id IS NULL OR pg_catalog.jsonb_typeof(logistics)<>'object'))
       OR (NOT has_direct AND (from_location_id IS NOT NULL OR logistics IS NOT NULL)) THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='invoice fulfillment source, location, and logistics shape differ';
    END IF;
    IF has_direct THEN
      IF transport_mode NOT IN ('road','rail','air','ship','multimodal','in_person')
         OR NULLIF(logistics->>'distance_km','')::numeric<0
         OR (transport_mode='road' AND (NULLIF(logistics->>'vehicle_number','') IS NULL
             OR logistics->>'vehicle_type' NOT IN ('regular','over_dimensional_cargo')))
         OR (transport_mode<>'road' AND (NULLIF(logistics->>'vehicle_number','') IS NOT NULL
             OR NULLIF(logistics->>'vehicle_type','') IS NOT NULL))
         OR (transport_mode IN ('rail','air','ship','multimodal') AND
             (NULLIF(logistics->>'transport_document_number','') IS NULL
              OR NULLIF(logistics->>'transport_document_date','')::date IS NULL))
         OR ((NULLIF(logistics->>'transport_document_number','') IS NULL) IS DISTINCT FROM
             (NULLIF(logistics->>'transport_document_date','') IS NULL))
         OR (transport_mode='in_person' AND
             (transporter_party_id IS NOT NULL OR NULLIF(logistics->>'transport_document_number','') IS NOT NULL))
         OR (transport_mode<>'in_person' AND transporter_party_id IS NULL) THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='invoice logistics fields do not match the selected transport mode';
      END IF;
    END IF;
    PERFORM 1
      FROM core.memberships membership
      JOIN core.users user_row ON user_row.id=membership.user_id
      JOIN core.organizations organization_row ON organization_row.id=membership.org_id
      JOIN automation.agent_grants grant_row ON grant_row.org_id=membership.org_id
       AND grant_row.subject_membership_id=membership.id
      JOIN automation.agent_grant_capabilities capability ON capability.org_id=grant_row.org_id
       AND capability.agent_grant_id=grant_row.id
     WHERE membership.org_id=organization_id AND membership.id=membership_id
       AND membership.user_id=application_user_id AND membership.status='active'
       AND user_row.auth_user_id=auth_user_id AND user_row.status='active'
       AND organization_row.status='active' AND grant_row.id=grant_id
       AND grant_row.client_id=caller_client_id AND grant_row.status='active'
       AND grant_row.expires_at>pg_catalog.transaction_timestamp()
       AND (grant_row.branch_id IS NULL OR grant_row.branch_id=branch_id)
       AND capability.capability_code='sales.invoice.prepare'
       AND capability.operation_mode='write' AND capability.status='active';
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='sales-invoice delegated authority is inactive'; END IF;
    PERFORM erp_security.activate_context(auth_user_id,organization_id);
    IF erp_security.current_membership_id() IS DISTINCT FROM membership_id THEN
      RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='sales-invoice verified auth context resolved a different membership'; END IF;
    IF invoice_date>"erp_core_commands"."current_organization_business_date"() THEN
      RAISE EXCEPTION USING ERRCODE='22007', MESSAGE='sales invoice date cannot be in the future'; END IF;
    IF erp_security.can_access_branch(branch_id) IS DISTINCT FROM true
       OR erp_security.has_permission('sales.invoice.create',branch_id) IS DISTINCT FROM true
       OR erp_security.has_permission('sales.invoice.post',branch_id) IS DISTINCT FROM true
       OR erp_security.has_permission('automation.command.execute',branch_id) IS DISTINCT FROM true
       OR erp_security.has_permission('finance.journal.post',NULL::uuid) IS DISTINCT FROM true
       OR (has_direct AND erp_security.has_permission('inventory.document.post',branch_id) IS DISTINCT FROM true) THEN
      RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='sales-invoice cross-domain permission is inactive'; END IF;
    SELECT * INTO STRICT organization FROM core.organizations
     WHERE id=organization_id AND status='active' FOR SHARE;
    IF organization.country_code<>'IN' OR organization.base_currency<>'INR' THEN
      RAISE EXCEPTION USING ERRCODE='0A000', MESSAGE='sales-invoice pilot supports only Indian INR organizations'; END IF;
    SELECT * INTO STRICT branch FROM core.branches
     WHERE org_id=organization_id AND id=branch_id AND status='active' FOR SHARE;
    SELECT count(*) INTO registration_count FROM tax.registration_branches association
      JOIN tax.registrations registration ON registration.org_id=association.org_id
       AND registration.id=association.registration_id
     WHERE association.org_id=organization_id AND association.branch_id=branch.id
       AND association.status='active' AND association.effective_from<=invoice_date
       AND (association.effective_to IS NULL OR association.effective_to>=invoice_date)
       AND registration.state_code=branch.state_code AND registration.status='active'
       AND registration.effective_from<=invoice_date
       AND (registration.effective_to IS NULL OR registration.effective_to>=invoice_date);
    IF registration_count<>1 THEN RAISE EXCEPTION USING ERRCODE='21000', MESSAGE='seller has no exact effective branch-state GST registration'; END IF;
    SELECT registration.* INTO STRICT seller_registration FROM tax.registration_branches association
      JOIN tax.registrations registration ON registration.org_id=association.org_id
       AND registration.id=association.registration_id
     WHERE association.org_id=organization_id AND association.branch_id=branch.id
       AND association.status='active' AND association.effective_from<=invoice_date
       AND (association.effective_to IS NULL OR association.effective_to>=invoice_date)
       AND registration.state_code=branch.state_code AND registration.status='active'
       AND registration.effective_from<=invoice_date
       AND (registration.effective_to IS NULL OR registration.effective_to>=invoice_date)
     FOR SHARE OF association,registration;
    SELECT * INTO STRICT seller_registration_branch FROM tax.registration_branches association
     WHERE association.org_id=organization_id AND association.registration_id=seller_registration.id
       AND association.branch_id=branch.id AND association.status='active'
       AND association.effective_from<=invoice_date
       AND (association.effective_to IS NULL OR association.effective_to>=invoice_date) FOR SHARE;
    IF seller_registration.registration_type<>'regular' THEN
      RAISE EXCEPTION USING ERRCODE='0A000', MESSAGE='pilot invoice posting requires a regular seller GST registration'; END IF;
    SELECT * INTO STRICT customer FROM parties.customer_accounts
     WHERE org_id=organization_id AND id=customer_account_id AND status='active' FOR SHARE;
    SELECT * INTO STRICT customer_party FROM parties.parties
     WHERE org_id=organization_id AND id=customer.party_id AND status='active' FOR SHARE;
    SELECT count(*) INTO address_count FROM parties.addresses
     WHERE org_id=organization_id AND party_id=customer.party_id AND address_kind='billing'
       AND is_primary AND status='active' AND valid_from<=invoice_date
       AND (valid_until IS NULL OR valid_until>=invoice_date);
    IF address_count>1 THEN RAISE EXCEPTION USING ERRCODE='21000', MESSAGE='customer billing address is ambiguous';
    ELSIF address_count=1 THEN
      SELECT * INTO STRICT billing FROM parties.addresses WHERE org_id=organization_id AND party_id=customer.party_id
       AND address_kind='billing' AND is_primary AND status='active' AND valid_from<=invoice_date
       AND (valid_until IS NULL OR valid_until>=invoice_date) FOR SHARE;
    ELSE
      SELECT * INTO STRICT billing FROM parties.addresses WHERE org_id=organization_id AND party_id=customer.party_id
       AND address_kind='registered' AND is_primary AND status='active' AND valid_from<=invoice_date
       AND (valid_until IS NULL OR valid_until>=invoice_date) FOR SHARE;
    END IF;
    SELECT * INTO STRICT shipping FROM parties.addresses
     WHERE org_id=organization_id AND id=delivery_address_id
       AND party_id=customer.party_id
       AND address_kind IN ('registered','billing','shipping') AND status='active'
       AND row_version=delivery_address_row_version
       AND valid_from<=invoice_date AND (valid_until IS NULL OR valid_until>=invoice_date)
     FOR SHARE;
    place_of_supply:=shipping.state_code;
    IF billing.country_code<>'IN' OR shipping.country_code<>'IN' THEN
      RAISE EXCEPTION USING ERRCODE='0A000', MESSAGE='export sales invoices remain fail-closed in the pilot'; END IF;
    SELECT count(*) INTO registration_count FROM parties.tax_registrations
     WHERE org_id=organization_id AND party_id=customer.party_id AND registration_type='GSTIN'
       AND state_code=place_of_supply
       AND status='active' AND (valid_from IS NULL OR valid_from<=invoice_date)
       AND (valid_until IS NULL OR valid_until>=invoice_date);
    IF registration_count>1 THEN RAISE EXCEPTION USING ERRCODE='21000', MESSAGE='customer GST registration is ambiguous';
    ELSIF registration_count=1 THEN
      SELECT * INTO STRICT customer_registration FROM parties.tax_registrations
       WHERE org_id=organization_id AND party_id=customer.party_id AND registration_type='GSTIN'
         AND state_code=place_of_supply
         AND status='active' AND (valid_from IS NULL OR valid_from<=invoice_date)
         AND (valid_until IS NULL OR valid_until>=invoice_date) FOR SHARE;
    END IF;
    supply_type:=CASE WHEN registration_count=1 AND customer_registration.taxpayer_type IN ('sez_unit','sez_developer')
      THEN 'sez' WHEN seller_registration.state_code=place_of_supply THEN 'intra_state' ELSE 'inter_state' END;
    IF place_of_supply<>shipping.state_code
       OR (supply_type='sez' AND (zero_mode<>'with_igst' OR customer_registration.state_code<>place_of_supply))
       OR (supply_type<>'sez' AND zero_mode<>'not_applicable') THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='place of supply or zero-rated mode lacks exact supported legal evidence'; END IF;
     SELECT * INTO STRICT revenue_account FROM finance.accounts AS resolved_revenue_account
      WHERE resolved_revenue_account.org_id=organization_id
        AND resolved_revenue_account.id=erp_commercial_commands.resolve_role_account(
          organization_id,branch_id,'sales_revenue','income','INR',false) FOR SHARE;
    IF has_direct THEN
      SELECT * INTO STRICT location FROM inventory.locations
       WHERE org_id=organization_id AND id=from_location_id AND branch_id=branch_id
         AND status='active' AND allows_sale FOR SHARE;
      IF branch.postal_code!~'^[0-9]{6}$' OR shipping.postal_code!~'^[0-9]{6}$' THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='direct invoice requires exact Indian origin and destination pincodes'; END IF;
      IF transporter_party_id IS NOT NULL THEN
        SELECT * INTO STRICT transporter FROM parties.parties
         WHERE org_id=organization_id AND id=transporter_party_id AND status='active' FOR SHARE;
        SELECT count(*) INTO registration_count FROM parties.tax_registrations
         WHERE org_id=organization_id AND party_id=transporter.id AND registration_type='GSTIN'
           AND status='active' AND (valid_from IS NULL OR valid_from<=invoice_date)
           AND (valid_until IS NULL OR valid_until>=invoice_date);
        IF registration_count>1 THEN RAISE EXCEPTION USING ERRCODE='21000', MESSAGE='transporter GST registration is ambiguous';
        ELSIF registration_count=1 THEN
          SELECT * INTO STRICT transporter_registration FROM parties.tax_registrations
           WHERE org_id=organization_id AND party_id=transporter.id AND registration_type='GSTIN'
             AND status='active' AND (valid_from IS NULL OR valid_from<=invoice_date)
             AND (valid_until IS NULL OR valid_until>=invoice_date) FOR SHARE;
        END IF;
      END IF;
    END IF;
    source_versions:=source_versions||pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('resource_type','organization','id',organization.id,'row_version',organization.row_version),
      pg_catalog.jsonb_build_object('resource_type','branch','id',branch.id,'row_version',branch.row_version),
      pg_catalog.jsonb_build_object('resource_type','seller_tax_registration','id',seller_registration.id,'row_version',seller_registration.row_version,'effective_from',seller_registration.effective_from,'effective_to',seller_registration.effective_to),
      pg_catalog.jsonb_build_object('resource_type','seller_registration_branch','registration_id',seller_registration_branch.registration_id,'branch_id',seller_registration_branch.branch_id,'status',seller_registration_branch.status,'effective_from',seller_registration_branch.effective_from,'effective_to',seller_registration_branch.effective_to),
      pg_catalog.jsonb_build_object('resource_type','customer_account','id',customer.id,'row_version',customer.row_version),
      pg_catalog.jsonb_build_object('resource_type','customer_party','id',customer_party.id,'row_version',customer_party.row_version),
      pg_catalog.jsonb_build_object('resource_type','billing_address','id',billing.id,'row_version',billing.row_version,'valid_from',billing.valid_from,'valid_until',billing.valid_until),
      pg_catalog.jsonb_build_object('resource_type','shipping_address','id',shipping.id,'row_version',shipping.row_version,'valid_from',shipping.valid_from,'valid_until',shipping.valid_until),
      pg_catalog.jsonb_build_object('resource_type','finance_account','role','sales_revenue','id',revenue_account.id,'row_version',revenue_account.row_version)
    );
    IF customer_registration.id IS NOT NULL THEN
      source_versions:=source_versions||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'resource_type','customer_tax_registration','id',customer_registration.id,'row_version',customer_registration.row_version,
        'taxpayer_type',customer_registration.taxpayer_type,'valid_from',customer_registration.valid_from,'valid_until',customer_registration.valid_until));
    END IF;
    IF has_direct THEN
      source_versions:=source_versions||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'resource_type','inventory_location','id',location.id,'row_version',location.row_version,'allows_sale',location.allows_sale));
      IF transporter.id IS NOT NULL THEN source_versions:=source_versions||pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object('resource_type','transporter_party','id',transporter.id,'row_version',transporter.row_version)); END IF;
      IF transporter_registration.id IS NOT NULL THEN source_versions:=source_versions||pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object('resource_type','transporter_gstin','id',transporter_registration.id,'row_version',transporter_registration.row_version,'registration_number',transporter_registration.registration_number)); END IF;
    END IF;

    FOR requested_line IN SELECT value FROM pg_catalog.jsonb_array_elements(request_document->'lines') LOOP
      billed:=NULLIF(requested_line->>'billed_quantity','')::numeric;
      free:=NULLIF(requested_line->>'free_quantity','')::numeric;
      IF billed<0 OR free<0 OR billed+free<=0 OR NULLIF(requested_line->>'line_id','')::uuid IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='invoice product line quantities are invalid'; END IF;
      SELECT * INTO STRICT product FROM catalog.products WHERE org_id=organization_id
       AND id=NULLIF(requested_line->>'product_id','')::uuid AND status='active' FOR SHARE;
      SELECT * INTO STRICT conversion FROM catalog.uom_conversions WHERE org_id=organization_id
       AND id=NULLIF(requested_line->>'uom_conversion_id','')::uuid AND product_id=product.id
       AND status='active' AND to_uom_code=product.base_uom_code AND valid_from<=invoice_date
       AND (valid_until IS NULL OR valid_until>=invoice_date) FOR SHARE;
      SELECT * INTO STRICT tax_version FROM erp_automation_reads.resolve_product_tax(organization_id,product.id,invoice_date);
      SELECT * INTO STRICT tax_release FROM core.reference_data_releases WHERE id=tax_version.release_id
       AND dataset_kind='hsn_sac_tax' AND status IN ('active','source_snapshot') AND effective_from<=invoice_date
       AND (effective_to IS NULL OR effective_to>=invoice_date) FOR SHARE;
      base_billed:=pg_catalog.round(billed*conversion.multiplier,6);
      base_free:=pg_catalog.round(free*conversion.multiplier,6);
      resolved_allocations:='[]'::jsonb; allocated_billed:=0; allocated_free:=0;
      order_line.id:=NULL;
      IF requested_line->>'fulfillment_source'='direct_issue' THEN
        allocation_mode:=COALESCE(NULLIF(requested_line->>'batch_allocation_mode',''),
          CASE WHEN requested_line->'batch_allocations' IS NULL THEN 'auto_fefo' ELSE 'explicit_fefo' END);
        IF allocation_mode NOT IN ('auto_fefo','explicit_fefo') THEN
          RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='direct invoice batch allocation mode is invalid';
        END IF;
        source_versions:=source_versions||pg_catalog.jsonb_build_array(
          pg_catalog.jsonb_build_object('resource_type','invoice_batch_allocation_policy',
            'invoice_line_id',requested_line->>'line_id','mode',allocation_mode,
            'algorithm_version','sales_invoice_auto_fefo_v1','later_expiry_override_supported',false));
        IF allocation_mode='auto_fefo' THEN
          IF requested_line->'dispatch_allocations' IS NOT NULL THEN
            RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='automatic FEFO invoice line cannot carry dispatch allocations'; END IF;
          auto_allocations:='[]'::jsonb;
          remaining_billed:=billed;
          remaining_free:=free;
          FOR eligible IN
            SELECT batch_row.id AS batch_id,batch_row.batch_number,batch_row.expires_on,
                   stock.on_hand_quantity-
                     coalesce((allocation_tracker#>>ARRAY[batch_row.id::text,'base_quantity'])::numeric,0)
                     AS on_hand_quantity
              FROM inventory.stock_balances stock
              JOIN inventory.batches batch_row ON batch_row.org_id=stock.org_id
               AND batch_row.id=stock.batch_id
             WHERE stock.org_id=organization_id AND stock.location_id=location.id
               AND stock.product_id=product.id
               AND stock.on_hand_quantity-
                     coalesce((allocation_tracker#>>ARRAY[batch_row.id::text,'base_quantity'])::numeric,0)>0
               AND batch_row.lot_kind='manufacturer_batch' AND batch_row.status='released'
               AND batch_row.released_at IS NOT NULL AND batch_row.expires_on IS NOT NULL
               AND invoice_date<batch_row.expires_on
             ORDER BY batch_row.expires_on,batch_row.batch_number,batch_row.id
             FOR SHARE OF stock,batch_row
          LOOP
            available_entered:=pg_catalog.trunc(eligible.on_hand_quantity/conversion.multiplier,6);
            candidate_billed:=LEAST(remaining_billed,available_entered);
            available_entered:=available_entered-candidate_billed;
            candidate_free:=LEAST(remaining_free,available_entered);
            IF candidate_billed+candidate_free>0 THEN
              auto_allocations:=auto_allocations||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
                'batch_id',eligible.batch_id,'billed_quantity',candidate_billed::text,
                'free_quantity',candidate_free::text));
              remaining_billed:=remaining_billed-candidate_billed;
              remaining_free:=remaining_free-candidate_free;
            END IF;
            EXIT WHEN remaining_billed=0 AND remaining_free=0;
          END LOOP;
          IF remaining_billed<>0 OR remaining_free<>0 THEN
            RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='automatic FEFO allocation cannot satisfy locked stock'; END IF;
          IF requested_line->'batch_allocations' IS NULL THEN
            requested_line:=pg_catalog.jsonb_set(requested_line,'{batch_allocations}',auto_allocations,true);
          ELSIF pg_catalog.jsonb_typeof(requested_line->'batch_allocations')<>'array'
             OR pg_catalog.jsonb_array_length(requested_line->'batch_allocations')<>pg_catalog.jsonb_array_length(auto_allocations)
             OR EXISTS (
               WITH expected AS (
                 SELECT value,ordinality FROM pg_catalog.jsonb_array_elements(auto_allocations) WITH ORDINALITY item(value,ordinality)
               ), supplied AS (
                 SELECT value,ordinality FROM pg_catalog.jsonb_array_elements(requested_line->'batch_allocations') WITH ORDINALITY item(value,ordinality)
               )
               SELECT 1 FROM expected FULL JOIN supplied USING(ordinality)
                WHERE ROW(expected.value->>'batch_id',expected.value->>'billed_quantity',expected.value->>'free_quantity')
                  IS DISTINCT FROM ROW(supplied.value->>'batch_id',supplied.value->>'billed_quantity',supplied.value->>'free_quantity')
             ) THEN
            RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='automatic FEFO allocation changed before persistence';
          END IF;
        END IF;
        IF pg_catalog.jsonb_typeof(requested_line->'batch_allocations')<>'array'
           OR pg_catalog.jsonb_array_length(requested_line->'batch_allocations')<1
           OR requested_line->'dispatch_allocations' IS NOT NULL
           OR (SELECT count(DISTINCT value->>'batch_id') FROM pg_catalog.jsonb_array_elements(requested_line->'batch_allocations'))
              <>pg_catalog.jsonb_array_length(requested_line->'batch_allocations') THEN
          RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='direct invoice batch allocations are invalid'; END IF;
        FOR requested_allocation IN SELECT value FROM pg_catalog.jsonb_array_elements(requested_line->'batch_allocations') LOOP
          allocation_billed:=NULLIF(requested_allocation->>'billed_quantity','')::numeric;
          allocation_free:=NULLIF(requested_allocation->>'free_quantity','')::numeric;
          IF allocation_billed<0 OR allocation_free<0 OR allocation_billed+allocation_free<=0
             OR (allocation_mode='explicit_fefo'
                 AND NULLIF(requested_allocation->>'inventory_line_id','')::uuid IS NULL) THEN
            RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='direct invoice batch allocation is invalid'; END IF;
          SELECT * INTO STRICT batch FROM inventory.batches WHERE org_id=organization_id
           AND id=NULLIF(requested_allocation->>'batch_id','')::uuid AND product_id=product.id
           AND lot_kind='manufacturer_batch' AND status='released' AND released_at IS NOT NULL
           AND expires_on IS NOT NULL AND invoice_date<expires_on FOR SHARE;
          SELECT * INTO STRICT balance FROM inventory.stock_balances WHERE org_id=organization_id
           AND location_id=location.id AND product_id=product.id AND batch_id=batch.id FOR SHARE;
          prior_base:=coalesce((allocation_tracker#>>ARRAY[batch.id::text,'base_quantity'])::numeric,0);
          prior_value:=coalesce((allocation_tracker#>>ARRAY[batch.id::text,'issued_value'])::numeric,0);
          current_quantity:=balance.on_hand_quantity-prior_base;
          current_value:=balance.inventory_value-prior_value;
          current_unit_cost:=CASE WHEN current_quantity=0 THEN 0 ELSE pg_catalog.round(current_value/current_quantity,4) END;
          IF pg_catalog.round((allocation_billed+allocation_free)*conversion.multiplier,6)>current_quantity THEN
            RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='direct invoice batch allocation exceeds locked stock'; END IF;
          extended_cost:=CASE WHEN pg_catalog.round((allocation_billed+allocation_free)*conversion.multiplier,6)=current_quantity
            THEN current_value ELSE pg_catalog.round(pg_catalog.round((allocation_billed+allocation_free)*conversion.multiplier,6)*current_unit_cost,2) END;
          allocation_tracker:=pg_catalog.jsonb_set(allocation_tracker,ARRAY[batch.id::text],pg_catalog.jsonb_build_object(
            'base_quantity',(prior_base+pg_catalog.round((allocation_billed+allocation_free)*conversion.multiplier,6))::text,
            'issued_value',(prior_value+extended_cost)::text),true);
          line_number:=line_number+1;
          resolved_allocations:=resolved_allocations||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
            'line_number',line_number,'inventory_line_id',requested_allocation->>'inventory_line_id','batch_id',batch.id,
            'batch_number',batch.batch_number,'batch_row_version',batch.row_version,'expires_on',batch.expires_on,
            'billed_quantity',allocation_billed::text,'free_quantity',allocation_free::text,
            'base_billed_quantity',pg_catalog.round(allocation_billed*conversion.multiplier,6)::text,
            'base_free_quantity',pg_catalog.round(allocation_free*conversion.multiplier,6)::text,
            'stock_balance_row_version',balance.row_version,'on_hand_quantity',balance.on_hand_quantity::text,
            'inventory_value',balance.inventory_value::text,'unit_cost',current_unit_cost::text,'extended_cost',extended_cost::text));
          source_versions:=source_versions||pg_catalog.jsonb_build_array(
            pg_catalog.jsonb_build_object('resource_type','manufacturer_batch','id',batch.id,'row_version',batch.row_version,'product_id',batch.product_id,'expires_on',batch.expires_on,'status',batch.status),
            pg_catalog.jsonb_build_object('resource_type','stock_balance','location_id',balance.location_id,'product_id',balance.product_id,'batch_id',balance.batch_id,'row_version',balance.row_version,'on_hand_quantity',balance.on_hand_quantity::text,'inventory_value',balance.inventory_value::text,'average_unit_cost',balance.average_unit_cost::text));
          allocated_billed:=allocated_billed+allocation_billed; allocated_free:=allocated_free+allocation_free;
          total_base:=total_base+pg_catalog.round((allocation_billed+allocation_free)*conversion.multiplier,6);
          total_value:=total_value+extended_cost;
        END LOOP;
        IF allocated_billed IS DISTINCT FROM billed OR allocated_free IS DISTINCT FROM free THEN
          RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='direct invoice batches do not reconcile billed and free quantities separately'; END IF;
      ELSE
        IF pg_catalog.jsonb_typeof(requested_line->'dispatch_allocations')<>'array'
           OR pg_catalog.jsonb_array_length(requested_line->'dispatch_allocations')<1
           OR requested_line->'batch_allocations' IS NOT NULL
           OR (SELECT count(DISTINCT value->>'dispatch_line_id') FROM pg_catalog.jsonb_array_elements(requested_line->'dispatch_allocations'))
              <>pg_catalog.jsonb_array_length(requested_line->'dispatch_allocations') THEN
          RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='invoice dispatch allocations are invalid'; END IF;
        FOR requested_allocation IN SELECT value FROM pg_catalog.jsonb_array_elements(requested_line->'dispatch_allocations') LOOP
          allocation_billed:=NULLIF(requested_allocation->>'allocated_base_billed_quantity','')::numeric;
          allocation_free:=NULLIF(requested_allocation->>'allocated_base_free_quantity','')::numeric;
          IF allocation_billed<0 OR allocation_free<0 OR allocation_billed+allocation_free<=0
             OR NULLIF(requested_allocation->>'invoice_dispatch_allocation_id','')::uuid IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='invoice dispatch allocation quantity is invalid'; END IF;
          SELECT * INTO STRICT dispatch_line FROM sales.dispatch_lines WHERE org_id=organization_id
           AND id=NULLIF(requested_allocation->>'dispatch_line_id','')::uuid FOR SHARE;
          SELECT * INTO STRICT dispatch_header FROM sales.dispatches WHERE org_id=organization_id
           AND id=dispatch_line.dispatch_id AND status='posted' AND branch_id=branch_id
           AND customer_account_id=customer.id AND shipping_address_id=shipping.id FOR SHARE;
          IF invoice_date<dispatch_header.dispatch_date THEN
            RAISE EXCEPTION USING ERRCODE='22007', MESSAGE='sales invoice date cannot precede an allocated dispatch date'; END IF;
          IF order_line.id IS NULL THEN
            SELECT * INTO STRICT order_line FROM sales.order_lines WHERE org_id=organization_id
             AND id=dispatch_line.order_line_id AND line_kind='product' FOR SHARE;
          ELSIF order_line.id IS DISTINCT FROM dispatch_line.order_line_id THEN
            RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='one invoice line cannot combine different approved order lines'; END IF;
          IF ROW(dispatch_line.product_id,order_line.product_id,order_line.uom_code,order_line.uom_conversion_factor,
                 order_line.quoted_unit_rate,order_line.price_basis,order_line.free_supply_tax_treatment,order_line.tax_code_version_id)
             IS DISTINCT FROM ROW(product.id,product.id,conversion.from_uom_code,conversion.multiplier,
                 (requested_line->>'quoted_unit_rate')::numeric,requested_line->>'price_basis',
                 requested_line->>'free_supply_tax_treatment',tax_version.id) THEN
            RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='dispatch invoice terms differ from the approved source order line'; END IF;
          SELECT coalesce(sum(allocation.allocated_base_billed_quantity),0),coalesce(sum(allocation.allocated_base_free_quantity),0)
            INTO existing_billed,existing_free FROM sales.invoice_dispatch_allocations allocation
            JOIN sales.invoice_lines invoice_line ON invoice_line.org_id=allocation.org_id AND invoice_line.id=allocation.invoice_line_id
           WHERE allocation.org_id=organization_id AND allocation.dispatch_line_id=dispatch_line.id
             AND invoice_line.invoice_id<>invoice_id;
          prior_base:=coalesce((dispatch_tracker#>>ARRAY[dispatch_line.id::text,'billed'])::numeric,0);
          prior_value:=coalesce((dispatch_tracker#>>ARRAY[dispatch_line.id::text,'free'])::numeric,0);
          IF existing_billed+prior_base+allocation_billed>dispatch_line.base_billed_quantity
             OR existing_free+prior_value+allocation_free>dispatch_line.base_free_quantity THEN
            RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='invoice exceeds separate dispatch billed or free ceiling'; END IF;
          dispatch_tracker:=pg_catalog.jsonb_set(dispatch_tracker,ARRAY[dispatch_line.id::text],
            pg_catalog.jsonb_build_object('billed',(prior_base+allocation_billed)::text,'free',(prior_value+allocation_free)::text),true);
          IF (SELECT count(*) FROM (
            SELECT 1 FROM inventory.inventory_document_lines issue_line
            JOIN inventory.inventory_documents issue ON issue.org_id=issue_line.org_id
             AND issue.id=issue_line.inventory_document_id AND issue.sales_dispatch_id=dispatch_header.id
             AND issue.status='posted' AND issue.document_type='sales_issue'
            JOIN finance.accounting_events valuation ON valuation.org_id=issue.org_id
             AND valuation.inventory_document_id=issue.id AND valuation.event_type='inventory_valuation'
           WHERE issue_line.org_id=organization_id AND issue_line.sales_dispatch_line_id=dispatch_line.id
             AND ROW(issue_line.product_id,issue_line.batch_id,issue_line.uom_code)
                 IS NOT DISTINCT FROM ROW(dispatch_line.product_id,dispatch_line.batch_id,dispatch_line.uom_code)
          ) posted_lineage)<>1 THEN
            RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='dispatch invoice allocation lacks posted stock and valuation lineage'; END IF;
          line_number:=line_number+1;
          resolved_allocations:=resolved_allocations||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
            'line_number',line_number,'invoice_dispatch_allocation_id',requested_allocation->>'invoice_dispatch_allocation_id',
            'dispatch_line_id',dispatch_line.id,'dispatch_id',dispatch_header.id,'dispatch_date',dispatch_header.dispatch_date,
            'dispatch_row_version',dispatch_header.row_version,'order_line_id',order_line.id,
            'allocated_base_billed_quantity',allocation_billed::text,'allocated_base_free_quantity',allocation_free::text));
          source_versions:=source_versions||pg_catalog.jsonb_build_array(
            pg_catalog.jsonb_build_object('resource_type','sales_dispatch','id',dispatch_header.id,
              'row_version',dispatch_header.row_version,'status',dispatch_header.status,'dispatch_date',dispatch_header.dispatch_date),
            pg_catalog.jsonb_build_object('resource_type','sales_dispatch_line','id',dispatch_line.id,'source_hash',pg_catalog.encode(extensions.digest(pg_catalog.convert_to(pg_catalog.to_jsonb(dispatch_line)::text,'UTF8'),'sha256'),'hex')),
            pg_catalog.jsonb_build_object('resource_type','sales_order_line','id',order_line.id,'source_hash',pg_catalog.encode(extensions.digest(pg_catalog.convert_to(pg_catalog.to_jsonb(order_line)::text,'UTF8'),'sha256'),'hex')));
          allocated_billed:=allocated_billed+allocation_billed; allocated_free:=allocated_free+allocation_free;
        END LOOP;
        IF allocated_billed IS DISTINCT FROM base_billed OR allocated_free IS DISTINCT FROM base_free THEN
          RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='invoice dispatch allocations do not reconcile base billed and free quantities separately'; END IF;
      END IF;
      resolved_line:=pg_catalog.jsonb_build_object(
        'line_number',pg_catalog.jsonb_array_length(resolved_lines)+1,'line_kind','product',
        'line_id',requested_line->>'line_id','product_id',product.id,'product_row_version',product.row_version,
        'hsn_code',product.hsn_code,'uom_conversion_id',conversion.id,'uom_code',conversion.from_uom_code,
        'to_uom_code',conversion.to_uom_code,'multiplier',conversion.multiplier::text,
        'uom_valid_from',conversion.valid_from,'uom_valid_until',conversion.valid_until,
        'tax_code_version_id',tax_version.id,'tax_version_number',tax_version.version_number,
        'tax_effective_from',tax_version.effective_from,'tax_effective_to',tax_version.effective_to,
        'tax_release_id',tax_release.id,'tax_release_ruleset_version',tax_release.ruleset_version,
        'taxability',CASE WHEN supply_type='sez' THEN 'zero_rated' ELSE tax_version.taxability END,
        'gst_rate',CASE WHEN supply_type='sez' OR tax_version.taxability='taxable' THEN tax_version.igst_rate::text ELSE '0' END,
        'cess_rate',CASE WHEN supply_type<>'sez' AND tax_version.taxability='taxable' THEN tax_version.cess_rate::text ELSE '0' END,
        'ruleset_version',tax_version.ruleset_version,'revenue_account_id',revenue_account.id,
        'order_line_id',order_line.id,'fulfillment_source',requested_line->>'fulfillment_source',
        'batch_allocation_mode',CASE WHEN requested_line->>'fulfillment_source'='direct_issue' THEN allocation_mode END,
        CASE WHEN requested_line->>'fulfillment_source'='direct_issue' THEN 'batch_allocations' ELSE 'dispatch_allocations' END,
        resolved_allocations,'input',requested_line);
      resolved_lines:=resolved_lines||pg_catalog.jsonb_build_array(resolved_line);
      source_versions:=source_versions||pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object('resource_type','product','id',product.id,'row_version',product.row_version,
          'uom_conversion_id',conversion.id,'uom_valid_from',conversion.valid_from,'uom_valid_until',conversion.valid_until,
          'tax_code_version_id',tax_version.id,'tax_version_number',tax_version.version_number,
          'tax_effective_from',tax_version.effective_from,'tax_effective_to',tax_version.effective_to,
          'tax_release_id',tax_release.id,'tax_release_ruleset_version',tax_release.ruleset_version));
    END LOOP;
    FOR requested_line IN SELECT value FROM pg_catalog.jsonb_array_elements(COALESCE(request_document->'charge_lines','[]'::jsonb)) LOOP
      SELECT * INTO STRICT profile FROM catalog.commercial_charge_tax_profiles WHERE org_id=organization_id
       AND direction='sales' AND charge_code=requested_line->>'charge_code' AND status='active'
       AND effective_from<=invoice_date AND (effective_to IS NULL OR effective_to>=invoice_date) FOR SHARE;
      SELECT * INTO STRICT tax_version FROM tax.tax_code_versions WHERE id=profile.tax_code_version_id
       AND code_kind='sac' AND status='active' AND effective_from<=invoice_date
       AND (effective_to IS NULL OR effective_to>=invoice_date) FOR SHARE;
      SELECT * INTO STRICT tax_release FROM core.reference_data_releases WHERE id=tax_version.release_id
       AND dataset_kind='hsn_sac_tax' AND status='active' AND effective_from<=invoice_date
       AND (effective_to IS NULL OR effective_to>=invoice_date) FOR SHARE;
      resolved_lines:=resolved_lines||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'line_number',pg_catalog.jsonb_array_length(resolved_lines)+1,'line_kind','charge','line_id',requested_line->>'line_id',
        'charge_code',profile.charge_code,'charge_tax_profile_id',profile.id,'charge_tax_profile_row_version',profile.row_version,
        'charge_tax_profile_effective_from',profile.effective_from,'charge_tax_profile_effective_to',profile.effective_to,
        'sac_code',tax_version.code,'tax_code_version_id',tax_version.id,'tax_version_number',tax_version.version_number,
        'tax_effective_from',tax_version.effective_from,'tax_effective_to',tax_version.effective_to,
        'tax_release_id',tax_release.id,'tax_release_ruleset_version',tax_release.ruleset_version,
        'taxability',CASE WHEN supply_type='sez' THEN 'zero_rated' ELSE tax_version.taxability END,
        'gst_rate',CASE WHEN supply_type='sez' OR tax_version.taxability='taxable' THEN tax_version.igst_rate::text ELSE '0' END,
        'cess_rate',CASE WHEN supply_type<>'sez' AND tax_version.taxability='taxable' THEN tax_version.cess_rate::text ELSE '0' END,
        'ruleset_version',tax_version.ruleset_version,'revenue_account_id',revenue_account.id,'input',requested_line));
      source_versions:=source_versions||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'resource_type','commercial_charge_tax_profile','id',profile.id,'row_version',profile.row_version,
        'charge_code',profile.charge_code,'effective_from',profile.effective_from,'effective_to',profile.effective_to,
        'tax_code_version_id',tax_version.id,'tax_version_number',tax_version.version_number,
        'tax_effective_from',tax_version.effective_from,'tax_effective_to',tax_version.effective_to,
        'tax_release_id',tax_release.id,'tax_release_ruleset_version',tax_release.ruleset_version));
    END LOOP;
    ruleset_version:=erp_automation_reads.tax_ruleset_fingerprint(resolved_lines);
    IF has_direct THEN
      WITH requested AS (
        SELECT (line.value->>'product_id')::uuid product_id,(allocation.value->>'batch_id')::uuid batch_id,
          sum(pg_catalog.round(((allocation.value->>'billed_quantity')::numeric+(allocation.value->>'free_quantity')::numeric)*requested_conversion.multiplier,6)) requested_base
        FROM pg_catalog.jsonb_array_elements(request_document->'lines') line(value)
        JOIN catalog.uom_conversions requested_conversion
          ON requested_conversion.org_id=organization_id
         AND requested_conversion.id=(line.value->>'uom_conversion_id')::uuid
        CROSS JOIN LATERAL pg_catalog.jsonb_array_elements(COALESCE(line.value->'batch_allocations','[]'::jsonb)) allocation(value)
        WHERE line.value->>'fulfillment_source'='direct_issue'
        GROUP BY (line.value->>'product_id')::uuid,(allocation.value->>'batch_id')::uuid
      ), totals AS (SELECT product_id,sum(requested_base) requested_base FROM requested GROUP BY product_id),
      /* sales_invoice_fefo_expiry_date_equivalence_v3 */
      eligible_lots AS (
        SELECT stock.product_id,stock.batch_id,stock.on_hand_quantity,batch_row.expires_on
        FROM inventory.stock_balances stock JOIN inventory.batches batch_row ON batch_row.org_id=stock.org_id AND batch_row.id=stock.batch_id
        JOIN totals ON totals.product_id=stock.product_id WHERE stock.org_id=organization_id AND stock.location_id=from_location_id
          AND stock.on_hand_quantity>0 AND batch_row.lot_kind='manufacturer_batch' AND batch_row.status='released'
          AND batch_row.released_at IS NOT NULL AND batch_row.expires_on IS NOT NULL AND invoice_date<batch_row.expires_on),
      expiry_groups AS (
        SELECT eligible_lot.product_id,eligible_lot.expires_on,
          sum(eligible_lot.on_hand_quantity) expiry_available,
          coalesce(sum(requested.requested_base),0) expiry_requested
        FROM eligible_lots eligible_lot
        LEFT JOIN requested ON requested.product_id=eligible_lot.product_id AND requested.batch_id=eligible_lot.batch_id
        GROUP BY eligible_lot.product_id,eligible_lot.expires_on),
      fefo_eligible AS (
        SELECT expiry_group.product_id,expiry_group.expires_on,
          expiry_group.expiry_available,expiry_group.expiry_requested,
          coalesce(sum(expiry_group.expiry_available) OVER (
            PARTITION BY expiry_group.product_id ORDER BY expiry_group.expires_on
            ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0) prior_available
        FROM expiry_groups expiry_group)
      SELECT count(*) INTO bad_count FROM fefo_eligible JOIN totals USING(product_id)
       WHERE fefo_eligible.expiry_requested IS DISTINCT FROM
         greatest(least(totals.requested_base-fefo_eligible.prior_available,fefo_eligible.expiry_available),0);
      IF bad_count<>0 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='direct invoice batches do not follow FEFO'; END IF;
    END IF;
    RETURN pg_catalog.jsonb_build_object(
      'branch_id',branch.id,'branch_row_version',branch.row_version,'invoice_date',invoice_date,
      'place_of_supply_state_code',place_of_supply,'supply_type',supply_type,'zero_rated_payment_mode',zero_mode,
      'tax_charge_mechanism','normal','customer_account_id',customer.id,'customer_account_row_version',customer.row_version,
      'customer_party_id',customer_party.id,'customer_party_row_version',customer_party.row_version,
      'seller_tax_registration_id',seller_registration.id,'seller_tax_registration_row_version',seller_registration.row_version,
      'customer_tax_registration_id',customer_registration.id,'customer_tax_registration_row_version',customer_registration.row_version,
      'customer_taxpayer_type',customer_registration.taxpayer_type,'billing_address_id',billing.id,'billing_address_row_version',billing.row_version,
      'shipping_address_id',shipping.id,'shipping_address_row_version',shipping.row_version,
      'revenue_account_id',revenue_account.id,'revenue_account_row_version',revenue_account.row_version,
      'from_location_id',location.id,'has_direct_issue',has_direct,'has_dispatch_allocated',has_allocated,
      'seller_legal_name',seller_registration.legal_name,'seller_gstin',seller_registration.gstin,
      'seller_address',pg_catalog.concat_ws(', ',branch.address_line1,branch.address_line2,branch.city,branch.state_code,branch.postal_code),
      'buyer_legal_name',COALESCE(customer_registration.registered_legal_name,customer_party.legal_name),'buyer_gstin',customer_registration.registration_number,
      'buyer_address',pg_catalog.concat_ws(', ',billing.line1,billing.line2,billing.city,billing.state_code,billing.postal_code),
      'origin',CASE WHEN has_direct THEN pg_catalog.jsonb_build_object('line1',branch.address_line1,'line2',branch.address_line2,'city',branch.city,'state_code',branch.state_code,'pincode',branch.postal_code) ELSE NULL END,
      'destination',CASE WHEN has_direct THEN pg_catalog.jsonb_build_object('line1',shipping.line1,'line2',shipping.line2,'city',shipping.city,'state_code',shipping.state_code,'pincode',shipping.postal_code) ELSE NULL END,
      'transport_mode',transport_mode,'distance_km',NULLIF(logistics->>'distance_km','')::numeric::text,
      'transporter_party_id',transporter.id,'transporter_name',transporter.legal_name,'transporter_gstin',transporter_registration.registration_number,
      'vehicle_number',NULLIF(logistics->>'vehicle_number',''),'vehicle_type',NULLIF(logistics->>'vehicle_type',''),
      'transport_document_number',NULLIF(logistics->>'transport_document_number',''),
      'transport_document_date',NULLIF(logistics->>'transport_document_date','')::date,
      'ruleset_version',ruleset_version,'lines',resolved_lines,
      'total_abs_base_quantity',total_base::text,'total_inventory_value',total_value::text,
      'legal_scope',pg_catalog.jsonb_build_object('country','IN','currency','INR','outward_rcm_supported',false,
        'export_supported',false,'sez_without_payment_supported',false,'sez_evidence_registration_id',customer_registration.id),
      'source_versions',source_versions);
END
$function$;

CREATE OR REPLACE FUNCTION "erp_trade_commands_v2"."assert_purchase_order_artifact"(p_org_id uuid, p_resource_id uuid, p_input jsonb, p_output jsonb)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE header procurement.purchase_orders%ROWTYPE;
        expected_lines bigint;
        bad_count bigint;
BEGIN
    SELECT * INTO STRICT header FROM procurement.purchase_orders
     WHERE org_id=p_org_id AND id=p_resource_id FOR UPDATE;
    IF header.status<>'submitted' THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='calculated order is no longer submitted';
    END IF;
    IF header.calculation_ruleset_version IS DISTINCT FROM (
        SELECT erp_automation_reads.tax_ruleset_fingerprint(pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object('tax_code_version_id',tax_version.id,
                                         'ruleset_version',tax_version.ruleset_version)))
          FROM procurement.purchase_order_lines AS line
          JOIN tax.tax_code_versions AS tax_version ON tax_version.id=line.tax_code_version_id
         WHERE line.org_id=p_org_id AND line.purchase_order_id=p_resource_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='document tax-version fingerprint differs from prepared lines';
    END IF;
    IF p_input->>'calculation_kind'<>'document'
       OR p_input->>'operation'<>'procurement.purchase_order.approve'
       OR p_input->>'resource_type'<>'purchase_order'
       OR p_input->>'resource_id'<>p_resource_id::text
       OR (p_input->>'aggregate_version')::bigint IS DISTINCT FROM header.row_version
       OR p_output->>'operation'<>'procurement.purchase_order.approve'
       OR p_output->>'resource_type'<>'purchase_order'
       OR p_output->>'resource_id'<>p_resource_id::text
       OR (p_output->>'aggregate_version')::bigint IS DISTINCT FROM header.row_version
       OR p_output->>'ruleset_version' IS DISTINCT FROM header.calculation_ruleset_version
       OR p_output->>'currency_code' IS DISTINCT FROM header.currency_code
       OR p_input#>>'{document,gst_type}' IS DISTINCT FROM
          (CASE WHEN header.supply_type='intra_state' THEN 'intra_state' ELSE 'inter_state' END)
       OR p_input#>>'{document,zero_rated_mode}' IS DISTINCT FROM header.zero_rated_payment_mode
       OR p_input#>>'{document,tax_charge_mechanism}' IS DISTINCT FROM header.tax_charge_mechanism
       OR p_input#>>'{document,rounding_policy}' IS DISTINCT FROM header.rounding_policy
       OR p_input#>>'{document,document_discount,kind}' IS DISTINCT FROM header.document_discount_kind
       OR (CASE p_input#>>'{document,document_discount,basis}'
            WHEN 'pre_tax_value' THEN 'taxable_value'
            ELSE p_input#>>'{document,document_discount,basis}'
          END) IS DISTINCT FROM header.document_discount_basis
       OR (p_input#>>'{document,document_discount,value}')::numeric IS DISTINCT FROM header.document_discount_value
       OR ROW(
          (p_output#>>'{totals,subtotal}')::numeric,
          (p_output#>>'{totals,discount_total}')::numeric,
          (p_output#>>'{totals,charges_total}')::numeric,
          (p_output#>>'{totals,net_value_total}')::numeric,
          (p_output#>>'{totals,gst_taxable_total}')::numeric,
          (p_output#>>'{totals,cgst_total}')::numeric,
          (p_output#>>'{totals,sgst_total}')::numeric,
          (p_output#>>'{totals,igst_total}')::numeric,
          (p_output#>>'{totals,cess_total}')::numeric,
          (p_output#>>'{totals,recipient_assessed_tax_total}')::numeric,
          (p_output#>>'{totals,rounding_adjustment}')::numeric,
          (p_output#>>'{totals,grand_total}')::numeric,
          (p_output#>>'{totals,pre_round_total}')::numeric
       ) IS DISTINCT FROM ROW(
          header.subtotal,header.discount_total,header.charges_total,
          header.net_value_total,header.gst_taxable_total,header.cgst_total,
          header.sgst_total,header.igst_total,header.cess_total,
          header.recipient_assessed_tax_total,header.rounding_adjustment,
          header.grand_total,header.grand_total-header.rounding_adjustment
       ) THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='calculation artifact header differs from persisted order';
    END IF;

    SELECT count(*) INTO expected_lines FROM procurement.purchase_order_lines
     WHERE org_id=p_org_id AND purchase_order_id=p_resource_id;
    IF expected_lines=0
       OR pg_catalog.jsonb_array_length(p_output->'lines')<>expected_lines
       OR pg_catalog.jsonb_array_length(p_input#>'{document,products}')
          +pg_catalog.jsonb_array_length(p_input#>'{document,charges}')<>expected_lines
       OR (SELECT count(DISTINCT value->>'line_id') FROM pg_catalog.jsonb_array_elements(p_output->'lines'))<>expected_lines
       OR (SELECT count(DISTINCT value->>'line_id')
             FROM (
               SELECT value FROM pg_catalog.jsonb_array_elements(p_input#>'{document,products}')
               UNION ALL
               SELECT value FROM pg_catalog.jsonb_array_elements(p_input#>'{document,charges}')
             ) AS input_items)<>expected_lines THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='calculation artifact line identity or cardinality differs';
    END IF;

    WITH output_lines AS (
        SELECT value AS item FROM pg_catalog.jsonb_array_elements(p_output->'lines')
    ), input_lines AS (
        SELECT value AS item,'product'::text AS line_kind
          FROM pg_catalog.jsonb_array_elements(p_input#>'{document,products}')
        UNION ALL
        SELECT value AS item,'charge'::text AS line_kind
          FROM pg_catalog.jsonb_array_elements(p_input#>'{document,charges}')
    )
    SELECT count(*) INTO bad_count
      FROM procurement.purchase_order_lines AS line
      LEFT JOIN output_lines AS output_line ON output_line.item->>'line_id'=line.id::text
      LEFT JOIN input_lines AS input_line ON input_line.item->>'line_id'=line.id::text
      LEFT JOIN tax.tax_code_versions AS tax_version ON tax_version.id=line.tax_code_version_id
     WHERE line.org_id=p_org_id AND line.purchase_order_id=p_resource_id
       AND (
         output_line.item IS NULL OR input_line.item IS NULL
         OR output_line.item->>'line_kind' IS DISTINCT FROM line.line_kind
         OR (output_line.item->>'final_residual')::boolean
         OR input_line.line_kind IS DISTINCT FROM line.line_kind
         OR input_line.item->>'tax_charge_mechanism' IS DISTINCT FROM line.tax_charge_mechanism
         OR input_line.item->>'price_basis' IS DISTINCT FROM line.price_basis
         OR input_line.item->>'taxability_snapshot' IS DISTINCT FROM line.taxability_snapshot
         OR (input_line.item->>'document_discount_eligible')::boolean IS DISTINCT FROM line.document_discount_eligible
         OR (input_line.item->>'cess_rate')::numeric IS DISTINCT FROM
            CASE WHEN line.taxability_snapshot='taxable' THEN tax_version.cess_rate ELSE 0 END
         OR (input_line.item->>'gst_rate')::numeric IS DISTINCT FROM
            CASE WHEN line.taxability_snapshot='taxable'
                       OR (line.taxability_snapshot='zero_rated' AND header.zero_rated_payment_mode='with_igst')
                 THEN tax_version.igst_rate ELSE 0 END
         OR tax_version.id IS NULL
         OR tax_version.code IS DISTINCT FROM line.tax_classification_code_snapshot
         OR tax_version.code_kind IS DISTINCT FROM CASE WHEN line.line_kind='product' THEN 'hsn' ELSE 'sac' END
         OR (tax_version.org_id IS NOT NULL AND (
              tax_version.org_id IS DISTINCT FROM p_org_id
              OR line.line_kind<>'product'
              OR tax_version.product_id IS DISTINCT FROM line.product_id
              OR NOT EXISTS (
                  SELECT 1 FROM erp_automation_reads.resolve_product_tax(p_org_id,line.product_id,header.order_date) AS scoped_tax
                   WHERE scoped_tax.id=tax_version.id)))
         OR header.order_date<tax_version.effective_from
         OR (tax_version.effective_to IS NOT NULL AND header.order_date>tax_version.effective_to)
         OR NOT (line.taxability_snapshot=tax_version.taxability
                 OR (line.taxability_snapshot='zero_rated' AND header.supply_type IN ('export','sez')))
         OR (line.line_kind='product' AND (
              (input_line.item->>'base_billed_quantity')::numeric IS DISTINCT FROM line.base_billed_quantity
              OR (input_line.item->>'base_free_quantity')::numeric IS DISTINCT FROM line.base_free_quantity
              OR (input_line.item->>'billed_quantity')::numeric IS DISTINCT FROM line.billed_quantity
              OR (input_line.item->>'free_quantity')::numeric IS DISTINCT FROM line.free_quantity
              OR (input_line.item->>'uom_conversion_factor')::numeric IS DISTINCT FROM line.uom_conversion_factor
              OR (input_line.item->>'quoted_unit_rate')::numeric IS DISTINCT FROM line.quoted_unit_rate
              OR input_line.item->>'free_supply_tax_treatment' IS DISTINCT FROM line.free_supply_tax_treatment
              OR input_line.item#>>'{line_discount,kind}' IS DISTINCT FROM line.line_discount_kind
              OR CASE input_line.item#>>'{line_discount,basis}'
                   WHEN 'pre_tax_value' THEN 'taxable_value'
                   ELSE input_line.item#>>'{line_discount,basis}'
                 END IS DISTINCT FROM line.line_discount_basis
              OR (input_line.item#>>'{line_discount,value}')::numeric IS DISTINCT FROM line.line_discount_value
         ))
         OR (line.line_kind='charge' AND (
              input_line.item->>'charge_code' IS DISTINCT FROM line.charge_code
              OR (input_line.item->>'quoted_amount')::numeric IS DISTINCT FROM line.gross_amount
         ))
         OR ROW(
            (output_line.item->>'gross_amount')::numeric,
            (output_line.item->>'line_discount_amount')::numeric,
            (output_line.item->>'line_taxable_discount_amount')::numeric,
            (output_line.item->>'document_discount_amount')::numeric,
            (output_line.item->>'document_taxable_discount_amount')::numeric,
            (output_line.item->>'net_value_amount')::numeric,
            (output_line.item->>'gst_taxable_value')::numeric,
            (output_line.item->>'cgst_rate')::numeric,
            (output_line.item->>'sgst_rate')::numeric,
            (output_line.item->>'igst_rate')::numeric,
            (output_line.item->>'cess_rate')::numeric,
            (output_line.item->>'cgst_amount')::numeric,
            (output_line.item->>'sgst_amount')::numeric,
            (output_line.item->>'igst_amount')::numeric,
            (output_line.item->>'cess_amount')::numeric,
            (output_line.item->>'line_total')::numeric,
            (output_line.item->>'recipient_assessed_tax_amount')::numeric
         ) IS DISTINCT FROM ROW(
            line.gross_amount,line.line_discount_amount,line.line_taxable_discount_amount,
            line.document_discount_amount,line.document_taxable_discount_amount,
            line.net_value_amount,line.gst_taxable_value,line.cgst_rate,line.sgst_rate,
            line.igst_rate,line.cess_rate,line.cgst_amount,line.sgst_amount,
            line.igst_amount,line.cess_amount,line.line_total,
            CASE WHEN line.tax_charge_mechanism='reverse_charge'
                 THEN line.cgst_amount+line.sgst_amount+line.igst_amount+line.cess_amount ELSE 0 END
         )
       );
    IF bad_count<>0 THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='calculation artifact input, tax version, or line output differs';
    END IF;
END
$function$;

CREATE OR REPLACE FUNCTION "erp_trade_commands_v2"."assert_sales_order_artifact"(p_org_id uuid, p_resource_id uuid, p_input jsonb, p_output jsonb)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE header sales.orders%ROWTYPE;
        expected_lines bigint;
        bad_count bigint;
BEGIN
    SELECT * INTO STRICT header FROM sales.orders
     WHERE org_id=p_org_id AND id=p_resource_id FOR UPDATE;
    IF header.status<>'submitted' THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='calculated order is no longer submitted';
    END IF;
    IF header.calculation_ruleset_version IS DISTINCT FROM (
        SELECT erp_automation_reads.tax_ruleset_fingerprint(pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object('tax_code_version_id',tax_version.id,
                                         'ruleset_version',tax_version.ruleset_version)))
          FROM sales.order_lines AS line
          JOIN tax.tax_code_versions AS tax_version ON tax_version.id=line.tax_code_version_id
         WHERE line.org_id=p_org_id AND line.order_id=p_resource_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='document tax-version fingerprint differs from prepared lines';
    END IF;
    IF p_input->>'calculation_kind'<>'document'
       OR p_input->>'operation'<>'sales.order.approve'
       OR p_input->>'resource_type'<>'sales_order'
       OR p_input->>'resource_id'<>p_resource_id::text
       OR (p_input->>'aggregate_version')::bigint IS DISTINCT FROM header.row_version
       OR p_output->>'operation'<>'sales.order.approve'
       OR p_output->>'resource_type'<>'sales_order'
       OR p_output->>'resource_id'<>p_resource_id::text
       OR (p_output->>'aggregate_version')::bigint IS DISTINCT FROM header.row_version
       OR p_output->>'ruleset_version' IS DISTINCT FROM header.calculation_ruleset_version
       OR p_output->>'currency_code' IS DISTINCT FROM header.currency_code
       OR p_input#>>'{document,gst_type}' IS DISTINCT FROM
          (CASE WHEN header.supply_type='intra_state' THEN 'intra_state' ELSE 'inter_state' END)
       OR p_input#>>'{document,zero_rated_mode}' IS DISTINCT FROM header.zero_rated_payment_mode
       OR p_input#>>'{document,tax_charge_mechanism}' IS DISTINCT FROM header.tax_charge_mechanism
       OR p_input#>>'{document,rounding_policy}' IS DISTINCT FROM header.rounding_policy
       OR p_input#>>'{document,document_discount,kind}' IS DISTINCT FROM header.document_discount_kind
       OR (CASE p_input#>>'{document,document_discount,basis}'
            WHEN 'pre_tax_value' THEN 'taxable_value'
            ELSE p_input#>>'{document,document_discount,basis}'
          END) IS DISTINCT FROM header.document_discount_basis
       OR (p_input#>>'{document,document_discount,value}')::numeric IS DISTINCT FROM header.document_discount_value
       OR ROW(
          (p_output#>>'{totals,subtotal}')::numeric,
          (p_output#>>'{totals,discount_total}')::numeric,
          (p_output#>>'{totals,charges_total}')::numeric,
          (p_output#>>'{totals,net_value_total}')::numeric,
          (p_output#>>'{totals,gst_taxable_total}')::numeric,
          (p_output#>>'{totals,cgst_total}')::numeric,
          (p_output#>>'{totals,sgst_total}')::numeric,
          (p_output#>>'{totals,igst_total}')::numeric,
          (p_output#>>'{totals,cess_total}')::numeric,
          (p_output#>>'{totals,recipient_assessed_tax_total}')::numeric,
          (p_output#>>'{totals,rounding_adjustment}')::numeric,
          (p_output#>>'{totals,grand_total}')::numeric,
          (p_output#>>'{totals,pre_round_total}')::numeric
       ) IS DISTINCT FROM ROW(
          header.subtotal,header.discount_total,header.charges_total,
          header.net_value_total,header.gst_taxable_total,header.cgst_total,
          header.sgst_total,header.igst_total,header.cess_total,
          header.recipient_assessed_tax_total,header.rounding_adjustment,
          header.grand_total,header.grand_total-header.rounding_adjustment
       ) THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='calculation artifact header differs from persisted order';
    END IF;

    SELECT count(*) INTO expected_lines FROM sales.order_lines
     WHERE org_id=p_org_id AND order_id=p_resource_id;
    IF expected_lines=0
       OR pg_catalog.jsonb_array_length(p_output->'lines')<>expected_lines
       OR pg_catalog.jsonb_array_length(p_input#>'{document,products}')
          +pg_catalog.jsonb_array_length(p_input#>'{document,charges}')<>expected_lines
       OR (SELECT count(DISTINCT value->>'line_id') FROM pg_catalog.jsonb_array_elements(p_output->'lines'))<>expected_lines
       OR (SELECT count(DISTINCT value->>'line_id')
             FROM (
               SELECT value FROM pg_catalog.jsonb_array_elements(p_input#>'{document,products}')
               UNION ALL
               SELECT value FROM pg_catalog.jsonb_array_elements(p_input#>'{document,charges}')
             ) AS input_items)<>expected_lines THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='calculation artifact line identity or cardinality differs';
    END IF;

    WITH output_lines AS (
        SELECT value AS item FROM pg_catalog.jsonb_array_elements(p_output->'lines')
    ), input_lines AS (
        SELECT value AS item,'product'::text AS line_kind
          FROM pg_catalog.jsonb_array_elements(p_input#>'{document,products}')
        UNION ALL
        SELECT value AS item,'charge'::text AS line_kind
          FROM pg_catalog.jsonb_array_elements(p_input#>'{document,charges}')
    )
    SELECT count(*) INTO bad_count
      FROM sales.order_lines AS line
      LEFT JOIN output_lines AS output_line ON output_line.item->>'line_id'=line.id::text
      LEFT JOIN input_lines AS input_line ON input_line.item->>'line_id'=line.id::text
      LEFT JOIN tax.tax_code_versions AS tax_version ON tax_version.id=line.tax_code_version_id
     WHERE line.org_id=p_org_id AND line.order_id=p_resource_id
       AND (
         output_line.item IS NULL OR input_line.item IS NULL
         OR output_line.item->>'line_kind' IS DISTINCT FROM line.line_kind
         OR (output_line.item->>'final_residual')::boolean
         OR input_line.line_kind IS DISTINCT FROM line.line_kind
         OR input_line.item->>'tax_charge_mechanism' IS DISTINCT FROM line.tax_charge_mechanism
         OR input_line.item->>'price_basis' IS DISTINCT FROM line.price_basis
         OR input_line.item->>'taxability_snapshot' IS DISTINCT FROM line.taxability_snapshot
         OR (input_line.item->>'document_discount_eligible')::boolean IS DISTINCT FROM line.document_discount_eligible
         OR (input_line.item->>'cess_rate')::numeric IS DISTINCT FROM
            CASE WHEN line.taxability_snapshot='taxable' THEN tax_version.cess_rate ELSE 0 END
         OR (input_line.item->>'gst_rate')::numeric IS DISTINCT FROM
            CASE WHEN line.taxability_snapshot='taxable'
                       OR (line.taxability_snapshot='zero_rated' AND header.zero_rated_payment_mode='with_igst')
                 THEN tax_version.igst_rate ELSE 0 END
         OR tax_version.id IS NULL
         OR tax_version.code IS DISTINCT FROM line.tax_classification_code_snapshot
         OR tax_version.code_kind IS DISTINCT FROM CASE WHEN line.line_kind='product' THEN 'hsn' ELSE 'sac' END
         OR (tax_version.org_id IS NOT NULL AND (
              tax_version.org_id IS DISTINCT FROM p_org_id
              OR line.line_kind<>'product'
              OR tax_version.product_id IS DISTINCT FROM line.product_id
              OR NOT EXISTS (
                  SELECT 1 FROM erp_automation_reads.resolve_product_tax(p_org_id,line.product_id,header.order_date) AS scoped_tax
                   WHERE scoped_tax.id=tax_version.id)))
         OR header.order_date<tax_version.effective_from
         OR (tax_version.effective_to IS NOT NULL AND header.order_date>tax_version.effective_to)
         OR NOT (line.taxability_snapshot=tax_version.taxability
                 OR (line.taxability_snapshot='zero_rated' AND header.supply_type IN ('export','sez')))
         OR (line.line_kind='product' AND (
              (input_line.item->>'base_billed_quantity')::numeric IS DISTINCT FROM line.base_billed_quantity
              OR (input_line.item->>'base_free_quantity')::numeric IS DISTINCT FROM line.base_free_quantity
              OR (input_line.item->>'billed_quantity')::numeric IS DISTINCT FROM line.billed_quantity
              OR (input_line.item->>'free_quantity')::numeric IS DISTINCT FROM line.free_quantity
              OR (input_line.item->>'uom_conversion_factor')::numeric IS DISTINCT FROM line.uom_conversion_factor
              OR (input_line.item->>'quoted_unit_rate')::numeric IS DISTINCT FROM line.quoted_unit_rate
              OR input_line.item->>'free_supply_tax_treatment' IS DISTINCT FROM line.free_supply_tax_treatment
              OR input_line.item#>>'{line_discount,kind}' IS DISTINCT FROM line.line_discount_kind
              OR CASE input_line.item#>>'{line_discount,basis}'
                   WHEN 'pre_tax_value' THEN 'taxable_value'
                   ELSE input_line.item#>>'{line_discount,basis}'
                 END IS DISTINCT FROM line.line_discount_basis
              OR (input_line.item#>>'{line_discount,value}')::numeric IS DISTINCT FROM line.line_discount_value
         ))
         OR (line.line_kind='charge' AND (
              input_line.item->>'charge_code' IS DISTINCT FROM line.charge_code
              OR (input_line.item->>'quoted_amount')::numeric IS DISTINCT FROM line.gross_amount
         ))
         OR ROW(
            (output_line.item->>'gross_amount')::numeric,
            (output_line.item->>'line_discount_amount')::numeric,
            (output_line.item->>'line_taxable_discount_amount')::numeric,
            (output_line.item->>'document_discount_amount')::numeric,
            (output_line.item->>'document_taxable_discount_amount')::numeric,
            (output_line.item->>'net_value_amount')::numeric,
            (output_line.item->>'gst_taxable_value')::numeric,
            (output_line.item->>'cgst_rate')::numeric,
            (output_line.item->>'sgst_rate')::numeric,
            (output_line.item->>'igst_rate')::numeric,
            (output_line.item->>'cess_rate')::numeric,
            (output_line.item->>'cgst_amount')::numeric,
            (output_line.item->>'sgst_amount')::numeric,
            (output_line.item->>'igst_amount')::numeric,
            (output_line.item->>'cess_amount')::numeric,
            (output_line.item->>'line_total')::numeric,
            (output_line.item->>'recipient_assessed_tax_amount')::numeric
         ) IS DISTINCT FROM ROW(
            line.gross_amount,line.line_discount_amount,line.line_taxable_discount_amount,
            line.document_discount_amount,line.document_taxable_discount_amount,
            line.net_value_amount,line.gst_taxable_value,line.cgst_rate,line.sgst_rate,
            line.igst_rate,line.cess_rate,line.cgst_amount,line.sgst_amount,
            line.igst_amount,line.cess_amount,line.line_total,
            CASE WHEN line.tax_charge_mechanism='reverse_charge'
                 THEN line.cgst_amount+line.sgst_amount+line.igst_amount+line.cess_amount ELSE 0 END
         )
       );
    IF bad_count<>0 THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='calculation artifact input, tax version, or line output differs';
    END IF;
END
$function$;

CREATE OR REPLACE FUNCTION "erp_commercial_commands"."assert_purchase_return_artifact"(organization_id uuid, resource_id uuid, input_doc jsonb, output_doc jsonb)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
DECLARE header procurement.purchase_returns%ROWTYPE; original procurement.supplier_invoices%ROWTYPE;
        expected_lines bigint; bad_count bigint; cumulative_grand numeric(20,2); cumulative_rounding numeric(20,2);
BEGIN
    SELECT * INTO STRICT header FROM procurement.purchase_returns WHERE org_id=organization_id AND id=resource_id FOR UPDATE;
    IF header.status NOT IN ('draft','submitted','approved','posted') THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='return is not postable or posted'; END IF;
    IF header.return_source_kind='invoiced' THEN
      SELECT * INTO STRICT original FROM procurement.supplier_invoices WHERE org_id=organization_id AND id=header.supplier_invoice_id FOR UPDATE;
    END IF;
    IF header.return_source_kind='invoiced' THEN PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(organization_id::text||original.id::text,734821)); END IF;
    IF header.return_source_kind='invoiced' AND original.calculation_ruleset_version IS DISTINCT FROM (
      SELECT erp_automation_reads.tax_ruleset_fingerprint(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
               'tax_code_version_id',version.id,'ruleset_version',version.ruleset_version)))
        FROM procurement.supplier_invoice_lines original_line
        JOIN tax.tax_code_versions version ON version.id=original_line.tax_code_version_id
       WHERE original_line.org_id=organization_id
         AND original_line.supplier_invoice_id=original.id
    ) THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='return original invoice tax fingerprint differs';
    END IF;
    PERFORM erp_calculation_authority.assert_input_schema(input_doc);
    PERFORM erp_calculation_authority.assert_output_schema(output_doc);
    IF input_doc->>'calculation_kind'<>'reversal' OR input_doc->>'operation'<>'procurement.purchase_return.post'
       OR input_doc#>>'{reversal,gst_tax_treatment}' IS DISTINCT FROM header.gst_tax_treatment
       OR output_doc->>'gst_tax_treatment' IS DISTINCT FROM header.gst_tax_treatment
       OR input_doc->>'resource_type'<>'purchase_return' OR input_doc->>'resource_id'<>resource_id::text
       OR (input_doc->>'aggregate_version')::bigint IS DISTINCT FROM
          (CASE WHEN header.status='posted' THEN header.row_version-1 ELSE header.row_version END)
       OR output_doc->>'operation'<>'procurement.purchase_return.post' OR output_doc->>'resource_type'<>'purchase_return'
       OR output_doc->>'resource_id'<>resource_id::text
       OR (output_doc->>'aggregate_version')::bigint IS DISTINCT FROM
          (CASE WHEN header.status='posted' THEN header.row_version-1 ELSE header.row_version END)
       OR output_doc->>'ruleset_version' IS DISTINCT FROM header.calculation_ruleset_version
       OR ROW((output_doc#>>'{totals,net_value_total}')::numeric,(output_doc#>>'{totals,gst_taxable_total}')::numeric,
              (output_doc#>>'{totals,cgst_total}')::numeric,(output_doc#>>'{totals,sgst_total}')::numeric,
              (output_doc#>>'{totals,igst_total}')::numeric,(output_doc#>>'{totals,cess_total}')::numeric,
              (output_doc#>>'{totals,recipient_assessed_tax_total}')::numeric,(output_doc#>>'{totals,rounding_adjustment}')::numeric,
              (output_doc#>>'{totals,grand_total}')::numeric)
          IS DISTINCT FROM ROW(header.net_value_total,header.gst_taxable_total,header.cgst_total,header.sgst_total,
              header.igst_total,header.cess_total,header.recipient_assessed_tax_total,header.rounding_adjustment,header.grand_total)
       OR (header.return_source_kind='invoiced' AND (header.supplier_account_id IS DISTINCT FROM original.supplier_account_id OR
           header.zero_rated_payment_mode IS DISTINCT FROM original.zero_rated_payment_mode
           OR header.tax_charge_mechanism IS DISTINCT FROM original.tax_charge_mechanism
           OR header.rounding_policy IS DISTINCT FROM original.rounding_policy
           OR header.calculation_ruleset_version IS DISTINCT FROM original.calculation_ruleset_version
           OR input_doc#>>'{original,resource_id}' IS DISTINCT FROM original.id::text
           OR ROW((input_doc#>>'{original,totals,net_value_total}')::numeric,(input_doc#>>'{original,totals,gst_taxable_total}')::numeric,
                  (input_doc#>>'{original,totals,cgst_total}')::numeric,(input_doc#>>'{original,totals,sgst_total}')::numeric,
                  (input_doc#>>'{original,totals,igst_total}')::numeric,(input_doc#>>'{original,totals,cess_total}')::numeric,
                  (input_doc#>>'{original,totals,rounding_adjustment}')::numeric,(input_doc#>>'{original,totals,grand_total}')::numeric)
              IS DISTINCT FROM ROW(original.net_value_total,original.gst_taxable_total,original.cgst_total,original.sgst_total,
                  original.igst_total,original.cess_total,original.rounding_adjustment,original.grand_total))) THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='return artifact header or original snapshot differs';
    END IF;
    SELECT count(*) INTO expected_lines FROM procurement.purchase_return_lines WHERE org_id=organization_id AND purchase_return_id=resource_id;
    IF expected_lines=0 OR pg_catalog.jsonb_array_length(input_doc#>'{reversal,products}')<>expected_lines
       OR pg_catalog.jsonb_array_length(input_doc#>'{reversal,charges}')<>0
       OR pg_catalog.jsonb_array_length(output_doc->'lines')<>expected_lines THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='return artifact line cardinality differs';
    END IF;
    WITH reversal_input AS (SELECT value item FROM pg_catalog.jsonb_array_elements(input_doc#>'{reversal,products}')),
         reversal_output AS (SELECT value item FROM pg_catalog.jsonb_array_elements(output_doc->'lines')),
         original_output AS (SELECT value item FROM pg_catalog.jsonb_array_elements(input_doc#>'{original,lines}'))
    SELECT count(*) INTO bad_count
      FROM procurement.purchase_return_lines line
      LEFT JOIN procurement.supplier_invoice_receipt_allocations allocation ON allocation.org_id=line.org_id AND allocation.id=line.supplier_invoice_receipt_allocation_id LEFT JOIN procurement.goods_receipt_lines receipt ON receipt.org_id=line.org_id AND receipt.id=line.goods_receipt_line_id LEFT JOIN inventory.locations return_location ON return_location.org_id=line.org_id AND return_location.id=line.from_location_id
      LEFT JOIN procurement.supplier_invoice_lines source ON source.org_id=line.org_id AND allocation.id=line.supplier_invoice_receipt_allocation_id AND source.id=allocation.supplier_invoice_line_id AND source.supplier_invoice_id=header.supplier_invoice_id
      LEFT JOIN tax.tax_code_versions tax_version ON tax_version.id=line.tax_code_version_id
      LEFT JOIN reversal_input requested ON requested.item->>'line_id'=(source.id)::text
      LEFT JOIN reversal_output calculated ON calculated.item->>'line_id'=(source.id)::text
      LEFT JOIN original_output original_line ON original_line.item->>'line_id'=(source.id)::text
     WHERE line.org_id=organization_id AND line.purchase_return_id=resource_id
       AND (header.return_source_kind='invoiced') AND (requested.item IS NULL OR calculated.item IS NULL OR original_line.item IS NULL
         OR line.gst_tax_treatment IS DISTINCT FROM header.gst_tax_treatment
         OR requested.item->>'value_basis' IS DISTINCT FROM line.reversal_value_basis
         OR (requested.item->>'final_residual')::boolean IS DISTINCT FROM line.final_residual
         OR (requested.item->>'reversed_billed_quantity')::numeric IS DISTINCT FROM line.billed_quantity
         OR (requested.item->>'reversed_free_quantity')::numeric IS DISTINCT FROM line.free_quantity
         OR (requested.item->>'reversed_base_billed_quantity')::numeric IS DISTINCT FROM line.base_billed_quantity
         OR (requested.item->>'reversed_base_free_quantity')::numeric IS DISTINCT FROM line.base_free_quantity
         OR ROW((calculated.item->>'net_value_amount')::numeric,(calculated.item->>'gst_taxable_value')::numeric,
                (calculated.item->>'cgst_rate')::numeric,(calculated.item->>'sgst_rate')::numeric,
                (calculated.item->>'igst_rate')::numeric,(calculated.item->>'cess_rate')::numeric,
                (calculated.item->>'cgst_amount')::numeric,(calculated.item->>'sgst_amount')::numeric,
                (calculated.item->>'igst_amount')::numeric,(calculated.item->>'cess_amount')::numeric,
                (calculated.item->>'line_total')::numeric,(calculated.item->>'final_residual')::boolean)
           IS DISTINCT FROM ROW(line.net_value_amount,line.gst_taxable_value,line.cgst_rate,line.sgst_rate,line.igst_rate,
                line.cess_rate,line.cgst_amount,line.sgst_amount,line.igst_amount,line.cess_amount,line.line_total,line.final_residual)
         OR ROW((original_line.item->>'net_value_amount')::numeric,(original_line.item->>'gst_taxable_value')::numeric,
                (original_line.item->>'cgst_rate')::numeric,(original_line.item->>'sgst_rate')::numeric,
                (original_line.item->>'igst_rate')::numeric,(original_line.item->>'cess_rate')::numeric,
                (original_line.item->>'cgst_amount')::numeric,(original_line.item->>'sgst_amount')::numeric,
                (original_line.item->>'igst_amount')::numeric,(original_line.item->>'cess_amount')::numeric,
                (original_line.item->>'line_total')::numeric)
           IS DISTINCT FROM ROW(source.net_value_amount,source.gst_taxable_value,source.cgst_rate,source.sgst_rate,source.igst_rate,
                source.cess_rate,source.cgst_amount,source.sgst_amount,source.igst_amount,source.cess_amount,source.line_total)
         
         OR source.id IS NULL
         OR source.product_id IS DISTINCT FROM line.product_id
         OR source.uom_conversion_factor IS DISTINCT FROM line.uom_conversion_factor
         OR source.quoted_unit_rate IS DISTINCT FROM line.quoted_unit_rate
         OR source.price_basis IS DISTINCT FROM line.price_basis
         OR source.free_supply_tax_treatment IS DISTINCT FROM line.free_supply_tax_treatment
         OR source.tax_classification_code_snapshot IS DISTINCT FROM line.hsn_code_snapshot
         OR source.tax_charge_mechanism IS DISTINCT FROM line.tax_charge_mechanism
         OR source.tax_code_version_id IS DISTINCT FROM line.tax_code_version_id
         OR source.taxability_snapshot IS DISTINCT FROM line.taxability_snapshot
         OR tax_version.id IS NULL
         OR (tax_version.org_id IS NOT NULL AND (
              tax_version.org_id IS DISTINCT FROM organization_id
              OR tax_version.product_id IS DISTINCT FROM line.product_id))
         OR original.supplier_invoice_date<tax_version.effective_from
         OR (tax_version.effective_to IS NOT NULL AND original.supplier_invoice_date>tax_version.effective_to)
         
         OR allocation.goods_receipt_line_id IS DISTINCT FROM line.goods_receipt_line_id
         OR receipt.id IS NULL OR return_location.id IS NULL
         OR return_location.branch_id IS DISTINCT FROM header.branch_id OR return_location.status<>'active'
         OR ROW(receipt.product_id,receipt.batch_id,receipt.location_id)
            IS DISTINCT FROM ROW(line.product_id,line.batch_id,line.from_location_id)
         OR line.base_billed_quantity>allocation.allocated_base_billed_quantity OR line.base_free_quantity>allocation.allocated_base_free_quantity);
    IF bad_count<>0 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='return artifact line differs from locked original'; END IF;
    
    IF header.return_source_kind='uninvoiced' THEN
      WITH reversal_input AS (SELECT value item FROM pg_catalog.jsonb_array_elements(input_doc#>'{reversal,products}')),
           reversal_output AS (SELECT value item FROM pg_catalog.jsonb_array_elements(output_doc->'lines')),
           original_output AS (SELECT value item FROM pg_catalog.jsonb_array_elements(input_doc#>'{original,lines}'))
      SELECT count(*) INTO bad_count
        FROM procurement.purchase_return_lines line
        JOIN procurement.goods_receipt_lines receipt
          ON receipt.org_id=line.org_id AND receipt.id=line.goods_receipt_line_id
        JOIN procurement.goods_receipts receipt_header
          ON receipt_header.org_id=receipt.org_id AND receipt_header.id=receipt.goods_receipt_id
        JOIN inventory.locations receipt_location
          ON receipt_location.org_id=receipt.org_id AND receipt_location.id=receipt.location_id
        LEFT JOIN procurement.supplier_invoice_receipt_allocations forbidden
          ON forbidden.org_id=line.org_id AND forbidden.id=line.supplier_invoice_receipt_allocation_id
        LEFT JOIN reversal_input requested ON requested.item->>'line_id'=line.goods_receipt_line_id::text
        LEFT JOIN reversal_output calculated ON calculated.item->>'line_id'=line.goods_receipt_line_id::text
        LEFT JOIN original_output original_line ON original_line.item->>'line_id'=line.goods_receipt_line_id::text
       WHERE line.org_id=organization_id AND line.purchase_return_id=resource_id
         AND (line.gst_tax_treatment IS DISTINCT FROM header.gst_tax_treatment
           OR forbidden.id IS NOT NULL OR requested.item IS NULL OR calculated.item IS NULL OR original_line.item IS NULL
           OR receipt_header.status<>'posted' OR receipt_header.branch_id IS DISTINCT FROM header.branch_id
           OR receipt_header.supplier_account_id IS DISTINCT FROM header.supplier_account_id
           OR receipt_location.status<>'active' OR receipt_location.branch_id IS DISTINCT FROM header.branch_id
           OR requested.item->>'value_basis' IS DISTINCT FROM line.reversal_value_basis
           OR (requested.item->>'final_residual')::boolean IS DISTINCT FROM line.final_residual
           OR (requested.item->>'reversed_billed_quantity')::numeric IS DISTINCT FROM line.billed_quantity
           OR (requested.item->>'reversed_free_quantity')::numeric IS DISTINCT FROM line.free_quantity
           OR (requested.item->>'reversed_base_billed_quantity')::numeric IS DISTINCT FROM line.base_billed_quantity
           OR (requested.item->>'reversed_base_free_quantity')::numeric IS DISTINCT FROM line.base_free_quantity
           OR ROW((calculated.item->>'net_value_amount')::numeric,(calculated.item->>'gst_taxable_value')::numeric,
                  (calculated.item->>'cgst_amount')::numeric,(calculated.item->>'sgst_amount')::numeric,
                  (calculated.item->>'igst_amount')::numeric,(calculated.item->>'cess_amount')::numeric,
                  (calculated.item->>'line_total')::numeric,(calculated.item->>'final_residual')::boolean)
              IS DISTINCT FROM ROW(line.net_value_amount,line.gst_taxable_value,line.cgst_amount,line.sgst_amount,line.igst_amount,line.cess_amount,line.line_total,line.final_residual)
           OR (original_line.item->>'net_value_amount')::numeric IS DISTINCT FROM receipt.extended_cost
           OR (original_line.item->>'gst_taxable_value')::numeric<>0 OR (original_line.item->>'cgst_amount')::numeric<>0
           OR (original_line.item->>'sgst_amount')::numeric<>0 OR (original_line.item->>'igst_amount')::numeric<>0
           OR (original_line.item->>'cess_amount')::numeric<>0 OR (original_line.item->>'line_total')::numeric IS DISTINCT FROM receipt.extended_cost
           OR line.product_id IS DISTINCT FROM receipt.product_id
           OR line.batch_id IS DISTINCT FROM receipt.batch_id OR line.from_location_id IS DISTINCT FROM receipt.location_id
           OR line.quoted_unit_rate IS DISTINCT FROM receipt.unit_cost
           OR (receipt.accepted_quantity>0 AND pg_catalog.round(receipt.accepted_quantity*line.uom_conversion_factor,6) IS DISTINCT FROM receipt.base_accepted_quantity)
           OR (receipt.free_quantity>0 AND pg_catalog.round(receipt.free_quantity*line.uom_conversion_factor,6) IS DISTINCT FROM receipt.base_free_quantity)
           OR line.gst_taxable_value<>0 OR line.cgst_amount<>0 OR line.sgst_amount<>0 OR line.igst_amount<>0 OR line.cess_amount<>0
           OR line.net_value_amount<>pg_catalog.round((line.base_billed_quantity+line.base_free_quantity)*receipt.unit_cost,2)
           OR line.line_total<>line.net_value_amount);
      IF bad_count<>0 OR header.gst_taxable_total<>0 OR header.cgst_total<>0 OR header.sgst_total<>0
         OR header.igst_total<>0 OR header.cess_total<>0 OR header.recipient_assessed_tax_total<>0
         OR header.rounding_adjustment<>0 OR header.grand_total<>header.net_value_total THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='uninvoiced purchase return differs from locked goods-receipt cost or carries GST';
      END IF;
    END IF;
    IF header.return_source_kind='invoiced' THEN
          SELECT count(*) INTO bad_count FROM (
            SELECT source.id source_id,max(source.base_billed_quantity) source_billed,max(source.base_free_quantity) source_free,
                   sum(all_returns.base_billed_quantity) reversed_billed,sum(all_returns.base_free_quantity) reversed_free,bool_or(current.final_residual) final_residual
                   ,sum(all_returns.net_value_amount) reversed_net,sum(all_returns.gst_taxable_value) reversed_taxable,
                   sum(all_returns.cgst_amount) reversed_cgst,sum(all_returns.sgst_amount) reversed_sgst,sum(all_returns.igst_amount) reversed_igst,sum(all_returns.cess_amount) reversed_cess,sum(all_returns.line_total) reversed_total,
                   max(source.net_value_amount) source_net,max(source.gst_taxable_value) source_taxable,max(source.cgst_amount) source_cgst,max(source.sgst_amount) source_sgst,max(source.igst_amount) source_igst,max(source.cess_amount) source_cess,max(source.line_total) source_total
              FROM procurement.purchase_return_lines current
              JOIN procurement.supplier_invoice_receipt_allocations allocation ON allocation.org_id=current.org_id AND allocation.id=current.supplier_invoice_receipt_allocation_id
              JOIN procurement.supplier_invoice_lines source ON source.org_id=allocation.org_id AND source.id=allocation.supplier_invoice_line_id
              JOIN procurement.supplier_invoice_receipt_allocations all_source_allocations ON all_source_allocations.org_id=source.org_id AND all_source_allocations.supplier_invoice_line_id=source.id
              JOIN procurement.purchase_return_lines all_returns ON all_returns.org_id=all_source_allocations.org_id AND all_returns.supplier_invoice_receipt_allocation_id=all_source_allocations.id
              JOIN procurement.purchase_returns prior_header ON prior_header.org_id=all_returns.org_id AND prior_header.id=all_returns.purchase_return_id
             WHERE current.org_id=organization_id AND current.purchase_return_id=resource_id AND (prior_header.status='posted' OR prior_header.id=resource_id)
             GROUP BY source.id
          ) cumulative WHERE reversed_billed>source_billed OR reversed_free>source_free
             OR reversed_taxable>source_taxable OR reversed_cgst>source_cgst OR reversed_sgst>source_sgst OR reversed_igst>source_igst OR reversed_cess>source_cess OR reversed_total>source_total
             OR (final_residual AND (reversed_billed<>source_billed OR reversed_free<>source_free OR reversed_total<>source_total));
          IF bad_count=0 THEN
            SELECT count(*) INTO bad_count FROM (
              SELECT current.supplier_invoice_receipt_allocation_id allocation_id,
                     max(allocation.allocated_base_billed_quantity) source_billed,max(allocation.allocated_base_free_quantity) source_free,
                     sum(all_returns.base_billed_quantity) reversed_billed,sum(all_returns.base_free_quantity) reversed_free
                FROM procurement.purchase_return_lines current
                JOIN procurement.supplier_invoice_receipt_allocations allocation ON allocation.org_id=current.org_id AND allocation.id=current.supplier_invoice_receipt_allocation_id
                JOIN procurement.purchase_return_lines all_returns ON all_returns.org_id=allocation.org_id AND all_returns.supplier_invoice_receipt_allocation_id=allocation.id
                JOIN procurement.purchase_returns prior_header ON prior_header.org_id=all_returns.org_id AND prior_header.id=all_returns.purchase_return_id
               WHERE current.org_id=organization_id AND current.purchase_return_id=resource_id AND (prior_header.status='posted' OR prior_header.id=resource_id)
               GROUP BY current.supplier_invoice_receipt_allocation_id
            ) allocation_total WHERE reversed_billed>source_billed OR reversed_free>source_free;
          END IF;
        ELSE
          SELECT count(*) INTO bad_count FROM (
            SELECT current.goods_receipt_line_id source_id,max(receipt.base_accepted_quantity) source_billed,max(receipt.base_free_quantity) source_free,
                   sum(all_returns.base_billed_quantity) reversed_billed,sum(all_returns.base_free_quantity) reversed_free,bool_or(current.final_residual) final_residual,
                   max(receipt.extended_cost) source_net,sum(all_returns.net_value_amount) reversed_net
              FROM procurement.purchase_return_lines current
              JOIN procurement.goods_receipt_lines receipt ON receipt.org_id=current.org_id AND receipt.id=current.goods_receipt_line_id
              JOIN procurement.purchase_return_lines all_returns ON all_returns.org_id=current.org_id AND all_returns.goods_receipt_line_id=current.goods_receipt_line_id
              JOIN procurement.purchase_returns prior_header ON prior_header.org_id=all_returns.org_id AND prior_header.id=all_returns.purchase_return_id
             WHERE current.org_id=organization_id AND current.purchase_return_id=resource_id AND (prior_header.status='posted' OR prior_header.id=resource_id)
             GROUP BY current.goods_receipt_line_id
          ) cumulative WHERE reversed_billed>source_billed OR reversed_free>source_free OR reversed_net>source_net
             OR (final_residual AND (reversed_billed<>source_billed OR reversed_free<>source_free OR reversed_net<>source_net));
        END IF;
        IF bad_count<>0 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='cumulative purchase return exceeds source or final residual is incomplete'; END IF;
    IF header.return_source_kind='invoiced' THEN
          SELECT count(*) INTO bad_count FROM finance.adjustment_note_lines adjustment_line
            JOIN finance.adjustment_notes adjustment ON adjustment.org_id=adjustment_line.org_id AND adjustment.id=adjustment_line.adjustment_note_id
            JOIN procurement.supplier_invoice_receipt_allocations allocation ON allocation.org_id=adjustment_line.org_id AND allocation.supplier_invoice_line_id=adjustment_line.supplier_invoice_line_id
            JOIN procurement.purchase_return_lines current ON current.org_id=allocation.org_id AND current.supplier_invoice_receipt_allocation_id=allocation.id
           WHERE current.org_id=organization_id AND current.purchase_return_id=resource_id AND adjustment.status='posted'
             AND adjustment.sales_return_id IS NULL AND adjustment.purchase_return_id IS NULL;
          IF bad_count<>0 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='return after a generic adjustment is blocked because the reversal artifact cannot encode an adjusted original basis'; END IF;
          WITH current_sources AS (
            SELECT DISTINCT allocation.supplier_invoice_line_id source_id FROM procurement.purchase_return_lines line
             JOIN procurement.supplier_invoice_receipt_allocations allocation ON allocation.org_id=line.org_id AND allocation.id=line.supplier_invoice_receipt_allocation_id
            WHERE line.org_id=organization_id AND line.purchase_return_id=resource_id
          ), returned AS (
            SELECT allocation.supplier_invoice_line_id source_id,sum(line.base_billed_quantity) billed,sum(line.base_free_quantity) free,
                   sum(line.net_value_amount) net,sum(line.gst_taxable_value) taxable,sum(line.cgst_amount) cgst,sum(line.sgst_amount) sgst,
                   sum(line.igst_amount) igst,sum(line.cess_amount) cess,sum(line.line_total) total
              FROM procurement.purchase_return_lines line JOIN procurement.purchase_returns parent ON parent.org_id=line.org_id AND parent.id=line.purchase_return_id
              JOIN procurement.supplier_invoice_receipt_allocations allocation ON allocation.org_id=line.org_id AND allocation.id=line.supplier_invoice_receipt_allocation_id
              JOIN current_sources current ON current.source_id=allocation.supplier_invoice_line_id
             WHERE line.org_id=organization_id AND (parent.status='posted' OR parent.id=resource_id) GROUP BY allocation.supplier_invoice_line_id
          ), adjusted AS (
            SELECT line.supplier_invoice_line_id source_id,
                   sum((CASE WHEN note.document_effect='increase' THEN 1 ELSE -1 END)*line.base_billed_quantity) billed,
                   sum((CASE WHEN note.document_effect='increase' THEN 1 ELSE -1 END)*line.base_free_quantity) free,
                   sum((CASE WHEN note.document_effect='increase' THEN 1 ELSE -1 END)*line.net_value_amount) net,
                   sum((CASE WHEN note.document_effect='increase' THEN 1 ELSE -1 END)*line.gst_taxable_value) taxable,
                   sum((CASE WHEN note.document_effect='increase' THEN 1 ELSE -1 END)*line.cgst_amount) cgst,
                   sum((CASE WHEN note.document_effect='increase' THEN 1 ELSE -1 END)*line.sgst_amount) sgst,
                   sum((CASE WHEN note.document_effect='increase' THEN 1 ELSE -1 END)*line.igst_amount) igst,
                   sum((CASE WHEN note.document_effect='increase' THEN 1 ELSE -1 END)*line.cess_amount) cess,
                   sum((CASE WHEN note.document_effect='increase' THEN 1 ELSE -1 END)*line.line_total) total
              FROM finance.adjustment_note_lines line JOIN finance.adjustment_notes note ON note.org_id=line.org_id AND note.id=line.adjustment_note_id
              JOIN current_sources current ON current.source_id=line.supplier_invoice_line_id
             WHERE line.org_id=organization_id AND note.status='posted' AND note.sales_return_id IS NULL AND note.purchase_return_id IS NULL
             GROUP BY line.supplier_invoice_line_id
          )
          SELECT count(*) INTO bad_count FROM current_sources current JOIN procurement.supplier_invoice_lines source ON source.org_id=organization_id AND source.id=current.source_id
            JOIN returned ON returned.source_id=current.source_id LEFT JOIN adjusted ON adjusted.source_id=current.source_id
           WHERE coalesce(adjusted.billed,0)-returned.billed < -source.base_billed_quantity
              OR coalesce(adjusted.free,0)-returned.free < -source.base_free_quantity OR coalesce(adjusted.net,0)-returned.net < -source.net_value_amount
              OR coalesce(adjusted.taxable,0)-returned.taxable < -source.gst_taxable_value OR coalesce(adjusted.cgst,0)-returned.cgst < -source.cgst_amount
              OR coalesce(adjusted.sgst,0)-returned.sgst < -source.sgst_amount OR coalesce(adjusted.igst,0)-returned.igst < -source.igst_amount
              OR coalesce(adjusted.cess,0)-returned.cess < -source.cess_amount OR coalesce(adjusted.total,0)-returned.total < -source.line_total;
          IF bad_count<>0 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='combined purchase returns and generic adjustments exceed the original invoice'; END IF;
        END IF;
    IF header.return_source_kind='invoiced' THEN
          SELECT coalesce(sum(prior.grand_total),0),coalesce(sum(prior.rounding_adjustment),0) INTO cumulative_grand,cumulative_rounding
            FROM procurement.purchase_returns prior WHERE prior.org_id=organization_id AND prior.supplier_invoice_id=header.supplier_invoice_id
              AND (prior.status='posted' OR prior.id=resource_id);
          IF cumulative_grand>original.grand_total OR (original.rounding_adjustment>=0 AND (cumulative_rounding<0 OR cumulative_rounding>original.rounding_adjustment))
             OR (original.rounding_adjustment<0 AND (cumulative_rounding>0 OR cumulative_rounding<original.rounding_adjustment)) THEN
            RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='cumulative purchase return header exceeds original invoice'; END IF;
        END IF;
    WITH current_sources AS (
             SELECT DISTINCT CASE WHEN header.return_source_kind='invoiced' THEN allocation.supplier_invoice_line_id ELSE line.goods_receipt_line_id END source_id
               FROM procurement.purchase_return_lines line
               LEFT JOIN procurement.supplier_invoice_receipt_allocations allocation ON allocation.org_id=line.org_id AND allocation.id=line.supplier_invoice_receipt_allocation_id
              WHERE line.org_id=organization_id AND line.purchase_return_id=resource_id
           ), prior_rows AS (
             SELECT CASE WHEN prior.return_source_kind='invoiced' THEN allocation.supplier_invoice_line_id ELSE line.goods_receipt_line_id END source_id,
                    line.reversal_value_basis,line.billed_quantity,line.free_quantity,line.base_billed_quantity,line.base_free_quantity,calculated.item
               FROM procurement.purchase_return_lines line
               JOIN procurement.purchase_returns prior ON prior.org_id=line.org_id AND prior.id=line.purchase_return_id AND prior.status='posted' AND prior.id<>resource_id
               LEFT JOIN procurement.supplier_invoice_receipt_allocations allocation ON allocation.org_id=line.org_id AND allocation.id=line.supplier_invoice_receipt_allocation_id
               JOIN current_sources current ON current.source_id=CASE WHEN prior.return_source_kind='invoiced' THEN allocation.supplier_invoice_line_id ELSE line.goods_receipt_line_id END
               JOIN calculation.artifacts artifact ON artifact.org_id=prior.org_id AND artifact.purchase_return_id=prior.id AND artifact.status='consumed'
               JOIN LATERAL pg_catalog.jsonb_array_elements(pg_catalog.convert_from(artifact.output_bytes,'UTF8')::jsonb->'lines') calculated(item)
                 ON calculated.item->>'line_id'=current.source_id::text
              WHERE line.org_id=organization_id AND prior.return_source_kind=header.return_source_kind
                AND (header.return_source_kind='uninvoiced' OR prior.supplier_invoice_id=header.supplier_invoice_id)
           ), expected AS (
             SELECT source_id,min(reversal_value_basis) value_basis,count(DISTINCT reversal_value_basis) basis_count,
                    sum(billed_quantity) billed_quantity,sum(free_quantity) free_quantity,sum(base_billed_quantity) base_billed_quantity,sum(base_free_quantity) base_free_quantity,
                    sum((item->>'gross_amount')::numeric) gross_amount,sum((item->>'line_discount_amount')::numeric) line_discount_amount,
                    sum((item->>'document_discount_amount')::numeric) document_discount_amount,sum((item->>'net_value_amount')::numeric) net_value_amount,
                    sum((item->>'gst_taxable_value')::numeric) gst_taxable_value,sum((item->>'cgst_amount')::numeric) cgst_amount,
                    sum((item->>'sgst_amount')::numeric) sgst_amount,sum((item->>'igst_amount')::numeric) igst_amount,sum((item->>'cess_amount')::numeric) cess_amount
               FROM prior_rows GROUP BY source_id
           ), provided AS (SELECT value item FROM pg_catalog.jsonb_array_elements(input_doc#>'{reversal,prior_state,products}'))
           SELECT count(*) INTO bad_count FROM expected FULL JOIN provided ON provided.item->>'line_id'=expected.source_id::text
            WHERE expected.source_id IS NULL OR provided.item IS NULL OR expected.basis_count<>1 OR provided.item->>'value_basis' IS DISTINCT FROM expected.value_basis
               OR ROW((provided.item->>'reversed_billed_quantity')::numeric,(provided.item->>'reversed_free_quantity')::numeric,(provided.item->>'reversed_base_billed_quantity')::numeric,
                      (provided.item->>'reversed_base_free_quantity')::numeric,(provided.item->>'gross_price_amount')::numeric,(provided.item->>'line_discount_amount')::numeric,
                      (provided.item->>'document_discount_amount')::numeric,(provided.item->>'net_value_amount')::numeric,(provided.item->>'gst_taxable_value')::numeric,
                      (provided.item->>'cgst_amount')::numeric,(provided.item->>'sgst_amount')::numeric,(provided.item->>'igst_amount')::numeric,(provided.item->>'cess_amount')::numeric)
                  IS DISTINCT FROM ROW(expected.billed_quantity,expected.free_quantity,expected.base_billed_quantity,expected.base_free_quantity,expected.gross_amount,
                      expected.line_discount_amount,expected.document_discount_amount,expected.net_value_amount,expected.gst_taxable_value,
                      expected.cgst_amount,expected.sgst_amount,expected.igst_amount,expected.cess_amount);
           IF bad_count<>0 OR (input_doc#>>'{reversal,prior_state,rounding_adjustment}')::numeric IS DISTINCT FROM
              (SELECT coalesce(sum(prior.rounding_adjustment),0) FROM procurement.purchase_returns prior WHERE prior.org_id=organization_id
                AND prior.status='posted' AND prior.id<>resource_id AND prior.return_source_kind=header.return_source_kind
                AND (header.return_source_kind='uninvoiced' OR prior.supplier_invoice_id=header.supplier_invoice_id)) THEN
             RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='artifact prior state differs from locked posted purchase returns'; END IF;
END
$function$;

CREATE OR REPLACE FUNCTION "erp_commercial_commands"."assert_supplier_invoice_artifact"(p_org_id uuid, p_resource_id uuid, p_input jsonb, p_output jsonb)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE header procurement.supplier_invoices%ROWTYPE;
        expected_lines bigint;
        bad_count bigint;
BEGIN
    SELECT * INTO STRICT header FROM procurement.supplier_invoices
     WHERE org_id=p_org_id AND id=p_resource_id FOR UPDATE;
    IF header.status NOT IN ('approved','posted') THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='calculated invoice is not in its postable or posted state';
    END IF;
    IF header.calculation_ruleset_version IS DISTINCT FROM (
        SELECT erp_automation_reads.tax_ruleset_fingerprint(pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object('tax_code_version_id',tax_version.id,
                                         'ruleset_version',tax_version.ruleset_version)))
          FROM procurement.supplier_invoice_lines AS line
          JOIN tax.tax_code_versions AS tax_version ON tax_version.id=line.tax_code_version_id
         WHERE line.org_id=p_org_id AND line.supplier_invoice_id=p_resource_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='document tax-version fingerprint differs from prepared lines';
    END IF;
    IF p_input->>'calculation_kind'<>'document'
       OR p_input->>'operation'<>'procurement.supplier_invoice.post'
       OR p_input->>'resource_type'<>'supplier_invoice'
       OR p_input->>'resource_id'<>p_resource_id::text
       OR (p_input->>'aggregate_version')::bigint IS DISTINCT FROM (CASE WHEN header.status='posted' THEN header.row_version-1 ELSE header.row_version END)
       OR p_output->>'operation'<>'procurement.supplier_invoice.post'
       OR p_output->>'resource_type'<>'supplier_invoice'
       OR p_output->>'resource_id'<>p_resource_id::text
       OR (p_output->>'aggregate_version')::bigint IS DISTINCT FROM (CASE WHEN header.status='posted' THEN header.row_version-1 ELSE header.row_version END)
       OR p_output->>'ruleset_version' IS DISTINCT FROM header.calculation_ruleset_version
       OR p_output->>'currency_code' IS DISTINCT FROM header.currency_code
       OR p_input#>>'{document,gst_type}' IS DISTINCT FROM
          (CASE WHEN header.supply_type='intra_state' THEN 'intra_state' ELSE 'inter_state' END)
       OR p_input#>>'{document,zero_rated_mode}' IS DISTINCT FROM header.zero_rated_payment_mode
       OR p_input#>>'{document,tax_charge_mechanism}' IS DISTINCT FROM header.tax_charge_mechanism
       OR p_input#>>'{document,rounding_policy}' IS DISTINCT FROM header.rounding_policy
       OR p_input#>>'{document,document_discount,kind}' IS DISTINCT FROM header.document_discount_kind
       OR (CASE p_input#>>'{document,document_discount,basis}'
            WHEN 'pre_tax_value' THEN 'taxable_value'
            ELSE p_input#>>'{document,document_discount,basis}'
          END) IS DISTINCT FROM header.document_discount_basis
       OR (p_input#>>'{document,document_discount,value}')::numeric IS DISTINCT FROM header.document_discount_value
       OR ROW(
          (p_output#>>'{totals,subtotal}')::numeric,
          (p_output#>>'{totals,discount_total}')::numeric,
          (p_output#>>'{totals,charges_total}')::numeric,
          (p_output#>>'{totals,net_value_total}')::numeric,
          (p_output#>>'{totals,gst_taxable_total}')::numeric,
          (p_output#>>'{totals,cgst_total}')::numeric,
          (p_output#>>'{totals,sgst_total}')::numeric,
          (p_output#>>'{totals,igst_total}')::numeric,
          (p_output#>>'{totals,cess_total}')::numeric,
          (p_output#>>'{totals,recipient_assessed_tax_total}')::numeric,
          (p_output#>>'{totals,rounding_adjustment}')::numeric,
          (p_output#>>'{totals,grand_total}')::numeric,
          (p_output#>>'{totals,pre_round_total}')::numeric
       ) IS DISTINCT FROM ROW(
          header.subtotal,header.discount_total,header.charges_total,
          header.net_value_total,header.gst_taxable_total,header.cgst_total,
          header.sgst_total,header.igst_total,header.cess_total,
          header.recipient_assessed_tax_total,header.rounding_adjustment,
          header.grand_total,header.grand_total-header.rounding_adjustment
       ) THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='calculation artifact header differs from persisted invoice';
    END IF;

    SELECT count(*) INTO expected_lines FROM procurement.supplier_invoice_lines
     WHERE org_id=p_org_id AND supplier_invoice_id=p_resource_id;
    IF expected_lines=0
       OR pg_catalog.jsonb_array_length(p_output->'lines')<>expected_lines
       OR pg_catalog.jsonb_array_length(p_input#>'{document,products}')
          +pg_catalog.jsonb_array_length(p_input#>'{document,charges}')<>expected_lines
       OR (SELECT count(DISTINCT value->>'line_id') FROM pg_catalog.jsonb_array_elements(p_output->'lines'))<>expected_lines
       OR (SELECT count(DISTINCT value->>'line_id')
             FROM (
               SELECT value FROM pg_catalog.jsonb_array_elements(p_input#>'{document,products}')
               UNION ALL
               SELECT value FROM pg_catalog.jsonb_array_elements(p_input#>'{document,charges}')
             ) AS input_items)<>expected_lines THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='calculation artifact line identity or cardinality differs';
    END IF;

    WITH output_lines AS (
        SELECT value AS item FROM pg_catalog.jsonb_array_elements(p_output->'lines')
    ), input_lines AS (
        SELECT value AS item,'product'::text AS line_kind
          FROM pg_catalog.jsonb_array_elements(p_input#>'{document,products}')
        UNION ALL
        SELECT value AS item,'charge'::text AS line_kind
          FROM pg_catalog.jsonb_array_elements(p_input#>'{document,charges}')
    )
    SELECT count(*) INTO bad_count
      FROM procurement.supplier_invoice_lines AS line
      LEFT JOIN output_lines AS output_line ON output_line.item->>'line_id'=line.id::text
      LEFT JOIN input_lines AS input_line ON input_line.item->>'line_id'=line.id::text
      LEFT JOIN tax.tax_code_versions AS tax_version ON tax_version.id=line.tax_code_version_id
     WHERE line.org_id=p_org_id AND line.supplier_invoice_id=p_resource_id
       AND (
         output_line.item IS NULL OR input_line.item IS NULL
         OR output_line.item->>'line_kind' IS DISTINCT FROM line.line_kind
         OR (output_line.item->>'final_residual')::boolean
         OR input_line.line_kind IS DISTINCT FROM line.line_kind
         OR input_line.item->>'tax_charge_mechanism' IS DISTINCT FROM line.tax_charge_mechanism
         OR input_line.item->>'price_basis' IS DISTINCT FROM line.price_basis
         OR input_line.item->>'taxability_snapshot' IS DISTINCT FROM line.taxability_snapshot
         OR (input_line.item->>'document_discount_eligible')::boolean IS DISTINCT FROM line.document_discount_eligible
         OR (input_line.item->>'cess_rate')::numeric IS DISTINCT FROM
            CASE WHEN line.taxability_snapshot='taxable' THEN tax_version.cess_rate ELSE 0 END
         OR (input_line.item->>'gst_rate')::numeric IS DISTINCT FROM
            CASE WHEN line.taxability_snapshot='taxable'
                       OR (line.taxability_snapshot='zero_rated' AND header.zero_rated_payment_mode='with_igst')
                 THEN tax_version.igst_rate ELSE 0 END
         OR tax_version.id IS NULL
         OR tax_version.code IS DISTINCT FROM line.tax_classification_code_snapshot
         OR tax_version.code_kind IS DISTINCT FROM CASE WHEN line.line_kind='product' THEN 'hsn' ELSE 'sac' END
         OR (tax_version.org_id IS NOT NULL AND (
              tax_version.org_id IS DISTINCT FROM p_org_id
              OR line.line_kind<>'product'
              OR tax_version.product_id IS DISTINCT FROM line.product_id
              OR NOT EXISTS (
                  SELECT 1 FROM erp_automation_reads.resolve_product_tax(p_org_id,line.product_id,header.supplier_invoice_date) AS scoped_tax
                   WHERE scoped_tax.id=tax_version.id)))
         OR header.supplier_invoice_date<tax_version.effective_from
         OR (tax_version.effective_to IS NOT NULL AND header.supplier_invoice_date>tax_version.effective_to)
         OR NOT (line.taxability_snapshot=tax_version.taxability
                 OR (line.taxability_snapshot='zero_rated' AND header.supply_type IN ('export','sez')))
         OR (line.line_kind='product' AND (
              (input_line.item->>'base_billed_quantity')::numeric IS DISTINCT FROM line.base_billed_quantity
              OR (input_line.item->>'base_free_quantity')::numeric IS DISTINCT FROM line.base_free_quantity
              OR (input_line.item->>'billed_quantity')::numeric IS DISTINCT FROM line.billed_quantity
              OR (input_line.item->>'free_quantity')::numeric IS DISTINCT FROM line.free_quantity
              OR (input_line.item->>'uom_conversion_factor')::numeric IS DISTINCT FROM line.uom_conversion_factor
              OR (input_line.item->>'quoted_unit_rate')::numeric IS DISTINCT FROM line.quoted_unit_rate
              OR input_line.item->>'free_supply_tax_treatment' IS DISTINCT FROM line.free_supply_tax_treatment
              OR input_line.item#>>'{line_discount,kind}' IS DISTINCT FROM line.line_discount_kind
              OR CASE input_line.item#>>'{line_discount,basis}'
                   WHEN 'pre_tax_value' THEN 'taxable_value'
                   ELSE input_line.item#>>'{line_discount,basis}'
                 END IS DISTINCT FROM line.line_discount_basis
              OR (input_line.item#>>'{line_discount,value}')::numeric IS DISTINCT FROM line.line_discount_value
         ))
         OR (line.line_kind='charge' AND (
              input_line.item->>'charge_code' IS DISTINCT FROM line.charge_code
              OR (input_line.item->>'quoted_amount')::numeric IS DISTINCT FROM line.gross_amount
         ))
         OR ROW(
            (output_line.item->>'gross_amount')::numeric,
            (output_line.item->>'line_discount_amount')::numeric,
            (output_line.item->>'line_taxable_discount_amount')::numeric,
            (output_line.item->>'document_discount_amount')::numeric,
            (output_line.item->>'document_taxable_discount_amount')::numeric,
            (output_line.item->>'net_value_amount')::numeric,
            (output_line.item->>'gst_taxable_value')::numeric,
            (output_line.item->>'cgst_rate')::numeric,
            (output_line.item->>'sgst_rate')::numeric,
            (output_line.item->>'igst_rate')::numeric,
            (output_line.item->>'cess_rate')::numeric,
            (output_line.item->>'cgst_amount')::numeric,
            (output_line.item->>'sgst_amount')::numeric,
            (output_line.item->>'igst_amount')::numeric,
            (output_line.item->>'cess_amount')::numeric,
            (output_line.item->>'line_total')::numeric,
            (output_line.item->>'recipient_assessed_tax_amount')::numeric
         ) IS DISTINCT FROM ROW(
            line.gross_amount,line.line_discount_amount,line.line_taxable_discount_amount,
            line.document_discount_amount,line.document_taxable_discount_amount,
            line.net_value_amount,line.gst_taxable_value,line.cgst_rate,line.sgst_rate,
            line.igst_rate,line.cess_rate,line.cgst_amount,line.sgst_amount,
            line.igst_amount,line.cess_amount,line.line_total,
            CASE WHEN line.tax_charge_mechanism='reverse_charge'
                 THEN line.cgst_amount+line.sgst_amount+line.igst_amount+line.cess_amount ELSE 0 END
         )
       );
    IF bad_count<>0 THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='calculation artifact input, tax version, or line output differs';
    END IF;
END
$function$;

CREATE OR REPLACE FUNCTION "erp_commercial_commands"."post_supplier_invoice"(organization_id uuid, resource_id uuid, artifact_id uuid, actor_id uuid, request_id uuid, command_request_id uuid, tax_document_id uuid, journal_id uuid, journal_number varchar, event_id uuid, open_item_id uuid, inventory_document_id uuid, inventory_key_hash bytea, inventory_request_hash bytea, key_hash bytea, request_hash bytea, expires_at timestamptz)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
DECLARE header procurement.supplier_invoices%ROWTYPE; artifact calculation.artifacts%ROWTYPE; line record;
        claim_id uuid; replay_id uuid; input_doc jsonb; output_doc jsonb; consumed bytea;
        party_id uuid; party_account uuid; party_default_account uuid; posted_time timestamptz:=pg_catalog.transaction_timestamp();
        line_no integer:=2; component_amount numeric(20,2); consumed_variance numeric(20,2); role_account uuid; role_key varchar;
        total_debit numeric(20,2); total_credit numeric(20,2); tax_effective date; source_hash bytea; noncreditable_tax numeric(20,2);
        eligible_cgst numeric(20,2):=0; eligible_sgst numeric(20,2):=0; eligible_igst numeric(20,2):=0; eligible_cess numeric(20,2):=0;
        inventory_value numeric(20,2):=0; inventory_entries bigint:=0; product_lines boolean:=false; allocated_lines boolean:=false;
        line_snapshot jsonb; registration_scope_count bigint;
BEGIN
    PERFORM erp_trade_commands.assert_context(organization_id,actor_id);
    IF NULLIF(pg_catalog.current_setting('app.request_id',true),'')::uuid IS DISTINCT FROM request_id THEN
      RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='commercial request context mismatch'; END IF;
    SELECT * INTO STRICT header FROM procurement.supplier_invoices WHERE org_id=organization_id AND id=resource_id FOR UPDATE;
    PERFORM erp_trade_commands.assert_permission('procurement.invoice.post',header.branch_id);
    IF NOT erp_security.has_permission('finance.journal.post',NULL::uuid) THEN
      RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='finance journal permission denied'; END IF;
    SELECT p_claim_id,p_replay_resource_id INTO claim_id,replay_id FROM erp_trade_commands.claim(
      organization_id,actor_id,'procurement.supplier_invoice.post',key_hash,request_hash,expires_at);
    IF replay_id IS NOT NULL THEN IF replay_id<>resource_id THEN RAISE EXCEPTION USING ERRCODE='23505', MESSAGE='commercial replay mismatch'; END IF; RETURN replay_id; END IF;
    SELECT * INTO STRICT artifact FROM calculation.artifacts WHERE org_id=organization_id AND id=artifact_id FOR UPDATE;
    input_doc:=pg_catalog.convert_from(artifact.input_bytes,'UTF8')::jsonb;
    output_doc:=pg_catalog.convert_from(artifact.output_bytes,'UTF8')::jsonb;
    IF artifact.supplier_invoice_id IS DISTINCT FROM resource_id OR artifact.engine_version IS DISTINCT FROM output_doc->>'engine_version'
       OR artifact.ruleset_version IS DISTINCT FROM output_doc->>'ruleset_version' THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='typed calculation artifact metadata mismatch'; END IF;
    PERFORM "erp_commercial_commands".assert_supplier_invoice_artifact(organization_id,resource_id,input_doc,output_doc);

    SELECT account.party_id,account.default_payable_account_id INTO party_id,party_default_account
      FROM parties.supplier_accounts account WHERE account.org_id=organization_id AND account.id=header.supplier_account_id AND account.status='active' FOR SHARE;
    IF party_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='commercial party account is inactive'; END IF;
    party_account:="erp_commercial_commands".resolve_role_account(organization_id,header.branch_id,'accounts_payable','liability',header.currency_code,true);
    IF party_default_account IS DISTINCT FROM party_account THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='party default ledger differs from active branch account-role mapping'; END IF;
    PERFORM 1 FROM tax.registrations registration WHERE registration.org_id=organization_id AND registration.id=header.buyer_tax_registration_id
      AND registration.status='active' AND registration.effective_from<=header.supplier_invoice_date
      AND (registration.effective_to IS NULL OR registration.effective_to>=header.supplier_invoice_date) FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='document tax registration is not active on document date'; END IF;
    SELECT count(*) INTO registration_scope_count FROM tax.registration_branches association
     WHERE association.org_id=organization_id AND association.registration_id=header.buyer_tax_registration_id
       AND association.branch_id=header.branch_id AND association.status='active'
       AND association.effective_from<=header.supplier_invoice_date
       AND (association.effective_to IS NULL OR association.effective_to>=header.supplier_invoice_date);
    IF registration_scope_count<>1 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='document requires exactly one effective branch registration association'; END IF;
    PERFORM 1 FROM tax.registration_branches association
     WHERE association.org_id=organization_id AND association.registration_id=header.buyer_tax_registration_id
       AND association.branch_id=header.branch_id AND association.status='active'
       AND association.effective_from<=header.supplier_invoice_date
       AND (association.effective_to IS NULL OR association.effective_to>=header.supplier_invoice_date) FOR SHARE;
    SELECT min(version.effective_from) INTO tax_effective FROM procurement.supplier_invoice_lines tax_line JOIN tax.tax_code_versions version ON version.id=tax_line.tax_code_version_id
      WHERE tax_line.org_id=organization_id AND tax_line.supplier_invoice_id=resource_id
        AND ((version.org_id IS NULL AND version.status='active') OR
             (version.org_id=organization_id AND version.product_id=tax_line.product_id
              AND tax_line.line_kind='product' AND version.status='source_snapshot'
              AND EXISTS (SELECT 1 FROM erp_automation_reads.resolve_product_tax(
                  organization_id,tax_line.product_id,header.supplier_invoice_date) resolved_tax WHERE resolved_tax.id=version.id)))
        AND version.effective_from<=header.supplier_invoice_date AND (version.effective_to IS NULL OR version.effective_to>=header.supplier_invoice_date)
      HAVING erp_automation_reads.tax_ruleset_fingerprint(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
               'tax_code_version_id',version.id,'ruleset_version',version.ruleset_version)))=header.calculation_ruleset_version
        AND count(*)=(SELECT count(*) FROM procurement.supplier_invoice_lines expected WHERE expected.org_id=organization_id AND expected.supplier_invoice_id=resource_id);
    IF tax_effective IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='invoice tax versions or document fingerprint are not valid'; END IF;

    IF inventory_document_id IS NOT NULL THEN
          inventory_document_id:=erp_trade_commands_v2.prepare_supplier_invoice_landed_cost_adjustment(
            organization_id,resource_id,inventory_document_id,actor_id);
        END IF;
    consumed:=erp_calculation_authority.consume_artifact(organization_id,artifact_id,'procurement.supplier_invoice.post','supplier_invoice',resource_id,
      header.row_version,request_id,command_request_id,claim_id);
    IF pg_catalog.convert_from(consumed,'UTF8')::jsonb IS DISTINCT FROM output_doc THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='consumed calculation changed'; END IF;

    INSERT INTO finance.journal_entries(org_id,id,journal_number,posting_date,description,transaction_currency,functional_currency,fx_rate,
      transaction_debit_total,transaction_credit_total,functional_debit_total,functional_credit_total,status,created_by_membership_id,updated_by_membership_id)
    VALUES(organization_id,journal_id,journal_number,header.supplier_invoice_date,'supplier_invoice',header.currency_code,'INR',1,
      header.grand_total,header.grand_total,header.grand_total,header.grand_total,'draft',actor_id,actor_id);
    PERFORM "erp_commercial_commands".add_journal_line(organization_id,journal_id,1,party_account,header.branch_id,party_id,
      'Supplier payable',0,header.grand_total,actor_id);
    FOR line IN SELECT * FROM procurement.supplier_invoice_lines WHERE org_id=organization_id AND supplier_invoice_id=resource_id ORDER BY line_number,id LOOP
        PERFORM "erp_commercial_commands".assert_line_account(organization_id,line.net_value_account_id,CASE WHEN line.inventory_cost_treatment='capitalize' THEN 'asset' ELSE 'expense' END,header.currency_code);
        noncreditable_tax:=CASE WHEN line.itc_eligibility='eligible' THEN 0 ELSE line.cgst_amount+line.sgst_amount+line.igst_amount+line.cess_amount END;
        IF line.itc_eligibility='eligible' THEN
          eligible_cgst:=eligible_cgst+line.cgst_amount; eligible_sgst:=eligible_sgst+line.sgst_amount;
          eligible_igst:=eligible_igst+line.igst_amount; eligible_cess:=eligible_cess+line.cess_amount;
        END IF;
        PERFORM "erp_commercial_commands".add_journal_line(organization_id,journal_id,line_no,line.net_value_account_id,header.branch_id,NULL,
          'Supplier invoice net value and noncreditable tax',line.net_value_amount+noncreditable_tax,0,actor_id); line_no:=line_no+1;
        IF line.inventory_cost_treatment='capitalize' THEN
          consumed_variance:=erp_trade_commands_v2.consumed_landed_cost_pool(organization_id,line.id);
          IF consumed_variance<>0 THEN
            role_account:=erp_commercial_commands.resolve_role_account(
              organization_id,header.branch_id,'purchase_price_variance','expense',header.currency_code,false);
            PERFORM "erp_commercial_commands".add_journal_line(organization_id,journal_id,line_no,role_account,header.branch_id,NULL,
              'Consumed supplier price or landed-cost variance',
              CASE WHEN consumed_variance>0 THEN consumed_variance ELSE 0 END,
              CASE WHEN consumed_variance<0 THEN -consumed_variance ELSE 0 END,actor_id); line_no:=line_no+1;
            PERFORM "erp_commercial_commands".add_journal_line(organization_id,journal_id,line_no,line.net_value_account_id,header.branch_id,NULL,
              'Reclassify consumed variance out of inventory',
              CASE WHEN consumed_variance<0 THEN -consumed_variance ELSE 0 END,
              CASE WHEN consumed_variance>0 THEN consumed_variance ELSE 0 END,actor_id); line_no:=line_no+1;
          END IF;
        END IF;
    END LOOP;
    NULL;
    FOR role_key,component_amount IN SELECT * FROM (VALUES
      ('input_cgst'::varchar,eligible_cgst),
      ('input_sgst'::varchar,eligible_sgst),
      ('input_igst'::varchar,eligible_igst),
      ('input_cess'::varchar,eligible_cess)) AS component(role_key,amount)
    LOOP
      IF component_amount>0 AND component_amount>0 THEN
        role_account:="erp_commercial_commands".resolve_role_account(organization_id,header.branch_id,role_key,'asset',header.currency_code,false);
        PERFORM "erp_commercial_commands".add_journal_line(organization_id,journal_id,line_no,role_account,header.branch_id,NULL,'Eligible input tax',component_amount,0,actor_id); line_no:=line_no+1;
      END IF;
    END LOOP;
    
    IF header.tax_charge_mechanism='reverse_charge' THEN
      FOR role_key,component_amount IN SELECT * FROM (VALUES
        ('rcm_cgst_payable'::varchar,header.cgst_total),('rcm_sgst_payable'::varchar,header.sgst_total),
        ('rcm_igst_payable'::varchar,header.igst_total),('rcm_cess_payable'::varchar,header.cess_total)) AS component(role_key,amount)
      LOOP
        IF component_amount>0 THEN role_account:=erp_commercial_commands.resolve_role_account(organization_id,header.branch_id,role_key,'liability',header.currency_code,false);
          PERFORM erp_commercial_commands.add_journal_line(organization_id,journal_id,line_no,role_account,header.branch_id,NULL,'Self-assessed reverse-charge liability',0,component_amount,actor_id); line_no:=line_no+1;
        END IF;
      END LOOP;
    END IF;
    
    IF header.rounding_adjustment<>0 THEN
      role_key:=CASE WHEN header.rounding_adjustment>0 THEN 'rounding_loss' ELSE 'rounding_gain' END;
      role_account:=erp_commercial_commands.resolve_role_account(organization_id,header.branch_id,role_key,CASE WHEN role_key='rounding_gain' THEN 'income' ELSE 'expense' END,header.currency_code,false);
      PERFORM erp_commercial_commands.add_journal_line(organization_id,journal_id,line_no,role_account,header.branch_id,NULL,'Signed rounding adjustment',
        CASE WHEN header.rounding_adjustment>0 THEN abs(header.rounding_adjustment) ELSE 0 END,
        CASE WHEN header.rounding_adjustment<0 THEN abs(header.rounding_adjustment) ELSE 0 END,actor_id); line_no:=line_no+1;
    END IF;
    SELECT coalesce(sum(transaction_debit),0),coalesce(sum(transaction_credit),0) INTO total_debit,total_credit
      FROM finance.journal_lines WHERE org_id=organization_id AND journal_entry_id=journal_id;
    IF total_debit<>total_credit OR total_debit=0 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='commercial journal does not exactly balance'; END IF;
    UPDATE finance.journal_entries SET transaction_debit_total=total_debit,transaction_credit_total=total_credit,
      functional_debit_total=total_debit,functional_credit_total=total_credit,status='posted',posted_at=posted_time,posted_by_membership_id=actor_id,
      updated_at=posted_time,updated_by_membership_id=actor_id,row_version=row_version+1 WHERE org_id=organization_id AND id=journal_id;
    UPDATE procurement.supplier_invoices SET status='posted',posted_at=posted_time,posted_by_membership_id=actor_id,
      updated_at=posted_time,updated_by_membership_id=actor_id,row_version=row_version+1 WHERE org_id=organization_id AND id=resource_id AND status='approved';
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='invoice posting state changed'; END IF;
    IF inventory_document_id IS NOT NULL THEN
          PERFORM erp_trade_commands_v2.post_landed_cost_adjustment(
            organization_id,inventory_document_id,actor_id,inventory_key_hash,inventory_request_hash,expires_at);
        END IF;
    SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(source_line) ORDER BY source_line.line_number,source_line.id) INTO line_snapshot
      FROM procurement.supplier_invoice_lines source_line WHERE source_line.org_id=organization_id AND source_line.supplier_invoice_id=resource_id;
    source_hash:=extensions.digest(pg_catalog.convert_to((pg_catalog.to_jsonb(header)||pg_catalog.jsonb_build_object('lines',line_snapshot,'artifact',pg_catalog.encode(artifact.output_sha256,'hex')))::text,'UTF8'),'sha256');
    INSERT INTO tax.documents(org_id,id,registration_id,supplier_invoice_id,document_class,document_number,document_date,direction,
      counterparty_party_id,counterparty_gstin,place_of_supply_state_code,supply_type,zero_rated_payment_mode,tax_charge_mechanism,
      tax_liability_party,document_effect,currency_code,net_value_amount,gst_taxable_value,cgst_amount,sgst_amount,igst_amount,cess_amount,
      self_assessed_tax_amount,rounding_adjustment,counterparty_payable_amount,tax_ruleset_version,tax_ruleset_effective_date,source_hash,posted_at,created_by_membership_id)
    VALUES(organization_id,tax_document_id,header.buyer_tax_registration_id,resource_id,'supplier_invoice',header.supplier_invoice_number,header.supplier_invoice_date,'inward',
      party_id,header.supplier_gstin_snapshot,header.place_of_supply_state_code,header.supply_type,header.zero_rated_payment_mode,header.tax_charge_mechanism,
      CASE WHEN header.tax_charge_mechanism='normal' THEN 'supplier' ELSE 'recipient' END,'original',header.currency_code,
      header.net_value_total,header.gst_taxable_total,header.cgst_total,header.sgst_total,header.igst_total,header.cess_total,
      CASE WHEN 'inward'='inward' AND header.tax_charge_mechanism='reverse_charge' THEN header.recipient_assessed_tax_total ELSE 0 END,
      header.rounding_adjustment,header.grand_total,header.calculation_ruleset_version,tax_effective,source_hash,posted_time,actor_id);
    INSERT INTO finance.accounting_events(org_id,id,event_type,supplier_invoice_id,journal_entry_id,occurred_at,source_posted_at,created_by_membership_id)
    VALUES(organization_id,event_id,'supplier_invoice',resource_id,journal_id,posted_time,posted_time,actor_id);
    INSERT INTO finance.open_items(org_id,id,accounting_event_id,party_id,item_side,document_number,document_date,due_date,currency_code,
      principal_amount,functional_principal_amount,status,created_by_membership_id)
    VALUES(organization_id,open_item_id,event_id,party_id,'payable',header.supplier_invoice_number,header.supplier_invoice_date,
      header.due_date,header.currency_code,header.grand_total,header.grand_total,'open',actor_id);
    PERFORM erp_trade_commands.finish_claim(organization_id,claim_id,'procurement.supplier_invoices',resource_id);
    RETURN resource_id;
END
$function$;

CREATE OR REPLACE FUNCTION "erp_commercial_commands"."assert_sales_invoice_artifact"(p_org_id uuid, p_resource_id uuid, p_input jsonb, p_output jsonb)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE header sales.invoices%ROWTYPE;
        expected_lines bigint;
        bad_count bigint;
BEGIN
    SELECT * INTO STRICT header FROM sales.invoices
     WHERE org_id=p_org_id AND id=p_resource_id FOR UPDATE;
    IF header.status NOT IN ('draft','posted') THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='calculated invoice is not in its postable or posted state';
    END IF;
    IF header.calculation_ruleset_version IS DISTINCT FROM (
        SELECT erp_automation_reads.tax_ruleset_fingerprint(pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object('tax_code_version_id',tax_version.id,
                                         'ruleset_version',tax_version.ruleset_version)))
          FROM sales.invoice_lines AS line
          JOIN tax.tax_code_versions AS tax_version ON tax_version.id=line.tax_code_version_id
         WHERE line.org_id=p_org_id AND line.invoice_id=p_resource_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='document tax-version fingerprint differs from prepared lines';
    END IF;
    IF p_input->>'calculation_kind'<>'document'
       OR p_input->>'operation'<>'sales.invoice.post'
       OR p_input->>'resource_type'<>'sales_invoice'
       OR p_input->>'resource_id'<>p_resource_id::text
       OR (p_input->>'aggregate_version')::bigint IS DISTINCT FROM (CASE WHEN header.status='posted' THEN header.row_version-1 ELSE header.row_version END)
       OR p_output->>'operation'<>'sales.invoice.post'
       OR p_output->>'resource_type'<>'sales_invoice'
       OR p_output->>'resource_id'<>p_resource_id::text
       OR (p_output->>'aggregate_version')::bigint IS DISTINCT FROM (CASE WHEN header.status='posted' THEN header.row_version-1 ELSE header.row_version END)
       OR p_output->>'ruleset_version' IS DISTINCT FROM header.calculation_ruleset_version
       OR p_output->>'currency_code' IS DISTINCT FROM header.currency_code
       OR p_input#>>'{document,gst_type}' IS DISTINCT FROM
          (CASE WHEN header.supply_type='intra_state' THEN 'intra_state' ELSE 'inter_state' END)
       OR p_input#>>'{document,zero_rated_mode}' IS DISTINCT FROM header.zero_rated_payment_mode
       OR p_input#>>'{document,tax_charge_mechanism}' IS DISTINCT FROM header.tax_charge_mechanism
       OR p_input#>>'{document,rounding_policy}' IS DISTINCT FROM header.rounding_policy
       OR p_input#>>'{document,document_discount,kind}' IS DISTINCT FROM header.document_discount_kind
       OR (CASE p_input#>>'{document,document_discount,basis}'
            WHEN 'pre_tax_value' THEN 'taxable_value'
            ELSE p_input#>>'{document,document_discount,basis}'
          END) IS DISTINCT FROM header.document_discount_basis
       OR (p_input#>>'{document,document_discount,value}')::numeric IS DISTINCT FROM header.document_discount_value
       OR ROW(
          (p_output#>>'{totals,subtotal}')::numeric,
          (p_output#>>'{totals,discount_total}')::numeric,
          (p_output#>>'{totals,charges_total}')::numeric,
          (p_output#>>'{totals,net_value_total}')::numeric,
          (p_output#>>'{totals,gst_taxable_total}')::numeric,
          (p_output#>>'{totals,cgst_total}')::numeric,
          (p_output#>>'{totals,sgst_total}')::numeric,
          (p_output#>>'{totals,igst_total}')::numeric,
          (p_output#>>'{totals,cess_total}')::numeric,
          (p_output#>>'{totals,recipient_assessed_tax_total}')::numeric,
          (p_output#>>'{totals,rounding_adjustment}')::numeric,
          (p_output#>>'{totals,grand_total}')::numeric,
          (p_output#>>'{totals,pre_round_total}')::numeric
       ) IS DISTINCT FROM ROW(
          header.subtotal,header.discount_total,header.charges_total,
          header.net_value_total,header.gst_taxable_total,header.cgst_total,
          header.sgst_total,header.igst_total,header.cess_total,
          header.recipient_assessed_tax_total,header.rounding_adjustment,
          header.grand_total,header.grand_total-header.rounding_adjustment
       ) THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='calculation artifact header differs from persisted invoice';
    END IF;

    SELECT count(*) INTO expected_lines FROM sales.invoice_lines
     WHERE org_id=p_org_id AND invoice_id=p_resource_id;
    IF expected_lines=0
       OR pg_catalog.jsonb_array_length(p_output->'lines')<>expected_lines
       OR pg_catalog.jsonb_array_length(p_input#>'{document,products}')
          +pg_catalog.jsonb_array_length(p_input#>'{document,charges}')<>expected_lines
       OR (SELECT count(DISTINCT value->>'line_id') FROM pg_catalog.jsonb_array_elements(p_output->'lines'))<>expected_lines
       OR (SELECT count(DISTINCT value->>'line_id')
             FROM (
               SELECT value FROM pg_catalog.jsonb_array_elements(p_input#>'{document,products}')
               UNION ALL
               SELECT value FROM pg_catalog.jsonb_array_elements(p_input#>'{document,charges}')
             ) AS input_items)<>expected_lines THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='calculation artifact line identity or cardinality differs';
    END IF;

    WITH output_lines AS (
        SELECT value AS item FROM pg_catalog.jsonb_array_elements(p_output->'lines')
    ), input_lines AS (
        SELECT value AS item,'product'::text AS line_kind
          FROM pg_catalog.jsonb_array_elements(p_input#>'{document,products}')
        UNION ALL
        SELECT value AS item,'charge'::text AS line_kind
          FROM pg_catalog.jsonb_array_elements(p_input#>'{document,charges}')
    )
    SELECT count(*) INTO bad_count
      FROM sales.invoice_lines AS line
      LEFT JOIN output_lines AS output_line ON output_line.item->>'line_id'=line.id::text
      LEFT JOIN input_lines AS input_line ON input_line.item->>'line_id'=line.id::text
      LEFT JOIN tax.tax_code_versions AS tax_version ON tax_version.id=line.tax_code_version_id
     WHERE line.org_id=p_org_id AND line.invoice_id=p_resource_id
       AND (
         output_line.item IS NULL OR input_line.item IS NULL
         OR output_line.item->>'line_kind' IS DISTINCT FROM line.line_kind
         OR (output_line.item->>'final_residual')::boolean
         OR input_line.line_kind IS DISTINCT FROM line.line_kind
         OR input_line.item->>'tax_charge_mechanism' IS DISTINCT FROM line.tax_charge_mechanism
         OR input_line.item->>'price_basis' IS DISTINCT FROM line.price_basis
         OR input_line.item->>'taxability_snapshot' IS DISTINCT FROM line.taxability_snapshot
         OR (input_line.item->>'document_discount_eligible')::boolean IS DISTINCT FROM line.document_discount_eligible
         OR (input_line.item->>'cess_rate')::numeric IS DISTINCT FROM
            CASE WHEN line.taxability_snapshot='taxable' THEN tax_version.cess_rate ELSE 0 END
         OR (input_line.item->>'gst_rate')::numeric IS DISTINCT FROM
            CASE WHEN line.taxability_snapshot='taxable'
                       OR (line.taxability_snapshot='zero_rated' AND header.zero_rated_payment_mode='with_igst')
                 THEN tax_version.igst_rate ELSE 0 END
         OR tax_version.id IS NULL
         OR tax_version.code IS DISTINCT FROM line.tax_classification_code_snapshot
         OR tax_version.code_kind IS DISTINCT FROM CASE WHEN line.line_kind='product' THEN 'hsn' ELSE 'sac' END
         OR (tax_version.org_id IS NOT NULL AND (
              tax_version.org_id IS DISTINCT FROM p_org_id
              OR line.line_kind<>'product'
              OR tax_version.product_id IS DISTINCT FROM line.product_id
              OR NOT EXISTS (
                  SELECT 1 FROM erp_automation_reads.resolve_product_tax(p_org_id,line.product_id,header.invoice_date) AS scoped_tax
                   WHERE scoped_tax.id=tax_version.id)))
         OR header.invoice_date<tax_version.effective_from
         OR (tax_version.effective_to IS NOT NULL AND header.invoice_date>tax_version.effective_to)
         OR NOT (line.taxability_snapshot=tax_version.taxability
                 OR (line.taxability_snapshot='zero_rated' AND header.supply_type IN ('export','sez')))
         OR (line.line_kind='product' AND (
              (input_line.item->>'base_billed_quantity')::numeric IS DISTINCT FROM line.base_billed_quantity
              OR (input_line.item->>'base_free_quantity')::numeric IS DISTINCT FROM line.base_free_quantity
              OR (input_line.item->>'billed_quantity')::numeric IS DISTINCT FROM line.billed_quantity
              OR (input_line.item->>'free_quantity')::numeric IS DISTINCT FROM line.free_quantity
              OR (input_line.item->>'uom_conversion_factor')::numeric IS DISTINCT FROM line.uom_conversion_factor
              OR (input_line.item->>'quoted_unit_rate')::numeric IS DISTINCT FROM line.quoted_unit_rate
              OR input_line.item->>'free_supply_tax_treatment' IS DISTINCT FROM line.free_supply_tax_treatment
              OR input_line.item#>>'{line_discount,kind}' IS DISTINCT FROM line.line_discount_kind
              OR CASE input_line.item#>>'{line_discount,basis}'
                   WHEN 'pre_tax_value' THEN 'taxable_value'
                   ELSE input_line.item#>>'{line_discount,basis}'
                 END IS DISTINCT FROM line.line_discount_basis
              OR (input_line.item#>>'{line_discount,value}')::numeric IS DISTINCT FROM line.line_discount_value
         ))
         OR (line.line_kind='charge' AND (
              input_line.item->>'charge_code' IS DISTINCT FROM line.charge_code
              OR (input_line.item->>'quoted_amount')::numeric IS DISTINCT FROM line.gross_amount
         ))
         OR ROW(
            (output_line.item->>'gross_amount')::numeric,
            (output_line.item->>'line_discount_amount')::numeric,
            (output_line.item->>'line_taxable_discount_amount')::numeric,
            (output_line.item->>'document_discount_amount')::numeric,
            (output_line.item->>'document_taxable_discount_amount')::numeric,
            (output_line.item->>'net_value_amount')::numeric,
            (output_line.item->>'gst_taxable_value')::numeric,
            (output_line.item->>'cgst_rate')::numeric,
            (output_line.item->>'sgst_rate')::numeric,
            (output_line.item->>'igst_rate')::numeric,
            (output_line.item->>'cess_rate')::numeric,
            (output_line.item->>'cgst_amount')::numeric,
            (output_line.item->>'sgst_amount')::numeric,
            (output_line.item->>'igst_amount')::numeric,
            (output_line.item->>'cess_amount')::numeric,
            (output_line.item->>'line_total')::numeric,
            (output_line.item->>'recipient_assessed_tax_amount')::numeric
         ) IS DISTINCT FROM ROW(
            line.gross_amount,line.line_discount_amount,line.line_taxable_discount_amount,
            line.document_discount_amount,line.document_taxable_discount_amount,
            line.net_value_amount,line.gst_taxable_value,line.cgst_rate,line.sgst_rate,
            line.igst_rate,line.cess_rate,line.cgst_amount,line.sgst_amount,
            line.igst_amount,line.cess_amount,line.line_total,
            CASE WHEN line.tax_charge_mechanism='reverse_charge'
                 THEN line.cgst_amount+line.sgst_amount+line.igst_amount+line.cess_amount ELSE 0 END
         )
       );
    IF bad_count<>0 THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='calculation artifact input, tax version, or line output differs';
    END IF;
END
$function$;

CREATE OR REPLACE FUNCTION "erp_commercial_commands"."post_sales_invoice"(organization_id uuid, resource_id uuid, artifact_id uuid, actor_id uuid, request_id uuid, command_request_id uuid, tax_document_id uuid, journal_id uuid, journal_number varchar, event_id uuid, open_item_id uuid, inventory_document_id uuid, key_hash bytea, request_hash bytea, expires_at timestamptz)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
DECLARE header sales.invoices%ROWTYPE; artifact calculation.artifacts%ROWTYPE; line record;
        claim_id uuid; replay_id uuid; input_doc jsonb; output_doc jsonb; consumed bytea;
        party_id uuid; party_account uuid; party_default_account uuid; posted_time timestamptz:=pg_catalog.transaction_timestamp();
        line_no integer:=2; component_amount numeric(20,2); consumed_variance numeric(20,2); role_account uuid; role_key varchar;
        total_debit numeric(20,2); total_credit numeric(20,2); tax_effective date; source_hash bytea; noncreditable_tax numeric(20,2);
        eligible_cgst numeric(20,2):=0; eligible_sgst numeric(20,2):=0; eligible_igst numeric(20,2):=0; eligible_cess numeric(20,2):=0;
        inventory_value numeric(20,2):=0; inventory_entries bigint:=0; product_lines boolean:=false; allocated_lines boolean:=false;
        line_snapshot jsonb; registration_scope_count bigint;
BEGIN
    PERFORM erp_trade_commands.assert_context(organization_id,actor_id);
    IF NULLIF(pg_catalog.current_setting('app.request_id',true),'')::uuid IS DISTINCT FROM request_id THEN
      RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='commercial request context mismatch'; END IF;
    SELECT * INTO STRICT header FROM sales.invoices WHERE org_id=organization_id AND id=resource_id FOR UPDATE;
    PERFORM erp_trade_commands.assert_permission('sales.invoice.post',header.branch_id);
    IF NOT erp_security.has_permission('finance.journal.post',NULL::uuid) THEN
      RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='finance journal permission denied'; END IF;
    SELECT p_claim_id,p_replay_resource_id INTO claim_id,replay_id FROM erp_trade_commands.claim(
      organization_id,actor_id,'sales.invoice.post',key_hash,request_hash,expires_at);
    IF replay_id IS NOT NULL THEN IF replay_id<>resource_id THEN RAISE EXCEPTION USING ERRCODE='23505', MESSAGE='commercial replay mismatch'; END IF; RETURN replay_id; END IF;
    SELECT * INTO STRICT artifact FROM calculation.artifacts WHERE org_id=organization_id AND id=artifact_id FOR UPDATE;
    input_doc:=pg_catalog.convert_from(artifact.input_bytes,'UTF8')::jsonb;
    output_doc:=pg_catalog.convert_from(artifact.output_bytes,'UTF8')::jsonb;
    IF artifact.sales_invoice_id IS DISTINCT FROM resource_id OR artifact.engine_version IS DISTINCT FROM output_doc->>'engine_version'
       OR artifact.ruleset_version IS DISTINCT FROM output_doc->>'ruleset_version' THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='typed calculation artifact metadata mismatch'; END IF;
    PERFORM "erp_commercial_commands".assert_sales_invoice_artifact(organization_id,resource_id,input_doc,output_doc);

    SELECT account.party_id,account.default_receivable_account_id INTO party_id,party_default_account
      FROM parties.customer_accounts account WHERE account.org_id=organization_id AND account.id=header.customer_account_id AND account.status='active' FOR SHARE;
    IF party_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='commercial party account is inactive'; END IF;
    party_account:="erp_commercial_commands".resolve_role_account(organization_id,header.branch_id,'accounts_receivable','asset',header.currency_code,true);
    IF party_default_account IS DISTINCT FROM party_account THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='party default ledger differs from active branch account-role mapping'; END IF;
    PERFORM 1 FROM tax.registrations registration WHERE registration.org_id=organization_id AND registration.id=header.seller_tax_registration_id
      AND registration.status='active' AND registration.effective_from<=header.invoice_date
      AND (registration.effective_to IS NULL OR registration.effective_to>=header.invoice_date) FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='document tax registration is not active on document date'; END IF;
    SELECT count(*) INTO registration_scope_count FROM tax.registration_branches association
     WHERE association.org_id=organization_id AND association.registration_id=header.seller_tax_registration_id
       AND association.branch_id=header.branch_id AND association.status='active'
       AND association.effective_from<=header.invoice_date
       AND (association.effective_to IS NULL OR association.effective_to>=header.invoice_date);
    IF registration_scope_count<>1 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='document requires exactly one effective branch registration association'; END IF;
    PERFORM 1 FROM tax.registration_branches association
     WHERE association.org_id=organization_id AND association.registration_id=header.seller_tax_registration_id
       AND association.branch_id=header.branch_id AND association.status='active'
       AND association.effective_from<=header.invoice_date
       AND (association.effective_to IS NULL OR association.effective_to>=header.invoice_date) FOR SHARE;
    SELECT min(version.effective_from) INTO tax_effective FROM sales.invoice_lines tax_line JOIN tax.tax_code_versions version ON version.id=tax_line.tax_code_version_id
      WHERE tax_line.org_id=organization_id AND tax_line.invoice_id=resource_id
        AND ((version.org_id IS NULL AND version.status='active') OR
             (version.org_id=organization_id AND version.product_id=tax_line.product_id
              AND tax_line.line_kind='product' AND version.status='source_snapshot'
              AND EXISTS (SELECT 1 FROM erp_automation_reads.resolve_product_tax(
                  organization_id,tax_line.product_id,header.invoice_date) resolved_tax WHERE resolved_tax.id=version.id)))
        AND version.effective_from<=header.invoice_date AND (version.effective_to IS NULL OR version.effective_to>=header.invoice_date)
      HAVING erp_automation_reads.tax_ruleset_fingerprint(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
               'tax_code_version_id',version.id,'ruleset_version',version.ruleset_version)))=header.calculation_ruleset_version
        AND count(*)=(SELECT count(*) FROM sales.invoice_lines expected WHERE expected.org_id=organization_id AND expected.invoice_id=resource_id);
    IF tax_effective IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='invoice tax versions or document fingerprint are not valid'; END IF;

    SELECT EXISTS(SELECT 1 FROM sales.invoice_lines invoice_product_line WHERE invoice_product_line.org_id=organization_id AND invoice_product_line.invoice_id=resource_id
                           AND invoice_product_line.line_kind='product' AND NOT EXISTS (
                             SELECT 1 FROM sales.invoice_dispatch_allocations allocation
                              WHERE allocation.org_id=invoice_product_line.org_id AND allocation.invoice_line_id=invoice_product_line.id)),
                 EXISTS(SELECT 1 FROM sales.invoice_dispatch_allocations allocation JOIN sales.invoice_lines invoice_line ON invoice_line.org_id=allocation.org_id AND invoice_line.id=allocation.invoice_line_id WHERE invoice_line.org_id=organization_id AND invoice_line.invoice_id=resource_id)
            INTO product_lines,allocated_lines;
        IF product_lines<>(inventory_document_id IS NOT NULL) THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='direct sales invoice inventory ownership mismatch'; END IF;
        IF allocated_lines AND EXISTS (
          SELECT 1 FROM sales.invoice_dispatch_allocations allocation
          JOIN sales.invoice_lines invoice_line ON invoice_line.org_id=allocation.org_id AND invoice_line.id=allocation.invoice_line_id
          WHERE invoice_line.org_id=organization_id AND invoice_line.invoice_id=resource_id
            AND (SELECT count(*) FROM inventory.inventory_document_lines inventory_line
                 JOIN inventory.inventory_documents inventory_document ON inventory_document.org_id=inventory_line.org_id AND inventory_document.id=inventory_line.inventory_document_id AND inventory_document.status='posted'
                 JOIN finance.accounting_events event ON event.org_id=inventory_document.org_id AND event.inventory_document_id=inventory_document.id AND event.event_type='inventory_valuation'
                 WHERE inventory_line.org_id=allocation.org_id AND inventory_line.sales_dispatch_line_id=allocation.dispatch_line_id)<>1
        ) THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='allocated dispatch lacks exactly one posted inventory-valuation accounting event'; END IF;
        IF inventory_document_id IS NOT NULL THEN
          PERFORM erp_commercial_commands.post_owned_inventory_document(
            organization_id,inventory_document_id,actor_id,'sales_invoice',resource_id,header.branch_id);
          SELECT coalesce(sum(-entry.value_delta),0),count(*) INTO inventory_value,inventory_entries FROM inventory.stock_ledger_entries entry WHERE entry.org_id=organization_id AND entry.inventory_document_id=inventory_document_id AND entry.entry_kind='issue';
          IF inventory_entries=0 OR inventory_value<=0 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='posted sales issue has no authoritative ledger value'; END IF;
        END IF;
    consumed:=erp_calculation_authority.consume_artifact(organization_id,artifact_id,'sales.invoice.post','sales_invoice',resource_id,
      header.row_version,request_id,command_request_id,claim_id);
    IF pg_catalog.convert_from(consumed,'UTF8')::jsonb IS DISTINCT FROM output_doc THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='consumed calculation changed'; END IF;

    INSERT INTO finance.journal_entries(org_id,id,journal_number,posting_date,description,transaction_currency,functional_currency,fx_rate,
      transaction_debit_total,transaction_credit_total,functional_debit_total,functional_credit_total,status,created_by_membership_id,updated_by_membership_id)
    VALUES(organization_id,journal_id,journal_number,header.invoice_date,'sales_invoice',header.currency_code,'INR',1,
      header.grand_total,header.grand_total,header.grand_total,header.grand_total,'draft',actor_id,actor_id);
    PERFORM "erp_commercial_commands".add_journal_line(organization_id,journal_id,1,party_account,header.branch_id,party_id,
      'Customer receivable',header.grand_total,0,actor_id);
    FOR line IN SELECT * FROM sales.invoice_lines WHERE org_id=organization_id AND invoice_id=resource_id ORDER BY line_number,id LOOP
        PERFORM "erp_commercial_commands".assert_line_account(organization_id,line.revenue_account_id,'income',header.currency_code);
        PERFORM "erp_commercial_commands".add_journal_line(organization_id,journal_id,line_no,line.revenue_account_id,header.branch_id,NULL,
          'Invoice net value',0,line.net_value_amount,actor_id); line_no:=line_no+1;
    END LOOP;
    IF inventory_value>0 THEN
      role_account:=erp_commercial_commands.resolve_role_account(organization_id,header.branch_id,'cost_of_goods_sold','expense',header.currency_code,false);
      PERFORM erp_commercial_commands.add_journal_line(organization_id,journal_id,line_no,role_account,header.branch_id,NULL,'COGS from posted stock ledger',inventory_value,0,actor_id); line_no:=line_no+1;
      role_account:=erp_commercial_commands.resolve_role_account(organization_id,header.branch_id,'inventory_asset','asset',header.currency_code,false);
      PERFORM erp_commercial_commands.add_journal_line(organization_id,journal_id,line_no,role_account,header.branch_id,NULL,'Inventory issue from posted stock ledger',0,inventory_value,actor_id); line_no:=line_no+1;
    END IF;
    FOR role_key,component_amount IN SELECT * FROM (VALUES
      ('output_cgst'::varchar,header.cgst_total),
      ('output_sgst'::varchar,header.sgst_total),
      ('output_igst'::varchar,header.igst_total),
      ('output_cess'::varchar,header.cess_total)) AS component(role_key,amount)
    LOOP
      IF component_amount>0 AND header.tax_charge_mechanism='normal' THEN
        role_account:="erp_commercial_commands".resolve_role_account(organization_id,header.branch_id,role_key,'liability',header.currency_code,false);
        PERFORM "erp_commercial_commands".add_journal_line(organization_id,journal_id,line_no,role_account,header.branch_id,NULL,'Output tax',0,component_amount,actor_id); line_no:=line_no+1;
      END IF;
    END LOOP;
    
    
    IF header.rounding_adjustment<>0 THEN
      role_key:=CASE WHEN header.rounding_adjustment>0 THEN 'rounding_gain' ELSE 'rounding_loss' END;
      role_account:=erp_commercial_commands.resolve_role_account(organization_id,header.branch_id,role_key,CASE WHEN role_key='rounding_gain' THEN 'income' ELSE 'expense' END,header.currency_code,false);
      PERFORM erp_commercial_commands.add_journal_line(organization_id,journal_id,line_no,role_account,header.branch_id,NULL,'Signed rounding adjustment',
        CASE WHEN header.rounding_adjustment<0 THEN abs(header.rounding_adjustment) ELSE 0 END,
        CASE WHEN header.rounding_adjustment>0 THEN abs(header.rounding_adjustment) ELSE 0 END,actor_id); line_no:=line_no+1;
    END IF;
    SELECT coalesce(sum(transaction_debit),0),coalesce(sum(transaction_credit),0) INTO total_debit,total_credit
      FROM finance.journal_lines WHERE org_id=organization_id AND journal_entry_id=journal_id;
    IF total_debit<>total_credit OR total_debit=0 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='commercial journal does not exactly balance'; END IF;
    UPDATE finance.journal_entries SET transaction_debit_total=total_debit,transaction_credit_total=total_credit,
      functional_debit_total=total_debit,functional_credit_total=total_credit,status='posted',posted_at=posted_time,posted_by_membership_id=actor_id,
      updated_at=posted_time,updated_by_membership_id=actor_id,row_version=row_version+1 WHERE org_id=organization_id AND id=journal_id;
    UPDATE sales.invoices SET status='posted',posted_at=posted_time,posted_by_membership_id=actor_id,
      updated_at=posted_time,updated_by_membership_id=actor_id,row_version=row_version+1 WHERE org_id=organization_id AND id=resource_id AND status='draft';
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='invoice posting state changed'; END IF;
    NULL;
    SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(source_line) ORDER BY source_line.line_number,source_line.id) INTO line_snapshot
      FROM sales.invoice_lines source_line WHERE source_line.org_id=organization_id AND source_line.invoice_id=resource_id;
    source_hash:=extensions.digest(pg_catalog.convert_to((pg_catalog.to_jsonb(header)||pg_catalog.jsonb_build_object('lines',line_snapshot,'artifact',pg_catalog.encode(artifact.output_sha256,'hex')))::text,'UTF8'),'sha256');
    INSERT INTO tax.documents(org_id,id,registration_id,sales_invoice_id,document_class,document_number,document_date,direction,
      counterparty_party_id,counterparty_gstin,place_of_supply_state_code,supply_type,zero_rated_payment_mode,tax_charge_mechanism,
      tax_liability_party,document_effect,currency_code,net_value_amount,gst_taxable_value,cgst_amount,sgst_amount,igst_amount,cess_amount,
      self_assessed_tax_amount,rounding_adjustment,counterparty_payable_amount,tax_ruleset_version,tax_ruleset_effective_date,source_hash,posted_at,created_by_membership_id)
    VALUES(organization_id,tax_document_id,header.seller_tax_registration_id,resource_id,'sales_invoice',header.invoice_number,header.invoice_date,'outward',
      party_id,header.buyer_gstin_snapshot,header.place_of_supply_state_code,header.supply_type,header.zero_rated_payment_mode,header.tax_charge_mechanism,
      CASE WHEN header.tax_charge_mechanism='normal' THEN 'supplier' ELSE 'recipient' END,'original',header.currency_code,
      header.net_value_total,header.gst_taxable_total,header.cgst_total,header.sgst_total,header.igst_total,header.cess_total,
      CASE WHEN 'outward'='inward' AND header.tax_charge_mechanism='reverse_charge' THEN header.recipient_assessed_tax_total ELSE 0 END,
      header.rounding_adjustment,header.grand_total,header.calculation_ruleset_version,tax_effective,source_hash,posted_time,actor_id);
    INSERT INTO finance.accounting_events(org_id,id,event_type,sales_invoice_id,journal_entry_id,occurred_at,source_posted_at,created_by_membership_id)
    VALUES(organization_id,event_id,'sales_invoice',resource_id,journal_id,posted_time,posted_time,actor_id);
    INSERT INTO finance.open_items(org_id,id,accounting_event_id,party_id,item_side,document_number,document_date,due_date,currency_code,
      principal_amount,functional_principal_amount,status,created_by_membership_id)
    VALUES(organization_id,open_item_id,event_id,party_id,'receivable',header.invoice_number,header.invoice_date,
      coalesce(header.due_date,header.invoice_date),header.currency_code,header.grand_total,header.grand_total,'open',actor_id);
    PERFORM erp_trade_commands.finish_claim(organization_id,claim_id,'sales.invoices',resource_id);
    RETURN resource_id;
END
$function$;

CREATE OR REPLACE FUNCTION "erp_commercial_commands"."assert_sales_return_artifact"(organization_id uuid, resource_id uuid, input_doc jsonb, output_doc jsonb)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
DECLARE header sales.returns%ROWTYPE; original sales.invoices%ROWTYPE;
        expected_lines bigint; bad_count bigint; cumulative_grand numeric(20,2); cumulative_rounding numeric(20,2);
BEGIN
    SELECT * INTO STRICT header FROM sales.returns WHERE org_id=organization_id AND id=resource_id FOR UPDATE;
    IF header.status NOT IN ('draft','approved','posted') THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='return is not postable or posted'; END IF;
    SELECT * INTO STRICT original FROM sales.invoices WHERE org_id=organization_id AND id=header.invoice_id FOR UPDATE;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(organization_id::text||original.id::text,734821));
    IF true AND original.calculation_ruleset_version IS DISTINCT FROM (
      SELECT erp_automation_reads.tax_ruleset_fingerprint(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
               'tax_code_version_id',version.id,'ruleset_version',version.ruleset_version)))
        FROM sales.invoice_lines original_line
        JOIN tax.tax_code_versions version ON version.id=original_line.tax_code_version_id
       WHERE original_line.org_id=organization_id
         AND original_line.invoice_id=original.id
    ) THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='return original invoice tax fingerprint differs';
    END IF;
    PERFORM erp_calculation_authority.assert_input_schema(input_doc);
    PERFORM erp_calculation_authority.assert_output_schema(output_doc);
    IF input_doc->>'calculation_kind'<>'reversal' OR input_doc->>'operation'<>'sales.return.post'
       OR input_doc#>>'{reversal,gst_tax_treatment}' IS DISTINCT FROM header.gst_tax_treatment
       OR output_doc->>'gst_tax_treatment' IS DISTINCT FROM header.gst_tax_treatment
       OR input_doc->>'resource_type'<>'sales_return' OR input_doc->>'resource_id'<>resource_id::text
       OR (input_doc->>'aggregate_version')::bigint IS DISTINCT FROM
          (CASE WHEN header.status='posted' THEN header.row_version-1 ELSE header.row_version END)
       OR output_doc->>'operation'<>'sales.return.post' OR output_doc->>'resource_type'<>'sales_return'
       OR output_doc->>'resource_id'<>resource_id::text
       OR (output_doc->>'aggregate_version')::bigint IS DISTINCT FROM
          (CASE WHEN header.status='posted' THEN header.row_version-1 ELSE header.row_version END)
       OR output_doc->>'ruleset_version' IS DISTINCT FROM header.calculation_ruleset_version
       OR ROW((output_doc#>>'{totals,net_value_total}')::numeric,(output_doc#>>'{totals,gst_taxable_total}')::numeric,
              (output_doc#>>'{totals,cgst_total}')::numeric,(output_doc#>>'{totals,sgst_total}')::numeric,
              (output_doc#>>'{totals,igst_total}')::numeric,(output_doc#>>'{totals,cess_total}')::numeric,
              (output_doc#>>'{totals,recipient_assessed_tax_total}')::numeric,(output_doc#>>'{totals,rounding_adjustment}')::numeric,
              (output_doc#>>'{totals,grand_total}')::numeric)
          IS DISTINCT FROM ROW(header.net_value_total,header.gst_taxable_total,header.cgst_total,header.sgst_total,
              header.igst_total,header.cess_total,header.recipient_assessed_tax_total,header.rounding_adjustment,header.grand_total)
       OR (true AND (header.customer_account_id IS DISTINCT FROM original.customer_account_id OR
           header.zero_rated_payment_mode IS DISTINCT FROM original.zero_rated_payment_mode
           OR header.tax_charge_mechanism IS DISTINCT FROM original.tax_charge_mechanism
           OR header.rounding_policy IS DISTINCT FROM original.rounding_policy
           OR header.calculation_ruleset_version IS DISTINCT FROM original.calculation_ruleset_version
           OR input_doc#>>'{original,resource_id}' IS DISTINCT FROM original.id::text
           OR ROW((input_doc#>>'{original,totals,net_value_total}')::numeric,(input_doc#>>'{original,totals,gst_taxable_total}')::numeric,
                  (input_doc#>>'{original,totals,cgst_total}')::numeric,(input_doc#>>'{original,totals,sgst_total}')::numeric,
                  (input_doc#>>'{original,totals,igst_total}')::numeric,(input_doc#>>'{original,totals,cess_total}')::numeric,
                  (input_doc#>>'{original,totals,rounding_adjustment}')::numeric,(input_doc#>>'{original,totals,grand_total}')::numeric)
              IS DISTINCT FROM ROW(original.net_value_total,original.gst_taxable_total,original.cgst_total,original.sgst_total,
                  original.igst_total,original.cess_total,original.rounding_adjustment,original.grand_total))) THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='return artifact header or original snapshot differs';
    END IF;
    SELECT count(*) INTO expected_lines FROM sales.return_lines WHERE org_id=organization_id AND return_id=resource_id;
    IF expected_lines=0 OR pg_catalog.jsonb_array_length(input_doc#>'{reversal,products}')<>expected_lines
       OR pg_catalog.jsonb_array_length(input_doc#>'{reversal,charges}')<>0
       OR pg_catalog.jsonb_array_length(output_doc->'lines')<>expected_lines THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='return artifact line cardinality differs';
    END IF;
    WITH reversal_input AS (SELECT value item FROM pg_catalog.jsonb_array_elements(input_doc#>'{reversal,products}')),
         reversal_output AS (SELECT value item FROM pg_catalog.jsonb_array_elements(output_doc->'lines')),
         original_output AS (SELECT value item FROM pg_catalog.jsonb_array_elements(input_doc#>'{original,lines}'))
    SELECT count(*) INTO bad_count
      FROM sales.return_lines line
      LEFT JOIN sales.invoice_dispatch_allocations allocation ON allocation.org_id=line.org_id AND allocation.id=line.invoice_dispatch_allocation_id LEFT JOIN sales.dispatch_lines dispatch_line ON dispatch_line.org_id=allocation.org_id AND dispatch_line.id=allocation.dispatch_line_id LEFT JOIN inventory.locations return_location ON return_location.org_id=line.org_id AND return_location.id=line.disposition_location_id
      LEFT JOIN sales.invoice_lines source ON source.org_id=line.org_id AND source.id=line.invoice_line_id AND source.invoice_id=header.invoice_id
      LEFT JOIN tax.tax_code_versions tax_version ON tax_version.id=line.tax_code_version_id
      LEFT JOIN reversal_input requested ON requested.item->>'line_id'=(line.invoice_line_id)::text
      LEFT JOIN reversal_output calculated ON calculated.item->>'line_id'=(line.invoice_line_id)::text
      LEFT JOIN original_output original_line ON original_line.item->>'line_id'=(line.invoice_line_id)::text
     WHERE line.org_id=organization_id AND line.return_id=resource_id
       AND (true) AND (requested.item IS NULL OR calculated.item IS NULL OR original_line.item IS NULL
         OR line.gst_tax_treatment IS DISTINCT FROM header.gst_tax_treatment
         OR requested.item->>'value_basis' IS DISTINCT FROM line.reversal_value_basis
         OR (requested.item->>'final_residual')::boolean IS DISTINCT FROM line.final_residual
         OR (requested.item->>'reversed_billed_quantity')::numeric IS DISTINCT FROM line.billed_quantity
         OR (requested.item->>'reversed_free_quantity')::numeric IS DISTINCT FROM line.free_quantity
         OR (requested.item->>'reversed_base_billed_quantity')::numeric IS DISTINCT FROM line.base_billed_quantity
         OR (requested.item->>'reversed_base_free_quantity')::numeric IS DISTINCT FROM line.base_free_quantity
         OR ROW((calculated.item->>'net_value_amount')::numeric,(calculated.item->>'gst_taxable_value')::numeric,
                (calculated.item->>'cgst_rate')::numeric,(calculated.item->>'sgst_rate')::numeric,
                (calculated.item->>'igst_rate')::numeric,(calculated.item->>'cess_rate')::numeric,
                (calculated.item->>'cgst_amount')::numeric,(calculated.item->>'sgst_amount')::numeric,
                (calculated.item->>'igst_amount')::numeric,(calculated.item->>'cess_amount')::numeric,
                (calculated.item->>'line_total')::numeric,(calculated.item->>'final_residual')::boolean)
           IS DISTINCT FROM ROW(line.net_value_amount,line.gst_taxable_value,line.cgst_rate,line.sgst_rate,line.igst_rate,
                line.cess_rate,line.cgst_amount,line.sgst_amount,line.igst_amount,line.cess_amount,line.line_total,line.final_residual)
         OR ROW((original_line.item->>'net_value_amount')::numeric,(original_line.item->>'gst_taxable_value')::numeric,
                (original_line.item->>'cgst_rate')::numeric,(original_line.item->>'sgst_rate')::numeric,
                (original_line.item->>'igst_rate')::numeric,(original_line.item->>'cess_rate')::numeric,
                (original_line.item->>'cgst_amount')::numeric,(original_line.item->>'sgst_amount')::numeric,
                (original_line.item->>'igst_amount')::numeric,(original_line.item->>'cess_amount')::numeric,
                (original_line.item->>'line_total')::numeric)
           IS DISTINCT FROM ROW(source.net_value_amount,source.gst_taxable_value,source.cgst_rate,source.sgst_rate,source.igst_rate,
                source.cess_rate,source.cgst_amount,source.sgst_amount,source.igst_amount,source.cess_amount,source.line_total)
         
         OR source.id IS NULL
         OR source.product_id IS DISTINCT FROM line.product_id
         OR source.uom_conversion_factor IS DISTINCT FROM line.uom_conversion_factor
         OR source.quoted_unit_rate IS DISTINCT FROM line.quoted_unit_rate
         OR source.price_basis IS DISTINCT FROM line.price_basis
         OR source.free_supply_tax_treatment IS DISTINCT FROM line.free_supply_tax_treatment
         OR source.tax_classification_code_snapshot IS DISTINCT FROM line.hsn_code_snapshot
         OR source.tax_charge_mechanism IS DISTINCT FROM line.tax_charge_mechanism
         OR source.tax_code_version_id IS DISTINCT FROM line.tax_code_version_id
         OR source.taxability_snapshot IS DISTINCT FROM line.taxability_snapshot
         OR tax_version.id IS NULL
         OR (tax_version.org_id IS NOT NULL AND (
              tax_version.org_id IS DISTINCT FROM organization_id
              OR tax_version.product_id IS DISTINCT FROM line.product_id))
         OR original.invoice_date<tax_version.effective_from
         OR (tax_version.effective_to IS NOT NULL AND original.invoice_date>tax_version.effective_to)
         
         OR return_location.id IS NULL OR return_location.branch_id IS DISTINCT FROM header.branch_id OR return_location.status<>'active'
         OR (line.invoice_dispatch_allocation_id IS NOT NULL AND
             (allocation.invoice_line_id IS DISTINCT FROM line.invoice_line_id
              OR ROW(dispatch_line.product_id,dispatch_line.batch_id,dispatch_line.uom_code)
                 IS DISTINCT FROM ROW(line.product_id,line.batch_id,source.uom_code)
              OR NOT EXISTS (
                SELECT 1 FROM inventory.inventory_document_lines issued_line
                JOIN inventory.inventory_documents issued_document
                  ON issued_document.org_id=issued_line.org_id AND issued_document.id=issued_line.inventory_document_id
               WHERE issued_line.org_id=line.org_id AND issued_line.sales_dispatch_line_id=dispatch_line.id
                 AND issued_document.sales_dispatch_id=dispatch_line.dispatch_id
                 AND issued_document.document_type='sales_issue' AND issued_document.status='posted'
                 AND ROW(issued_line.product_id,issued_line.batch_id,issued_line.uom_code)
                   IS NOT DISTINCT FROM ROW(line.product_id,line.batch_id,source.uom_code))))
         OR (line.invoice_dispatch_allocation_id IS NULL AND
             (EXISTS (SELECT 1 FROM sales.invoice_dispatch_allocations allocated
                       WHERE allocated.org_id=line.org_id AND allocated.invoice_line_id=line.invoice_line_id)
              OR NOT EXISTS (
                SELECT 1 FROM inventory.inventory_document_lines issued_line
                JOIN inventory.inventory_documents issued_document
                  ON issued_document.org_id=issued_line.org_id AND issued_document.id=issued_line.inventory_document_id
               WHERE issued_line.org_id=line.org_id AND issued_line.sales_invoice_line_id=line.invoice_line_id
                 AND issued_document.sales_invoice_id=header.invoice_id
                 AND issued_document.document_type='sales_issue' AND issued_document.status='posted'
                 AND ROW(issued_line.product_id,issued_line.batch_id,issued_line.uom_code)
                   IS NOT DISTINCT FROM ROW(line.product_id,line.batch_id,source.uom_code))))
         OR line.base_billed_quantity>source.base_billed_quantity OR line.base_free_quantity>source.base_free_quantity);
    IF bad_count<>0 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='return artifact line differs from locked original'; END IF;
    
    SELECT count(*) INTO bad_count FROM (
          SELECT current.invoice_line_id source_id,max(source.base_billed_quantity) source_billed,max(source.base_free_quantity) source_free,
                 sum(all_returns.base_billed_quantity) reversed_billed,sum(all_returns.base_free_quantity) reversed_free,
                 sum(all_returns.net_value_amount) reversed_net,sum(all_returns.gst_taxable_value) reversed_taxable,
                 sum(all_returns.cgst_amount) reversed_cgst,sum(all_returns.sgst_amount) reversed_sgst,
                 sum(all_returns.igst_amount) reversed_igst,sum(all_returns.cess_amount) reversed_cess,sum(all_returns.line_total) reversed_total,
                 max(source.net_value_amount) source_net,max(source.gst_taxable_value) source_taxable,max(source.cgst_amount) source_cgst,
                 max(source.sgst_amount) source_sgst,max(source.igst_amount) source_igst,max(source.cess_amount) source_cess,max(source.line_total) source_total,
                 bool_or(current.final_residual) final_residual
            FROM sales.return_lines current
            JOIN sales.invoice_lines source ON source.org_id=current.org_id AND source.id=current.invoice_line_id
            JOIN sales.return_lines all_returns ON all_returns.org_id=current.org_id AND all_returns.invoice_line_id=current.invoice_line_id
            JOIN sales.returns prior_header ON prior_header.org_id=all_returns.org_id AND prior_header.id=all_returns.return_id
           WHERE current.org_id=organization_id AND current.return_id=resource_id
             AND (prior_header.status='posted' OR prior_header.id=resource_id)
           GROUP BY current.invoice_line_id
        ) cumulative WHERE reversed_billed>source_billed OR reversed_free>source_free
           OR reversed_taxable>source_taxable OR reversed_cgst>source_cgst OR reversed_sgst>source_sgst
           OR reversed_igst>source_igst OR reversed_cess>source_cess OR reversed_total>source_total
           OR (final_residual AND (reversed_billed<>source_billed OR reversed_free<>source_free OR reversed_total<>source_total));
        IF bad_count=0 THEN
          SELECT count(*) INTO bad_count FROM (
            SELECT current.invoice_dispatch_allocation_id allocation_id,max(allocation.allocated_base_billed_quantity) source_billed,
                   max(allocation.allocated_base_free_quantity) source_free,sum(all_returns.base_billed_quantity) reversed_billed,sum(all_returns.base_free_quantity) reversed_free
              FROM sales.return_lines current
              JOIN sales.invoice_dispatch_allocations allocation ON allocation.org_id=current.org_id AND allocation.id=current.invoice_dispatch_allocation_id
              JOIN sales.return_lines all_returns ON all_returns.org_id=allocation.org_id AND all_returns.invoice_dispatch_allocation_id=allocation.id
              JOIN sales.returns prior_header ON prior_header.org_id=all_returns.org_id AND prior_header.id=all_returns.return_id
             WHERE current.org_id=organization_id AND current.return_id=resource_id AND (prior_header.status='posted' OR prior_header.id=resource_id)
             GROUP BY current.invoice_dispatch_allocation_id
          ) allocation_total WHERE reversed_billed>source_billed OR reversed_free>source_free;
        END IF;
        IF bad_count=0 THEN
          SELECT count(*) INTO bad_count FROM (
            SELECT current.invoice_line_id,current.batch_id,
                   max(issued.issued_base_quantity) issued_base_quantity,
                   sum(all_returns.base_billed_quantity+all_returns.base_free_quantity) returned_base_quantity
              FROM sales.return_lines current
              JOIN LATERAL (
                SELECT sum(issue_line.base_quantity) issued_base_quantity
                  FROM inventory.inventory_document_lines issue_line
                  JOIN inventory.inventory_documents issue_document
                    ON issue_document.org_id=issue_line.org_id AND issue_document.id=issue_line.inventory_document_id
                 WHERE issue_line.org_id=current.org_id AND issue_line.sales_invoice_line_id=current.invoice_line_id
                   AND issue_line.batch_id=current.batch_id AND issue_document.sales_invoice_id=header.invoice_id
                   AND issue_document.document_type='sales_issue' AND issue_document.status='posted'
              ) issued ON true
              JOIN sales.return_lines all_returns ON all_returns.org_id=current.org_id
                AND all_returns.invoice_line_id=current.invoice_line_id AND all_returns.batch_id=current.batch_id
                AND all_returns.invoice_dispatch_allocation_id IS NULL
              JOIN sales.returns prior_header ON prior_header.org_id=all_returns.org_id AND prior_header.id=all_returns.return_id
             WHERE current.org_id=organization_id AND current.return_id=resource_id
               AND current.invoice_dispatch_allocation_id IS NULL
               AND (prior_header.status='posted' OR prior_header.id=resource_id)
             GROUP BY current.invoice_line_id,current.batch_id
          ) direct_batch WHERE issued_base_quantity IS NULL OR returned_base_quantity>issued_base_quantity;
        END IF;
        IF bad_count<>0 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='cumulative sales return exceeds original or final residual is incomplete'; END IF;
    WITH current_sources AS (
             SELECT DISTINCT invoice_line_id source_id FROM sales.return_lines
              WHERE org_id=organization_id AND return_id=resource_id
           ), returned AS (
             SELECT line.invoice_line_id source_id,sum(line.base_billed_quantity) billed,sum(line.base_free_quantity) free,
                    sum(line.net_value_amount) net,sum(line.gst_taxable_value) taxable,sum(line.cgst_amount) cgst,
                    sum(line.sgst_amount) sgst,sum(line.igst_amount) igst,sum(line.cess_amount) cess,sum(line.line_total) total
               FROM sales.return_lines line JOIN sales.returns parent ON parent.org_id=line.org_id AND parent.id=line.return_id
               JOIN current_sources current ON current.source_id=line.invoice_line_id
              WHERE line.org_id=organization_id AND (parent.status='posted' OR parent.id=resource_id) GROUP BY line.invoice_line_id
           ), adjusted AS (
             SELECT line.sales_invoice_line_id source_id,
                    sum((CASE WHEN note.document_effect='increase' THEN 1 ELSE -1 END)*line.base_billed_quantity) billed,
                    sum((CASE WHEN note.document_effect='increase' THEN 1 ELSE -1 END)*line.base_free_quantity) free,
                    sum((CASE WHEN note.document_effect='increase' THEN 1 ELSE -1 END)*line.net_value_amount) net,
                    sum((CASE WHEN note.document_effect='increase' THEN 1 ELSE -1 END)*line.gst_taxable_value) taxable,
                    sum((CASE WHEN note.document_effect='increase' THEN 1 ELSE -1 END)*line.cgst_amount) cgst,
                    sum((CASE WHEN note.document_effect='increase' THEN 1 ELSE -1 END)*line.sgst_amount) sgst,
                    sum((CASE WHEN note.document_effect='increase' THEN 1 ELSE -1 END)*line.igst_amount) igst,
                    sum((CASE WHEN note.document_effect='increase' THEN 1 ELSE -1 END)*line.cess_amount) cess,
                    sum((CASE WHEN note.document_effect='increase' THEN 1 ELSE -1 END)*line.line_total) total
               FROM finance.adjustment_note_lines line JOIN finance.adjustment_notes note ON note.org_id=line.org_id AND note.id=line.adjustment_note_id
               JOIN current_sources current ON current.source_id=line.sales_invoice_line_id
              WHERE line.org_id=organization_id AND note.status='posted' AND note.sales_return_id IS NULL AND note.purchase_return_id IS NULL
              GROUP BY line.sales_invoice_line_id
           )
           SELECT count(*) INTO bad_count FROM current_sources current JOIN sales.invoice_lines source ON source.org_id=organization_id AND source.id=current.source_id
             JOIN returned ON returned.source_id=current.source_id LEFT JOIN adjusted ON adjusted.source_id=current.source_id
            WHERE coalesce(adjusted.billed,0)-returned.billed < -source.base_billed_quantity
               OR coalesce(adjusted.free,0)-returned.free < -source.base_free_quantity
               OR coalesce(adjusted.net,0)-returned.net < -source.net_value_amount
               OR coalesce(adjusted.taxable,0)-returned.taxable < -source.gst_taxable_value
               OR coalesce(adjusted.cgst,0)-returned.cgst < -source.cgst_amount OR coalesce(adjusted.sgst,0)-returned.sgst < -source.sgst_amount
               OR coalesce(adjusted.igst,0)-returned.igst < -source.igst_amount OR coalesce(adjusted.cess,0)-returned.cess < -source.cess_amount
               OR coalesce(adjusted.total,0)-returned.total < -source.line_total;
           IF bad_count<>0 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='combined sales returns and generic adjustments exceed the original invoice'; END IF;
    SELECT coalesce(sum(prior.grand_total),0),coalesce(sum(prior.rounding_adjustment),0) INTO cumulative_grand,cumulative_rounding
             FROM sales.returns prior WHERE prior.org_id=organization_id AND prior.invoice_id=header.invoice_id
               AND (prior.status='posted' OR prior.id=resource_id);
           IF cumulative_grand>original.grand_total OR (original.rounding_adjustment>=0 AND (cumulative_rounding<0 OR cumulative_rounding>original.rounding_adjustment))
              OR (original.rounding_adjustment<0 AND (cumulative_rounding>0 OR cumulative_rounding<original.rounding_adjustment)) THEN
             RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='cumulative sales return header exceeds original invoice'; END IF;
    SELECT count(*) INTO bad_count FROM finance.adjustment_note_lines adjustment_line
             JOIN finance.adjustment_notes adjustment ON adjustment.org_id=adjustment_line.org_id AND adjustment.id=adjustment_line.adjustment_note_id
             JOIN sales.return_lines current ON current.org_id=adjustment_line.org_id AND current.invoice_line_id=adjustment_line.sales_invoice_line_id
            WHERE current.org_id=organization_id AND current.return_id=resource_id AND adjustment.status='posted'
              AND adjustment.sales_return_id IS NULL AND adjustment.purchase_return_id IS NULL;
           IF bad_count<>0 THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='return after a generic adjustment is blocked because the reversal artifact cannot encode an adjusted original basis'; END IF;
           WITH current_sources AS (
             SELECT DISTINCT line.invoice_line_id source_id FROM sales.return_lines line
              WHERE line.org_id=organization_id AND line.return_id=resource_id
           ), prior_rows AS (
             SELECT line.invoice_line_id source_id,line.reversal_value_basis,line.billed_quantity,line.free_quantity,
                    line.base_billed_quantity,line.base_free_quantity,calculated.item
               FROM sales.return_lines line
               JOIN current_sources current ON current.source_id=line.invoice_line_id
               JOIN sales.returns prior ON prior.org_id=line.org_id AND prior.id=line.return_id AND prior.status='posted' AND prior.id<>resource_id
               JOIN calculation.artifacts artifact ON artifact.org_id=prior.org_id AND artifact.sales_return_id=prior.id AND artifact.status='consumed'
               JOIN LATERAL pg_catalog.jsonb_array_elements(pg_catalog.convert_from(artifact.output_bytes,'UTF8')::jsonb->'lines') calculated(item)
                 ON calculated.item->>'line_id'=line.invoice_line_id::text
              WHERE line.org_id=organization_id AND prior.invoice_id=header.invoice_id
           ), expected AS (
             SELECT source_id,min(reversal_value_basis) value_basis,count(DISTINCT reversal_value_basis) basis_count,
                    sum(billed_quantity) billed_quantity,sum(free_quantity) free_quantity,sum(base_billed_quantity) base_billed_quantity,
                    sum(base_free_quantity) base_free_quantity,sum((item->>'gross_amount')::numeric) gross_amount,
                    sum((item->>'line_discount_amount')::numeric) line_discount_amount,
                    sum((item->>'document_discount_amount')::numeric) document_discount_amount,
                    sum((item->>'net_value_amount')::numeric) net_value_amount,sum((item->>'gst_taxable_value')::numeric) gst_taxable_value,
                    sum((item->>'cgst_amount')::numeric) cgst_amount,sum((item->>'sgst_amount')::numeric) sgst_amount,
                    sum((item->>'igst_amount')::numeric) igst_amount,sum((item->>'cess_amount')::numeric) cess_amount
               FROM prior_rows GROUP BY source_id
           ), provided AS (SELECT value item FROM pg_catalog.jsonb_array_elements(input_doc#>'{reversal,prior_state,products}'))
           SELECT count(*) INTO bad_count FROM expected FULL JOIN provided ON provided.item->>'line_id'=expected.source_id::text
            WHERE expected.source_id IS NULL OR provided.item IS NULL OR expected.basis_count<>1
               OR provided.item->>'value_basis' IS DISTINCT FROM expected.value_basis
               OR ROW((provided.item->>'reversed_billed_quantity')::numeric,(provided.item->>'reversed_free_quantity')::numeric,
                      (provided.item->>'reversed_base_billed_quantity')::numeric,(provided.item->>'reversed_base_free_quantity')::numeric,
                      (provided.item->>'gross_price_amount')::numeric,(provided.item->>'line_discount_amount')::numeric,
                      (provided.item->>'document_discount_amount')::numeric,(provided.item->>'net_value_amount')::numeric,
                      (provided.item->>'gst_taxable_value')::numeric,(provided.item->>'cgst_amount')::numeric,
                      (provided.item->>'sgst_amount')::numeric,(provided.item->>'igst_amount')::numeric,(provided.item->>'cess_amount')::numeric)
                  IS DISTINCT FROM ROW(expected.billed_quantity,expected.free_quantity,expected.base_billed_quantity,expected.base_free_quantity,
                      expected.gross_amount,expected.line_discount_amount,expected.document_discount_amount,expected.net_value_amount,
                      expected.gst_taxable_value,expected.cgst_amount,expected.sgst_amount,expected.igst_amount,expected.cess_amount);
           IF bad_count<>0 OR (input_doc#>>'{reversal,prior_state,rounding_adjustment}')::numeric IS DISTINCT FROM
              (SELECT coalesce(sum(prior.rounding_adjustment),0) FROM sales.returns prior WHERE prior.org_id=organization_id AND prior.invoice_id=header.invoice_id AND prior.status='posted' AND prior.id<>resource_id) THEN
             RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='artifact prior state differs from locked posted sales returns'; END IF;
END
$function$;

RESET ROLE;
